// GearSwap Atelier · hud_sources.js: GearSwap's HUD code (Lua) for the live preview of the Settings' Display
// (hud_preview.js). Written by scripts/atelier/gen_hud_sources.py at each build: never by hand.
const HUD_SOURCES = {"shared/config/ui_settings.lua": "---  ═══════════════════════════════════════════════════════════════════════════\r\n---   UI Settings - Persistent Configuration Storage (Per Character)\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n---   Global variables + file persistence for UI display settings.\r\n---   Settings persist within session AND across //lua reload gearswap.\r\n---\r\n---   Features:\r\n---     • Per-character settings ([CharName]/saved/ui_settings.lua)\r\n---     • Global variable storage (_G.UI_SETTINGS)\r\n---     • Auto-load from file on startup\r\n---     • Auto-save on every setting change\r\n---     • 19 configurable parameters (position, visibility, background, font, sections)\r\n---\r\n---   Architecture:\r\n---     • File persistence via dofile() and io.open()\r\n---     • Default settings if file doesn't exist\r\n---     • Getter/Setter functions for all settings\r\n---     • Automatic file generation with formatted output\r\n---\r\n---   Configuration Categories:\r\n---     • Position (pos_x, pos_y)\r\n---     • Visibility (enabled, show_header, show_legend, show_column_headers, show_footer)\r\n---     • Background (bg_r, bg_g, bg_b, bg_a, bg_visible)\r\n---     • Font (font_name, font_size)\r\n---     • Sections (section_spells, section_enhancing, section_job_abilities, section_weapons, section_modes)\r\n---\r\n---   Settings File:\r\n---     • [CharName]/saved/ui_settings.lua (one file per character)\r\n---\r\n---   @file    shared/config/ui_settings.lua\r\n---   @author  ejouanchicot\r\n---   @version 1.1 - Refactored with new header style\r\n---   @date    Updated: 2025-11-12\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n\r\nlocal UISettings = {}\r\n\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n---   DEFAULTS (single source of truth)\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n---   Read from _G.UIConfig if available, else hardcoded fallback. Computed once,\r\n---   on the first require in a sandbox. ConfigLoader.load_ui_config() sets\r\n---   _G.UIConfig right before it requires this module. Entries that require\r\n---   UI_MANAGER before config_loader (WAR, BST, PUP) reach this file first, so\r\n---   the fallback is used there. The fallback visibility flags match\r\n---   UI_CONFIG.lua, and so does the position (1600, 300).\r\n\r\nlocal function compute_defaults()\r\n    local uc  = _G.UIConfig or {}\r\n    local pos = uc.default_position or {}\r\n    local bg  = uc.background or {}\r\n    local txt = uc.text or {}\r\n    local sec = uc.sections or {}\r\n    return {\r\n        pos_x                 = pos.x or 1600,\r\n        pos_y                 = pos.y or 300,\r\n        enabled               = uc.enabled ~= false,\r\n        show_header           = uc.show_header == true,\r\n        show_legend           = uc.show_legend ~= false,\r\n        show_column_headers   = uc.show_column_headers == true,\r\n        show_footer           = uc.show_footer == true,\r\n        bg_r                  = bg.r or 15,\r\n        bg_g                  = bg.g or 15,\r\n        bg_b                  = bg.b or 35,\r\n        bg_a                  = bg.a or 180,\r\n        bg_visible            = bg.visible ~= false,\r\n        font_size             = txt.size or 10,\r\n        font_name             = txt.font or 'Consolas',\r\n        section_spells        = sec.spells ~= false,\r\n        section_enhancing     = sec.enhancing ~= false,\r\n        section_job_abilities = sec.job_abilities ~= false,\r\n        section_weapons       = sec.weapons ~= false,\r\n        section_modes         = sec.modes ~= false,\r\n    }\r\nend\r\n\r\nlocal D = compute_defaults()\r\n-- Whether D was read from the player's UI_CONFIG.lua (false: the fallback above, the file was not loaded yet)\r\nlocal FROM_CONFIG = type(rawget(_G, 'UIConfig')) == 'table'\r\n-- The settings in the order the file writes them (the seed block is written in the same order)\r\nlocal KEYS = {'pos_x', 'pos_y', 'enabled', 'show_header', 'show_legend', 'show_column_headers', 'show_footer',\r\n    'bg_r', 'bg_g', 'bg_b', 'bg_a', 'bg_visible', 'font_size', 'font_name',\r\n    'section_spells', 'section_enhancing', 'section_job_abilities', 'section_weapons', 'section_modes'}\r\n\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n---   FILE PERSISTENCE\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n\r\n--- Absolute path of the per-character settings file\r\n--- @return string Path to [CharName]/saved/ui_settings.lua\r\nlocal function get_settings_path()\r\n    return require('shared/utils/core/char_paths').writable('saved', 'ui_settings.lua')\r\nend\r\n\r\n--- Load settings from file\r\n--- @return table|nil Loaded settings or nil if file doesn't exist\r\nlocal function load_from_file()\r\n    local file_path = get_settings_path()\r\n\r\n    -- Use dofile() instead of loadfile() (GearSwap environment)\r\n    local success, settings = pcall(dofile, file_path)\r\n\r\n    if success and settings and type(settings) == 'table' then\r\n        return settings\r\n    end\r\n\r\n    return nil\r\nend\r\n\r\n--- Save settings to file\r\n--- @param settings table Settings to save\r\n--- @return boolean True if the file was written\r\nlocal function save_to_file(settings)\r\n    local file_path = get_settings_path()\r\n\r\n    local file = io.open(file_path, 'w')\r\n    if file then\r\n        file:write('-- UI Settings (auto-generated)\\n')\r\n        file:write('-- Character: ' .. (player and player.name or 'Unknown') .. '\\n')\r\n        file:write('-- File: ' .. file_path .. '\\n')\r\n        file:write('return {\\n')\r\n        file:write('    -- Position\\n')\r\n        file:write(string.format('    pos_x = %d,\\n', settings.pos_x or D.pos_x))\r\n        file:write(string.format('    pos_y = %d,\\n', settings.pos_y or D.pos_y))\r\n        file:write('\\n')\r\n        file:write('    -- Visibility\\n')\r\n        file:write(string.format('    enabled = %s,\\n', tostring(settings.enabled ~= false)))\r\n        file:write(string.format('    show_header = %s,\\n', tostring(settings.show_header == true)))\r\n        file:write(string.format('    show_legend = %s,\\n', tostring(settings.show_legend ~= false)))\r\n        file:write(string.format('    show_column_headers = %s,\\n', tostring(settings.show_column_headers == true)))\r\n        file:write(string.format('    show_footer = %s,\\n', tostring(settings.show_footer == true)))\r\n        file:write('\\n')\r\n        file:write('    -- Background\\n')\r\n        file:write(string.format('    bg_r = %d,\\n', settings.bg_r or D.bg_r))\r\n        file:write(string.format('    bg_g = %d,\\n', settings.bg_g or D.bg_g))\r\n        file:write(string.format('    bg_b = %d,\\n', settings.bg_b or D.bg_b))\r\n        file:write(string.format('    bg_a = %d,\\n', settings.bg_a or D.bg_a))\r\n        file:write(string.format('    bg_visible = %s,\\n', tostring(settings.bg_visible ~= false)))\r\n        file:write('\\n')\r\n        file:write('    -- Font\\n')\r\n        file:write(string.format('    font_size = %d,\\n', settings.font_size or D.font_size))\r\n        file:write(string.format('    font_name = \"%s\",\\n', settings.font_name or D.font_name))\r\n        file:write('\\n')\r\n        file:write('    -- Sections\\n')\r\n        file:write(string.format('    section_spells = %s,\\n', tostring(settings.section_spells ~= false)))\r\n        file:write(string.format('    section_enhancing = %s,\\n', tostring(settings.section_enhancing ~= false)))\r\n        file:write(string.format('    section_job_abilities = %s,\\n', tostring(settings.section_job_abilities ~= false)))\r\n        file:write(string.format('    section_weapons = %s,\\n', tostring(settings.section_weapons ~= false)))\r\n        file:write(string.format('    section_modes = %s,\\n', tostring(settings.section_modes ~= false)))\r\n        file:write('\\n')\r\n        -- What UI_CONFIG.lua said when these values were last lined up with it: a value that no longer\r\n        -- matches means the player changed UI_CONFIG.lua since, and that setting follows it at the next load\r\n        -- (none yet when UI_CONFIG.lua was not read at this load: written at the first load that reads it)\r\n        local seed = settings.seed or (_G.UI_SETTINGS and _G.UI_SETTINGS.seed)\r\n        if type(seed) == 'table' then\r\n            file:write('    -- UI_CONFIG.lua as last read (do not edit)\\n')\r\n            file:write('    seed = {\\n')\r\n            for _, key in ipairs(KEYS) do\r\n                local value = seed[key]\r\n                if value == nil then value = D[key] end\r\n                file:write(string.format('        %s = %s,\\n', key, type(value) == 'string' and string.format('%q', value) or tostring(value)))\r\n            end\r\n            file:write('    },\\n')\r\n        end\r\n        file:write('}\\n')\r\n        file:close()\r\n        return true\r\n    else\r\n        local MessageFormatter = require('shared/utils/messages/message_formatter')\r\n        MessageFormatter.show_error('[UI_SETTINGS] ERROR: Cannot write to ' .. file_path)\r\n        return false\r\n    end\r\nend\r\n\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n---   GLOBAL SETTINGS STORAGE\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n\r\n--- Line the saved settings up with UI_CONFIG.lua. The saved file wins (a change made in game with //gs c ui\r\n--- stays), except for a setting the player changed in UI_CONFIG.lua since the last load: that one follows the\r\n--- config, or an edit of the file (by hand, or from the Atelier page) would never show. A file saved before the\r\n--- seed existed only records it: nothing can tell what was changed where.\r\n--- @param settings table the saved settings (changed in place)\r\n--- @return boolean True when something was changed and must be written\r\nlocal function follow_config(settings)\r\n    if not FROM_CONFIG then return false end\r\n    if type(settings.seed) ~= 'table' then\r\n        settings.seed = {}\r\n        for _, key in ipairs(KEYS) do settings.seed[key] = D[key] end\r\n        return true\r\n    end\r\n    local changed = false\r\n    for _, key in ipairs(KEYS) do\r\n        if settings.seed[key] ~= D[key] then\r\n            settings[key] = D[key]\r\n            settings.seed[key] = D[key]\r\n            changed = true\r\n        end\r\n    end\r\n    return changed\r\nend\r\n\r\n-- ALWAYS try to load from file first (even if _G.UI_SETTINGS exists)\r\n-- This ensures settings persist across //lua reload gearswap\r\nlocal loaded = load_from_file()\r\n\r\nif loaded then\r\n    -- File exists, use it (overwrite any existing _G.UI_SETTINGS)\r\n    _G.UI_SETTINGS = loaded\r\n    if follow_config(loaded) then save_to_file(loaded) end\r\nelseif _G.UI_SETTINGS == nil then\r\n    -- No file AND no global variable: seed from defaults (read from UIConfig).\r\n    -- Shallow-copy D so subsequent mutations to _G.UI_SETTINGS don't leak\r\n    -- back into the module-local defaults table.\r\n    _G.UI_SETTINGS = {}\r\n    for k, v in pairs(D) do _G.UI_SETTINGS[k] = v end\r\n    if FROM_CONFIG then _G.UI_SETTINGS.seed = {} for k, v in pairs(D) do _G.UI_SETTINGS.seed[k] = v end end\r\n    save_to_file(_G.UI_SETTINGS)\r\nend\r\n-- If file doesn't exist but _G.UI_SETTINGS exists, keep the global (in-session changes)\r\n\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n---   SETTINGS ACCESS - Position\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n\r\n--- @return table {x, y} saved HUD position\r\nfunction UISettings.get_position()\r\n    return {\r\n        x = _G.UI_SETTINGS.pos_x or D.pos_x,\r\n        y = _G.UI_SETTINGS.pos_y or D.pos_y\r\n    }\r\nend\r\n\r\n--- Save the HUD position (floored to integers)\r\n--- @param x number\r\n--- @param y number\r\nfunction UISettings.set_position(x, y)\r\n    _G.UI_SETTINGS.pos_x = math.floor(x)\r\n    _G.UI_SETTINGS.pos_y = math.floor(y)\r\n    save_to_file(_G.UI_SETTINGS)\r\nend\r\n\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n---   SETTINGS ACCESS - Visibility\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n\r\n--- @return boolean True unless the HUD was explicitly disabled\r\nfunction UISettings.get_enabled()\r\n    return _G.UI_SETTINGS.enabled ~= false\r\nend\r\n\r\n--- @param value boolean\r\nfunction UISettings.set_enabled(value)\r\n    _G.UI_SETTINGS.enabled = value\r\n    save_to_file(_G.UI_SETTINGS)\r\nend\r\n\r\n--- @return boolean True only if explicitly enabled\r\nfunction UISettings.get_show_header()\r\n    return _G.UI_SETTINGS.show_header == true\r\nend\r\n\r\n--- @param value boolean\r\nfunction UISettings.set_show_header(value)\r\n    _G.UI_SETTINGS.show_header = value\r\n    save_to_file(_G.UI_SETTINGS)\r\nend\r\n\r\n--- @return boolean True unless explicitly disabled\r\nfunction UISettings.get_show_legend()\r\n    return _G.UI_SETTINGS.show_legend ~= false\r\nend\r\n\r\n--- @param value boolean\r\nfunction UISettings.set_show_legend(value)\r\n    _G.UI_SETTINGS.show_legend = value\r\n    save_to_file(_G.UI_SETTINGS)\r\nend\r\n\r\n--- @return boolean True only if explicitly enabled\r\nfunction UISettings.get_show_column_headers()\r\n    return _G.UI_SETTINGS.show_column_headers == true\r\nend\r\n\r\n--- @param value boolean\r\nfunction UISettings.set_show_column_headers(value)\r\n    _G.UI_SETTINGS.show_column_headers = value\r\n    save_to_file(_G.UI_SETTINGS)\r\nend\r\n\r\n--- @return boolean True only if explicitly enabled\r\nfunction UISettings.get_show_footer()\r\n    return _G.UI_SETTINGS.show_footer == true\r\nend\r\n\r\n--- @param value boolean\r\nfunction UISettings.set_show_footer(value)\r\n    _G.UI_SETTINGS.show_footer = value\r\n    save_to_file(_G.UI_SETTINGS)\r\nend\r\n\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n---   SETTINGS ACCESS - Background\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n\r\n--- @return table {r, g, b, a, visible}\r\nfunction UISettings.get_background()\r\n    return {\r\n        r = _G.UI_SETTINGS.bg_r or D.bg_r,\r\n        g = _G.UI_SETTINGS.bg_g or D.bg_g,\r\n        b = _G.UI_SETTINGS.bg_b or D.bg_b,\r\n        a = _G.UI_SETTINGS.bg_a or D.bg_a,\r\n        visible = _G.UI_SETTINGS.bg_visible ~= false\r\n    }\r\nend\r\n\r\n--- @param r number Red (0-255)\r\n--- @param g number Green (0-255)\r\n--- @param b number Blue (0-255)\r\n--- @param a number Alpha (0-255)\r\nfunction UISettings.set_background(r, g, b, a)\r\n    _G.UI_SETTINGS.bg_r = r\r\n    _G.UI_SETTINGS.bg_g = g\r\n    _G.UI_SETTINGS.bg_b = b\r\n    _G.UI_SETTINGS.bg_a = a\r\n    save_to_file(_G.UI_SETTINGS)\r\nend\r\n\r\n--- @param value boolean\r\nfunction UISettings.set_background_visible(value)\r\n    _G.UI_SETTINGS.bg_visible = value\r\n    save_to_file(_G.UI_SETTINGS)\r\nend\r\n\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n---   SETTINGS ACCESS - Font\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n\r\n--- @return table {size, name}\r\nfunction UISettings.get_font()\r\n    return {\r\n        size = _G.UI_SETTINGS.font_size or D.font_size,\r\n        name = _G.UI_SETTINGS.font_name or D.font_name\r\n    }\r\nend\r\n\r\n--- Save font settings; a nil argument leaves that field unchanged\r\n--- @param name string|nil Font name\r\n--- @param size number|nil Font size\r\nfunction UISettings.set_font(name, size)\r\n    if name then\r\n        _G.UI_SETTINGS.font_name = name\r\n    end\r\n    if size then\r\n        _G.UI_SETTINGS.font_size = size\r\n    end\r\n    save_to_file(_G.UI_SETTINGS)\r\nend\r\n\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n---   EXPORT\r\n---  ═══════════════════════════════════════════════════════════════════════════\r\n\r\nreturn UISettings\r\n", "shared/utils/core/char_paths.lua": "---============================================================================\n--- Character Paths - where each file of a character folder lives\n---============================================================================\n--- One place that knows the layout of data/<Character>/, so no module\n--- builds a path by hand.\n---\n--- Layout since 2026-09-30:\n---   <Char>/<Char>_<JOB>.lua      one-line entry (GearSwap needs this name)\n---   <Char>/_common/              settings for the whole character, by theme\n---                                (the _ puts it first in the folder list)\n---       display/                 HUD, colours, region, lockstyle delay\n---       keys/                    the keys bound for every job\n---       dualbox/                 dual-box settings; alt/ = the alt's own commands\n---       inventory/               refill, craft, wardrobe organizer\n---       combat/                  buffs, recasts, debuffs (medicine, cleanse), what a\n---                                subjob brings to any job (waltz tiers, stratagems)\n---       gear/                    how pieces are put on: weapons, Dual Wield tiers,\n---                                elemental belt, HP order\n---       travel/                  Sneak / Invisible, warp rings\n---       tools/                   fight journal, Sortie orders, addons a job loads\n---       sets/                    gear shared by jobs (rings.lua...), craft and\n---                                fishing sets\n---   <Char>/<job>/                one job, by theme (job_group below)\n---       display/                 <JOB>_HUD, _LOCKSTYLE, _MACROBOOK\n---       keys/                    <JOB>_KEYBINDS, _STATES, _CUSTOM\n---       combat/                  <JOB>_CONFIG (the job's own switches and\n---                                thresholds: job_config.lua), <JOB>_TP_CONFIG,\n---                                _WS_CONFIG, and songs, Saboteur, cures, pets...\n---       inventory/               <JOB>_REFILL\n---       sets/                    its gear: <job>_sets.lua, armor.lua...\n---   <Char>/saved/                files the game writes (window positions,\n---                                dual-box role, HUD settings, Combat Mode /\n---                                Treasure Mode per job, caches...)\n---   <Char>/logs/                 journals, one folder a topic (CharPaths.log):\n---       trace/                   trace.log, trace.old.log (//gs c trace)\n---       fights/                  <date>.log (//gs c fights on)\n---       sortie/                  <date>_<time>.log, one a run (the SortieLog addon)\n---       rolls/                   rolldebug.log (COR //gs c rolldebug)\n---       dualbox/                 altbuff.log (//gs c altdebug)\n---       wardrobe/                wardrobe_debug.log (//gs c wo)\n---       craft/                   synth.log (every synthesis: craft/synth_results.lua)\n---                                (past 2 MB a journal goes to <name>.old.log; dated\n---                                files older than 60 days are deleted: log_keeper.lua)\n---                                (before 2026-10-07 in saved/ or in data/: moved\n---                                here when written again)\n---   <Char>/atelier/              what the Atelier page (data/atelier.html) writes\n---       overrides/               set_overrides.lua, keybind_overrides.lua, mode_overrides.lua: pieces,\n---                                keys and mode start values changed in the page, laid over your files\n---       exports/                 <JOB>_<SUB>.js: the page's data (//gs c atelier)\n---       backups/                 set files before each push (last 20 each)\n---       history.lua              every push (the page's History)\n---       export.on, live.off      //gs c atelier on / live off\n---                                (before 2026-10-05 all of it was in saved/: still read\n---                                there, moved here when written again)\n---\n--- Since 2026-10-10 a setting of one job is in that job's folder (TUNING.lua\n--- and AUTO_ABILITIES.lua are gone: job_config.lua), gear/, travel/ and tools/\n--- took what combat/ and display/ held for want of a better place, two files\n--- got the _CONFIG of the others (AUTOCURE_CONFIG is AUTO_MEDICINE_CONFIG), and the mode files went\n--- from keys/ to saved/. The places and names of before are still read\n--- (COMMON_BEFORE, SAVED_BEFORE).\n---\n--- Older layouts, still read: config/<FILE>, config/<job>/, config/alt/,\n--- config/craft/, sets/<job>_sets.lua, sets/<job>/, files at the root of the\n--- character folder, and the first form of this layout (sets and gear files\n--- next to the settings, common/craft/, then common/ without the _). Every\n--- lookup tries the new place first, then the old\n--- ones, so a character that was not moved (a frozen clone) keeps working.\n--- A file that exists nowhere yet is created where that character's layout\n--- puts it: its new place once the folder has _common/ (or common/), else the\n--- old place, so\n--- a folder that was not moved never gets new folders.\n---\n--- @file    shared/utils/core/char_paths.lua\n--- @author  ejouanchicot\n--- @version 1.0\n--- @date    Created: 2026-09-30\n---============================================================================\n\nlocal CharPaths = {}\n\n--- Places of each kind of file, relative to the character folder, newest\n--- first. %s is the file name, %j the job in lower case.\nlocal LAYOUT = {\n    common = {'_common/%s', 'common/%s', 'config/%s'},\n    alt    = {'_common/dualbox/alt/%s', 'common/dualbox/alt/%s', 'common/alt/%s', 'config/alt/%s'},\n    craft  = {'_common/inventory/%s', '_common/%s', 'common/inventory/%s', 'common/%s',\n              'common/craft/%s', 'config/craft/%s'},\n    gear   = {'_common/sets/%s', 'common/sets/%s', 'common/craft/%s', 'common/%s',\n              'sets/common/%s', 'sets/%s'},\n    job    = {'%j/%s', 'config/%j/%s'},\n    sets   = {'%j/sets/%s', '%j/%s', 'sets/%j/%s', 'sets/%s'},\n    saved  = {'saved/%s', 'config/%s', '%s'},\n}\n\n--- Theme folder of each character setting in _common/. A file not listed\n--- here stays at the root of _common/.\nlocal COMMON_GROUPS = {\n    ['UI_CONFIG.lua'] = 'display', ['UI_COLOR_CONFIG.lua'] = 'display',\n    ['REGION_CONFIG.lua'] = 'display', ['LOCKSTYLE_CONFIG.lua'] = 'display',\n    ['COMMON_KEYBINDS.lua'] = 'keys',\n    ['DUALBOX_CONFIG.lua'] = 'dualbox',\n    ['REFILL_CONFIG.lua'] = 'inventory', ['CRAFT_CONFIG.lua'] = 'inventory',\n    ['CRAFT_REFILL.lua'] = 'inventory', ['WARDROBE_CONFIG.lua'] = 'inventory',\n    ['BUFF_CONFIG.lua'] = 'combat', ['RECAST_CONFIG.lua'] = 'combat', ['CLEANSE_CONFIG.lua'] = 'combat',\n    ['AUTO_MEDICINE_CONFIG.lua'] = 'combat', ['SUBJOB_CONFIG.lua'] = 'combat',\n    ['WEAPON_CONFIG.lua'] = 'gear', ['DW_CONFIG.lua'] = 'gear',\n    ['ELEMENTAL_BELT_CONFIG.lua'] = 'gear', ['HP_PRIORITY_CONFIG.lua'] = 'gear',\n    ['STEALTH_CONFIG.lua'] = 'travel', ['WARP_CONFIG.lua'] = 'travel',\n    ['FIGHTS_CONFIG.lua'] = 'tools', ['SORTIE_CONFIG.lua'] = 'tools', ['ADDONS_CONFIG.lua'] = 'tools', ['ENHTEST_CONFIG.lua'] = 'tools', ['ENHTEST_SETS.lua'] = 'tools',\n    -- gone on 2026-10-10 (job_config.lua), read where a folder still has them\n    ['TUNING.lua'] = 'combat', ['AUTO_ABILITIES.lua'] = 'combat',\n}\nCharPaths.COMMON_GROUPS = COMMON_GROUPS\n\n--- Where a common setting was before 2026-10-10: {theme folder, file name}.\nlocal COMMON_BEFORE = {\n    ['AUTO_MEDICINE_CONFIG.lua'] = {'combat', 'AUTOCURE_CONFIG.lua'},\n    ['ELEMENTAL_BELT_CONFIG.lua'] = {'combat', 'ELEMENTAL_BELT.lua'},\n    ['HP_PRIORITY_CONFIG.lua'] = {'combat', 'HP_PRIORITY.lua'},\n    ['WEAPON_CONFIG.lua'] = {'combat', 'WEAPON_CONFIG.lua'}, ['DW_CONFIG.lua'] = {'combat', 'DW_CONFIG.lua'},\n    ['STEALTH_CONFIG.lua'] = {'combat', 'STEALTH_CONFIG.lua'},\n    ['FIGHTS_CONFIG.lua'] = {'combat', 'FIGHTS_CONFIG.lua'}, ['SORTIE_CONFIG.lua'] = {'combat', 'SORTIE_CONFIG.lua'},\n    ['ADDONS_CONFIG.lua'] = {'display', 'ADDONS_CONFIG.lua'},\n}\n--- Where a file the game writes was before 2026-10-10 (a setting's folder).\nlocal SAVED_BEFORE = {\n    ['combat_mode.lua'] = {'_common/keys/combat_mode.lua', 'common/keys/combat_mode.lua'},\n    ['treasure_mode.lua'] = {'_common/keys/treasure_mode.lua', 'common/keys/treasure_mode.lua'},\n}\n\n--- Theme folder of a job settings file, from the end of its name.\nlocal JOB_GROUP_SUFFIXES = {\n    {'_HUD', 'display'}, {'_LOCKSTYLE', 'display'}, {'_MACROBOOK', 'display'},\n    {'_KEYBINDS', 'keys'}, {'_STATES', 'keys'}, {'_CUSTOM', 'keys'},\n    {'_REFILL', 'inventory'},\n}\n\n--- @param file string e.g. 'WAR_STATES.lua'\n--- @return string|nil display | keys | inventory | combat; nil for a gear file\nfunction CharPaths.job_group(file)\n    if not file:match('^%u') then return nil end\n    local base = file:gsub('%.lua$', '')\n    for _, entry in ipairs(JOB_GROUP_SUFFIXES) do\n        if base:sub(-#entry[1]) == entry[1] then return entry[2] end\n    end\n    return 'combat'\nend\n\n--- Old place of a file that exists nowhere yet, per kind (the path the code\n--- used before 2026-09-30).\nlocal LEGACY_DEFAULT = {\n    common = 'config/%s', alt = 'config/alt/%s', job = 'config/%j/%s', sets = 'sets/%s',\n    craft = 'config/craft/%s', gear = 'sets/%s',\n}\n-- What the Atelier writes, by the name the code knows it by: its place in <Char>/atelier/ (the code before\n-- 2026-10-05 kept them all in saved/, under these names; exports in saved/atelier/)\nlocal ATELIER = {\n    ['set_overrides.lua'] = 'atelier/overrides/set_overrides.lua',\n    ['keybind_overrides.lua'] = 'atelier/overrides/keybind_overrides.lua',\n    ['mode_overrides.lua'] = 'atelier/overrides/mode_overrides.lua',\n    ['list_layout.js'] = 'atelier/overrides/list_layout.js',\n    ['bag_plan.js'] = 'atelier/overrides/bag_plan.js',\n    ['set_push_history.lua'] = 'atelier/history.lua',\n    ['atelier.on'] = 'atelier/export.on',\n    ['atelier_live.off'] = 'atelier/live.off',\n    ['backups'] = 'atelier/backups',\n    ['exports'] = 'atelier/exports',\n}\nlocal ATELIER_OLD = {exports = {'saved/atelier'}}\nlocal ROOT_SAVED = {['temp_binds.lua'] = true, ['trace.log'] = true, ['trace.old.log'] = true,\n    ['trace.on'] = true, ['atelier.on'] = true, ['rolldebug.log'] = true}\n\n--- Name of the character being played, or nil before the game knows it.\n--- @return string|nil\nfunction CharPaths.name()\n    local p = windower.ffxi.get_player()\n    if p and p.name then return p.name end\n    return rawget(_G, 'player') and player.name or nil\nend\n\nlocal function data_dir()\n    return windower.addon_path .. 'data/'\nend\n\nlocal function exists(path)\n    if windower.file_exists then return windower.file_exists(path) end\n    local f = io.open(path, 'r')\n    if f then f:close() return true end\n    return false\nend\n\nlocal function fill(pattern, file, job)\n    return (pattern:gsub('%%j', (job or ''):lower()):gsub('%%s', function() return file end))\nend\n\n--- True when the character folder uses the layout of 2026-09-30.\nlocal layout_cache = {}\nlocal function new_layout(char)\n    if layout_cache[char] == nil then\n        local base = data_dir() .. char\n        layout_cache[char] = windower.dir_exists and (windower.dir_exists(base .. '/_common')\n            or windower.dir_exists(base .. '/common')) and true or false\n    end\n    return layout_cache[char]\nend\n\n--- Where a file that exists nowhere yet goes, for a folder in the old layout.\nlocal function legacy_default(kind, file, job)\n    if kind == 'atelier' then return legacy_default('saved', file, job) end\n    if kind == 'saved' then return ROOT_SAVED[file] and file or ('config/' .. file) end\n    return LEGACY_DEFAULT[kind] and fill(LEGACY_DEFAULT[kind], file, job) or nil\nend\n\n--- Candidate paths of one file, relative to the character folder.\n--- @param kind string common (its theme folder from COMMON_GROUPS) | alt | craft (CRAFT_REFILL) | gear (_common/sets/:\n---   shared gear, craft sets) | job | sets (a job's gear) | saved\n--- @param file string File name (with .lua for files, without for modules)\n--- @param job string|nil Job code, for job and sets\n--- @return table\nlocal function candidates(kind, file, job)\n    local out = {}\n    if kind == 'atelier' then\n        out[1] = ATELIER[file] or ('atelier/' .. file)\n        for _, old in ipairs(ATELIER_OLD[file] or {'saved/' .. file, 'config/' .. file, file}) do out[#out + 1] = old end\n        return out\n    end\n    if kind == 'common' and COMMON_GROUPS[file] then\n        out[1] = '_common/' .. COMMON_GROUPS[file] .. '/' .. file\n        out[2] = 'common/' .. COMMON_GROUPS[file] .. '/' .. file\n    elseif kind == 'job' and CharPaths.job_group(file) then\n        out[1] = (job or ''):lower() .. '/' .. CharPaths.job_group(file) .. '/' .. file\n    end\n    local was = kind == 'common' and COMMON_BEFORE[file] or nil\n    if was then\n        out[#out + 1] = '_common/' .. was[1] .. '/' .. was[2]\n        out[#out + 1] = 'common/' .. was[1] .. '/' .. was[2]\n    end\n    for _, pattern in ipairs(LAYOUT[kind] or {}) do\n        out[#out + 1] = fill(pattern, file, job)\n    end\n    -- under its name of before, in the places of the older layouts\n    if was and was[2] ~= file then\n        for _, pattern in ipairs(LAYOUT.common) do out[#out + 1] = fill(pattern, was[2], job) end\n    end\n    for _, old in ipairs(kind == 'saved' and SAVED_BEFORE[file] or {}) do out[#out + 1] = old end\n    return out\nend\n\n--- Path of a file relative to the character folder: where it is, or where\n--- it would be created.\n--- @param kind string\n--- @param file string File name with its extension\n--- @param job string|nil\n--- @param char string|nil Character (default: the one being played)\n--- @return string|nil\nfunction CharPaths.relative(kind, file, job, char)\n    char = char or CharPaths.name()\n    if not char then return nil end\n    local list = candidates(kind, file, job)\n    for _, rel in ipairs(list) do\n        if exists(data_dir() .. char .. '/' .. rel) then return rel end\n    end\n    if new_layout(char) then return list[1] end\n    return legacy_default(kind, file, job) or list[1]\nend\n\n--- Absolute path of a file: where it is, or where it would be created.\n--- @param kind string\n--- @param file string File name with its extension\n--- @param job string|nil\n--- @param char string|nil\n--- @return string|nil\nfunction CharPaths.file(kind, file, job, char)\n    char = char or CharPaths.name()\n    local rel = CharPaths.relative(kind, file, job, char)\n    return rel and (data_dir() .. char .. '/' .. rel) or nil\nend\n\n--- require() name of a module: where it is, else its new place.\n--- @param kind string\n--- @param name string Module name without .lua\n--- @param job string|nil\n--- @param char string|nil\n--- @return string|nil\nfunction CharPaths.module(kind, name, job, char)\n    char = char or CharPaths.name()\n    local rel = CharPaths.relative(kind, name .. '.lua', job, char)\n    return rel and (char .. '/' .. rel:gsub('%.lua$', '')) or nil\nend\n\n--- pcall(require) of a character module.\n--- @return boolean ok, any module or error\nfunction CharPaths.load(kind, name, job, char)\n    local mod = CharPaths.module(kind, name, job, char)\n    if not mod then return false, 'no character' end\n    return pcall(require, mod)\nend\n\n--- require() of a character module that older folders may not have: nil\n--- when the file is missing, the module otherwise. A broken file is named in\n--- chat and also gives nil (module_cache.lua, CHARACTER FILES).\n--- @return any|nil\nfunction CharPaths.optional(kind, name, job, char)\n    local path = CharPaths.file(kind, name .. '.lua', job, char)\n    if not (path and exists(path)) then return nil end\n    return require(CharPaths.module(kind, name, job, char))\nend\n\n--- Create the folder of a file about to be written (one level: the file's\n--- own folder, e.g. <Char>/saved/).\n--- @param path string Absolute file path\nfunction CharPaths.ensure_parent(path)\n    local dir = path and path:match('^(.*)/[^/]*$')\n    if dir and windower.dir_exists and not windower.dir_exists(dir) and windower.create_dir then\n        windower.create_dir(dir)\n    end\nend\n\n--- Create every missing folder of a path under data/<Char>/ (atelier/overrides/: two levels).\n--- @param dir string Absolute folder path\nfunction CharPaths.ensure_dir(dir)\n    if not (dir and windower.dir_exists and windower.create_dir) or windower.dir_exists(dir) then return end\n    CharPaths.ensure_dir(dir:match('^(.*)/[^/]+$'))\n    windower.create_dir(dir)\nend\n\n--- Absolute path of a file about to be written: where it already is, else\n--- where the character's layout puts it. In the new layout its folder is\n--- created (e.g. saved/); an old-layout folder is never given new folders.\n--- An Atelier file (kind 'atelier') always goes to <Char>/atelier/ in the new\n--- layout; once it is written there, CharPaths.retire drops its old copy.\n--- @return string|nil\nfunction CharPaths.writable(kind, file, job, char)\n    char = char or CharPaths.name()\n    if kind == 'atelier' and char and new_layout(char) then\n        local path = data_dir() .. char .. '/' .. (ATELIER[file] or ('atelier/' .. file))\n        CharPaths.ensure_dir(path:match('^(.*)/[^/]*$'))\n        return path\n    end\n    if kind == 'atelier' then kind = 'saved' end\n    -- A file the game writes goes to saved/ in a tidied folder, even when an\n    -- old copy is left at the root: Kaories' trace went back to the root\n    -- once saved/trace.log was rotated away (2026-10-01).\n    if kind == 'saved' and char and new_layout(char) then\n        local path = data_dir() .. char .. '/saved/' .. file\n        CharPaths.ensure_parent(path)\n        return path\n    end\n    local path = CharPaths.file(kind, file, job, char)\n    if path and new_layout(char) then CharPaths.ensure_parent(path) end\n    return path\nend\n\nlocal log_paths = {}\n\n--- Absolute path of a journal: <Char>/logs/<topic>/<file>, its folder created.\n--- A copy left where journals used to be written (saved/, the character's\n--- root, or `old`) is moved there first, so one file carries on. A character\n--- in an older layout keeps it where CharPaths.writable('saved') puts it.\n--- @param topic string 'trace', 'fights', 'sortie', 'rolls', 'dualbox', 'wardrobe'\n--- @param file string File name\n--- @param char string|nil\n--- @param old string|nil Absolute path of an older copy elsewhere (data/altbuff_<name>.log)\n--- @return string|nil\nfunction CharPaths.log(topic, file, char, old)\n    char = char or CharPaths.name()\n    if not char then return nil end\n    if not new_layout(char) then return CharPaths.writable('saved', file, nil, char) end\n    -- once a load: a trace writes a line a second, the folder is not looked up each time\n    local key = char .. '/' .. topic .. '/' .. file\n    if log_paths[key] then return log_paths[key] end\n    local base = data_dir() .. char\n    local dir = base .. '/logs/' .. topic\n    CharPaths.ensure_dir(dir)\n    local path = dir .. '/' .. file\n    if not exists(path) then\n        for _, before in ipairs({base .. '/saved/' .. file, base .. '/' .. file, old}) do\n            if exists(before) then os.rename(before, path) break end\n        end\n    end\n    -- a journal past 2 MB goes to <name>.old.log, once a load (log_keeper.lua); not the trace nor the dated files\n    pcall(function()\n        local LogKeeper = require('shared/utils/core/log_keeper')\n        if LogKeeper.rotates(topic) then LogKeeper.rotate(path) end\n    end)\n    log_paths[key] = path\n    return path\nend\n\n--- The old copies of an Atelier file once it is written in <Char>/atelier/ (so no older copy is read in its place).\n--- @param file string The file's name (ATELIER above)\n--- @param char string|nil\nfunction CharPaths.retire(file, char)\n    char = char or CharPaths.name()\n    if not (char and new_layout(char)) then return end\n    local list = candidates('atelier', file)\n    for i = 2, #list do\n        local old = data_dir() .. char .. '/' .. list[i]\n        if exists(old) then os.remove(old) end\n    end\nend\n\n--- Absolute path of an Atelier folder (exports, backups): <Char>/atelier/<x>/ in the new layout (created), else\n--- the old place; and the old place, to read what is still there.\n--- @param name string 'exports' | 'backups'\n--- @param char string|nil\n--- @return string|nil folder, string|nil old folder\nfunction CharPaths.atelier_dir(name, char)\n    char = char or CharPaths.name()\n    if not char then return nil end\n    local base, list = data_dir() .. char .. '/', candidates('atelier', name)\n    if not new_layout(char) then return base .. list[2], nil end\n    local dir = base .. list[1]\n    CharPaths.ensure_dir(dir)\n    return dir, base .. list[2]\nend\n\n--- require() name for a path written the old way ('config/war/WAR_LOCKSTYLE',\n--- 'Tetsouo/config/war/WAR_LOCKSTYLE', 'config/COMMON_KEYBINDS'), found in\n--- the current layout. Any other path comes back unchanged.\n--- @param path string\n--- @return string\nfunction CharPaths.legacy_module(path)\n    if type(path) ~= 'string' then return path end\n    local rest = path:match('^config/(.+)$')\n    local char = nil\n    if not rest then char, rest = path:match('^([^/]+)/config/(.+)$') end\n    if not rest then return path end\n    local job, name = rest:match('^(%w+)/([%w_]+)$')\n    if job then return CharPaths.module('job', name, job, char) or path end\n    if rest:match('^[%w_]+$') then return CharPaths.module('common', rest, nil, char) or path end\n    return path\nend\n\n_G.CharPaths = CharPaths\n\n-- First shared file of every entry (shared/entry/<job>.lua requires it before anything else):\n-- the require cache goes in here, so the character files an entry reads before config_loader\n-- (LOCKSTYLE_CONFIG, REGION_CONFIG) are already checked for a broken file (module_cache.lua).\n-- This file was itself loaded by the uncached require: recording it keeps it from loading twice.\nlocal cache_ok, ModuleCache = pcall(require, 'shared/utils/core/module_cache')\nif cache_ok and ModuleCache and ModuleCache.install then\n    ModuleCache.install()\n    ModuleCache.remember('shared/utils/core/char_paths', CharPaths)\nend\n\nreturn CharPaths\n", "shared/utils/core/module_cache.lua": "---  ═══════════════════════════════════════════════════════════════════════════\n---   Module Cache - make require() actually cache\n---  ═══════════════════════════════════════════════════════════════════════════\n---   In the GearSwap sandbox `require` is not Lua's require: refresh.lua aliases\n---   it to `include_user`, which reads package.loaded but NEVER writes to it\n---   (user_functions.lua:300). Only Windower's own libs are in there, so every\n---   require of a project module falls through to a full disk read, a loadfile\n---   compile and a fresh execution - every single call.\n---\n---   Measured in game with //gs c lagdebug: 300 module loads for 54 distinct\n---   modules in 34 seconds, 1180ms of load time of which 1018ms (86%) was\n---   re-running modules already in memory. UI_SETTINGS alone loaded 37 times.\n---\n---   That is what makes the project's own lazy-loading convention backfire:\n---   `local X = require(...)` inside a function is documented as the cheap\n---   option, and without a cache it is the expensive one.\n---\n---   LIFETIME - why the cache lives on the sandbox _G and nowhere else:\n---   include_user does `setfenv(f, user_env)`, so a loaded module is bound to\n---   the user_env it was compiled against. GearSwap drops user_env on every\n---   reload and job change (refresh.lua:83). A cache in the windower table\n---   would outlive that and hand the new job modules closed over the old\n---   player/sets/state. On the sandbox _G it dies with the environment it\n---   belongs to, which is exactly right - and it is also why GearSwap not\n---   caching is defensible rather than simply a bug.\n---\n---   `include()` is deliberately left alone. It is the same underlying function\n---   but it is used for set files, which are meant to re-execute.\n---\n---   @file    shared/utils/core/module_cache.lua\n---   @author  ejouanchicot\n---   @version 1.0\n---   @date    Created: 2026-08-09\n---  ═══════════════════════════════════════════════════════════════════════════\n\nlocal ModuleCache = {}\n\n-- Lets a module that legitimately returns nil be remembered as loaded, instead\n-- of being re-run forever because \"no value\" reads the same as \"not cached\".\nlocal CACHED_NIL = {}\n\n---  ═══════════════════════════════════════════════════════════════════════════\n---   CHARACTER FILES - a broken one is named, then treated as missing\n---  ═══════════════════════════════════════════════════════════════════════════\n---   A player edits the files of data/<Character>/ by hand. Before, one typo in\n---   any of them stopped the whole load, and the error often named the file that\n---   USED it (war_sets.lua:94 'Rings' a nil value) instead of the broken one\n---   (rings.lua). Now a character file that errors, is empty or returns\n---   something else than a table is reported in red, with its path and line,\n---   and require() gives nil: what callers already get for a missing file\n---   (CharPaths.optional), so an optional file falls back to its defaults.\n---   A file the job cannot do without (its sets, its states) still stops the\n---   load, but the line just above names the real culprit.\n---   Checked outside the game: python scripts/loadcheck/check_load.py (broken files).\n\n--- Lowercased \"<character>/\" prefix of the files of the one playing, or nil.\nlocal function char_prefix()\n    local p = rawget(_G, 'player')\n    local name = type(p) == 'table' and p.name\n    return type(name) == 'string' and name ~= '' and (name:lower() .. '/') or nil\nend\n\n--- True when a file's text holds only blanks and comments: an emptied file.\nlocal function blank_text(text)\n    return not (text or ''):gsub('%-%-%[(=*)%[.-%]%1%]', ''):gsub('%-%-[^\\n]*', ''):find('%S')\nend\n\n--- True when the required file (path relative to data/, no .lua) is an emptied one.\nlocal function is_blank(path)\n    local base = windower and windower.addon_path\n    local f = base and io.open(base .. 'data/' .. path .. '.lua', 'rb')\n    if not f then return false end\n    local text = f:read('*a')\n    f:close()\n    return blank_text(text)\nend\n\n--- Say in chat which character file is broken and why.\n--- The message system may itself be what fails to load: then plain chat (CODE_QUALITY §6, fallback).\nlocal function report(path, why)\n    local text = ('%s.lua is broken (%s): loaded without it, fix the file then //lua reload gearswap')\n        :format(path, why)\n    local ok = pcall(function() require('shared/utils/messages/message_formatter').show_error(text) end)\n    if not ok then\n        add_to_chat(167, '[GearSwap] ' .. text)\n    end\n    local list = rawget(_G, '__char_file_errors') or {}\n    list[#list + 1] = {path = path, why = why}\n    _G.__char_file_errors = list\nend\n\n--- Read a character settings file run with dofile (no require: absolute path, re-read on purpose).\n--- A broken one is reported like a required one. Files the game writes (saved/) do not use this:\n--- a broken one there is simply rewritten, the player never edits it.\n--- @param path string|nil Absolute path\n--- @param label string Name shown to the player (e.g. 'Tetsouo/_common/travel/STEALTH_CONFIG')\n--- @return table|nil The file's table, nil when missing or broken\nfunction ModuleCache.read_char_file(path, label)\n    local f = path and io.open(path, 'rb')\n    if not f then return nil end\n    local text = f:read('*a') or ''\n    f:close()\n    local ok, result = pcall(dofile, path)\n    if not ok then\n        local line, why = tostring(result):match(':(%d+): ([^\\n]*)$')\n        report(label, line and ('line ' .. line .. ': ' .. why) or tostring(result))\n        return nil\n    end\n    if type(result) ~= 'table' then\n        report(label, blank_text(text) and 'it is empty' or ('it returns a ' .. type(result) .. ', a table { ... } was expected'))\n        return nil\n    end\n    return result\nend\n\n--- Load a character file through the original require, never letting it stop the load.\nlocal function load_char_file(original, path)\n    local ok, result = pcall(original, path)\n    if not ok then\n        local msg = tostring(result)\n        -- a missing file is not a broken one: callers probe with pcall(require) (CharPaths.load)\n        if msg:find('Cannot find the include file', 1, true) then error(result, 0) end\n        local line, why = msg:match(':(%d+): ([^\\n]*)$')\n        report(path, line and ('line ' .. line .. ': ' .. why) or msg)\n        return nil\n    end\n    if result ~= nil and type(result) ~= 'table' then\n        report(path, 'it returns a ' .. type(result) .. ', a table { ... } was expected')\n        return nil\n    end\n    if result == nil and is_blank(path) then\n        report(path, 'it is empty')\n    end\n    return result\nend\n\n--- Replace require with a caching version, once per sandbox.\n--- @return boolean True when the cache was installed by this call\nfunction ModuleCache.install()\n    if rawget(_G, '__require_cache_installed') then\n        return false\n    end\n\n    local original = rawget(_G, 'require')\n    if type(original) ~= 'function' then\n        return false\n    end\n\n    local cache = {}\n    _G.__require_cache = cache\n    _G.__require_cache_installed = true\n    _G.__require_cache_stats = { hits = 0, loads = 0 }\n    local stats = _G.__require_cache_stats\n\n    _G.require = function(path, ...)\n        -- include_user's second parameter loads the file into a caller-supplied\n        -- table, which is a different result each time. Never serve that from\n        -- cache; hand it straight through.\n        if type(path) ~= 'string' or select('#', ...) > 0 then\n            return original(path, ...)\n        end\n\n        -- include_user lowercases before its own lookup, so match that or the\n        -- same module under two spellings would be loaded twice.\n        local key = path:lower()\n\n        local hit = cache[key]\n        if hit ~= nil then\n            stats.hits = stats.hits + 1\n            if hit == CACHED_NIL then\n                return nil\n            end\n            return hit\n        end\n\n        -- //gs c trace names each module read from disk (trace_hooks.lua)\n        local on_miss = rawget(_G, '__require_miss_hook')\n        if on_miss then on_miss(path) end\n\n        local prefix = char_prefix()\n        local result\n        if prefix and key:sub(1, #prefix) == prefix then\n            result = load_char_file(original, path)\n        else\n            result = original(path)\n        end\n        stats.loads = stats.loads + 1\n        cache[key] = (result == nil) and CACHED_NIL or result\n        return result\n    end\n\n    -- this file was loaded by the uncached require: the next require of it is a hit, not a second copy\n    ModuleCache.remember('shared/utils/core/module_cache', ModuleCache)\n    return true\nend\n\n--- Record a module loaded before the cache was installed, so its next require is a hit.\n--- @param path string require() name\n--- @param module any What that require returned\nfunction ModuleCache.remember(path, module)\n    local cache = rawget(_G, '__require_cache')\n    if cache and module ~= nil and cache[path:lower()] == nil then\n        cache[path:lower()] = module\n    end\nend\n\n---  ═══════════════════════════════════════════════════════════════════════════\n---   MODULE EXPORT\n---  ═══════════════════════════════════════════════════════════════════════════\n\n_G.ModuleCache = ModuleCache\n\nreturn ModuleCache\n", "shared/utils/keybinds/key_conflicts.lua": "---============================================================================\r\n--- Key Conflicts - two actions on one key, told instead of silently lost\r\n---============================================================================\r\n--- A job's key list holds its own keys, the player's custom keys\r\n--- (<JOB>_CUSTOM.lua), Combat Mode and the character's common keys\r\n--- (_common/keys/COMMON_KEYBINDS.lua: subjob and partner layers). Only one command\r\n--- can sit on a key; when two entries apply at once, one of them does\r\n--- nothing. Which one wins (KeybindManager lays the keys in list order):\r\n---   - a common entry without `override` yields to a job / custom entry;\r\n---   - otherwise the later entry in the list is the one bound.\r\n--- The keys are never changed here: conflicts are only reported.\r\n---\r\n--- What counts as a conflict, by kind of entry (job = job file, custom keys,\r\n--- Combat Mode; own = common key for this character; partner = common key\r\n--- with an `alt` condition):\r\n---   job / job, job / own, job / partner, own / partner   reported\r\n---   own / own          not reported: a common key and its subjob version\r\n---                      (Prism Powder, /NIN Tonko: Ni) are layers on purpose\r\n---   partner / partner  not reported: layers of the partner's own keys\r\n---   same command twice not reported: nothing is lost\r\n---\r\n---   live(active, yielded)  conflicts right now (current subjob, partner,\r\n---                          weapon), one per key: {key, bound, lost = {...}}\r\n---   possible(binds)        every pair of entries on one key that can apply\r\n---                          together, over all subjobs and partner jobs\r\n---   report(job, list, told)  one chat warning per conflict and per load\r\n---   show_possible(job, binds)  //gs c keyconflicts\r\n---\r\n--- @file    shared/utils/keybinds/key_conflicts.lua\r\n--- @author  ejouanchicot\r\n--- @version 1.0\r\n--- @date    Created: 2026-09-27\r\n---============================================================================\r\n\r\nlocal KeyConflicts = {}\r\n\r\nlocal SUBJOBS = {'WAR', 'MNK', 'WHM', 'BLM', 'RDM', 'THF', 'PLD', 'DRK', 'BST', 'BRD', 'RNG',\r\n    'SAM', 'NIN', 'DRG', 'SMN', 'BLU', 'COR', 'PUP', 'DNC', 'SCH', 'GEO', 'RUN'}\r\n\r\nlocal function keyed(bind)\r\n    return type(bind.key) == 'string' and bind.key ~= '' and bind.command ~= nil\r\nend\r\n\r\nlocal function kind(bind)\r\n    if not bind._common then return 'job' end\r\n    return type(bind.alt) == 'table' and 'partner' or 'own'\r\nend\r\n\r\n--- Whether two entries on one key are a conflict (see the header).\r\n--- @param a table\r\n--- @param b table\r\n--- @return boolean\r\nfunction KeyConflicts.counts(a, b)\r\n    if a.command == b.command and (a.raw and true) == (b.raw and true) then return false end\r\n    local ka, kb = kind(a), kind(b)\r\n    if ka == 'job' or kb == 'job' then return true end\r\n    return ka ~= kb\r\nend\r\n\r\n--- A common entry without override gives way to a job or custom entry.\r\n--- @param bind table\r\n--- @return boolean\r\nfunction KeyConflicts.yields(bind)\r\n    return bind._common == true and not bind.override\r\nend\r\n\r\n---============================================================================\r\n--- LIVE CONFLICTS\r\n---============================================================================\r\n\r\n--- Conflicts among the entries that apply now.\r\n--- @param active table Entries bound now, in list order\r\n--- @param yielded table|nil Common entries dropped for a job key (get_active_binds)\r\n--- @return table Array of {key, bound, lost}, in key order of appearance\r\nfunction KeyConflicts.live(active, yielded)\r\n    local by_key, order = {}, {}\r\n    local function add(key, bind, is_bound)\r\n        local c = by_key[key]\r\n        if not c then\r\n            c = {key = key, lost = {}}\r\n            by_key[key] = c\r\n            order[#order + 1] = key\r\n        end\r\n        if is_bound then\r\n            if c.bound then c.lost[#c.lost + 1] = c.bound end\r\n            c.bound = bind\r\n        else\r\n            c.lost[#c.lost + 1] = bind\r\n        end\r\n    end\r\n    for _, bind in ipairs(active or {}) do\r\n        if keyed(bind) then add(bind.key, bind, true) end\r\n    end\r\n    for _, bind in ipairs(yielded or {}) do\r\n        if keyed(bind) then add(bind.key, bind, false) end\r\n    end\r\n    local found = {}\r\n    for _, key in ipairs(order) do\r\n        local c = by_key[key]\r\n        local lost = {}\r\n        for _, bind in ipairs(c.lost) do\r\n            if KeyConflicts.counts(c.bound, bind) then lost[#lost + 1] = bind end\r\n        end\r\n        if #lost > 0 then\r\n            c.lost = lost\r\n            found[#found + 1] = c\r\n        end\r\n    end\r\n    return found\r\nend\r\n\r\n---============================================================================\r\n--- POSSIBLE CONFLICTS (all subjobs, all partner jobs)\r\n---============================================================================\r\n\r\nlocal function norm(value)\r\n    return tostring(value):lower():gsub('%s', '')\r\nend\r\n\r\n--- Set of normalized names from a string / list rule, nil = anything.\r\nlocal function name_set(rule)\r\n    if rule == nil then return nil end\r\n    local set = {}\r\n    for _, value in ipairs(type(rule) == 'table' and rule or {rule}) do set[norm(value)] = true end\r\n    return set\r\nend\r\n\r\n--- Whether two name sets (nil = anything) share a value.\r\nlocal function overlap(a, b)\r\n    if a == nil or b == nil then return true end\r\n    for value in pairs(a) do\r\n        if b[value] then return true end\r\n    end\r\n    return false\r\nend\r\n\r\n--- Subjobs under which a bind applies.\r\n--- @param bind table\r\n--- @return table Set of subjob codes\r\nlocal function subjobs_of(bind)\r\n    local only, never = name_set(bind.subjob), name_set(bind.exclude_subjob) or {}\r\n    local set = {}\r\n    for _, code in ipairs(SUBJOBS) do\r\n        local key = norm(code)\r\n        if (only == nil or only[key]) and not never[key] then set[code] = true end\r\n    end\r\n    return set\r\nend\r\n\r\n--- Whether two `alt` conditions can hold together: two named partners can\r\n--- both be there; one partner cannot play two jobs at once.\r\nlocal function alts_compatible(a, b)\r\n    if type(a) ~= 'table' or type(b) ~= 'table' then return true end\r\n    if a.name and b.name and norm(a.name) ~= norm(b.name) then return true end\r\n    return overlap(name_set(a.job), name_set(b.job))\r\n        and overlap(name_set(a.subjob), name_set(b.subjob))\r\n        and overlap(name_set(a.weapon), name_set(b.weapon))\r\nend\r\n\r\n--- Subjobs under which both binds apply (empty when they never meet).\r\nlocal function shared_subjobs(a, b)\r\n    if not overlap(name_set(a.weapon), name_set(b.weapon)) then return {} end\r\n    if not alts_compatible(a.alt, b.alt) then return {} end\r\n    local sa, sb, both = subjobs_of(a), subjobs_of(b), {}\r\n    for _, code in ipairs(SUBJOBS) do\r\n        if sa[code] and sb[code] then both[#both + 1] = code end\r\n    end\r\n    return both\r\nend\r\n\r\n--- Which of two entries (a before b in the list) is bound when both apply.\r\nlocal function winner(a, b)\r\n    if KeyConflicts.yields(b) and not a._common then return a, b end\r\n    return b, a\r\nend\r\n\r\n--- Every pair of entries on one key that can apply at the same time.\r\n--- @param binds table The job's full key list (module.binds)\r\n--- @return table Array of {key, bound, lost, subjobs}\r\nfunction KeyConflicts.possible(binds)\r\n    local found = {}\r\n    for i = 1, #(binds or {}) do\r\n        local a = binds[i]\r\n        for j = i + 1, #binds do\r\n            local b = binds[j]\r\n            if keyed(a) and keyed(b) and a.key == b.key and KeyConflicts.counts(a, b) then\r\n                local subjobs = shared_subjobs(a, b)\r\n                if #subjobs > 0 then\r\n                    local bound, lost = winner(a, b)\r\n                    found[#found + 1] = {key = a.key, bound = bound, lost = lost, subjobs = subjobs}\r\n                end\r\n            end\r\n        end\r\n    end\r\n    return found\r\nend\r\n\r\n---============================================================================\r\n--- DISPLAY\r\n---============================================================================\r\n\r\nlocal function key_name(key)\r\n    local ok, MessageCore = pcall(require, 'shared/utils/messages/message_core')\r\n    if ok and MessageCore and MessageCore.convert_key_display then return MessageCore.convert_key_display(key) end\r\n    return key\r\nend\r\n\r\nlocal function label(bind)\r\n    return tostring(bind.desc or bind.state or bind.command)\r\nend\r\n\r\n--- Label cut for one chat line, with the partner / weapon condition when\r\n--- the label does not already name it.\r\nlocal function short(bind)\r\n    local text = label(bind)\r\n    if #text > 40 then text = text:sub(1, 38) .. '..' end\r\n    local parts = {}\r\n    local alt = bind.alt\r\n    if type(alt) == 'table' and not (alt.name and text:lower():find(alt.name:lower(), 1, true)) then\r\n        local list = function(v) return type(v) == 'table' and table.concat(v, '/') or v end\r\n        parts[#parts + 1] = ((alt.name or 'partner') .. ' ' .. (list(alt.job) or '')\r\n            .. (alt.subjob and ('/' .. list(alt.subjob)) or '')):gsub('%s+$', '')\r\n    end\r\n    if bind.weapon then\r\n        parts[#parts + 1] = type(bind.weapon) == 'table' and table.concat(bind.weapon, '/') or tostring(bind.weapon)\r\n    end\r\n    if type(bind.visible) == 'function' then parts[#parts + 1] = 'when shown' end\r\n    return #parts > 0 and (text .. ' (' .. table.concat(parts, ', ') .. ')') or text\r\nend\r\n\r\n--- \"all subjobs\", \"/WAR\", \"/WAR /DRK\", \"21 subjobs\".\r\nlocal function subjob_text(list)\r\n    if #list == #SUBJOBS then return 'all subjobs' end\r\n    if #list > 6 then return ('%d subjobs'):format(#list) end\r\n    return '/' .. table.concat(list, ' /')\r\nend\r\n\r\n--- Warn once per load for each conflict of `list` (live()), in one block:\r\n--- \"Key / Bound / Lost\" per conflict, long values wrapped at the chat width.\r\n--- @param job string\r\n--- @param list table\r\n--- @param told table Signatures already told (kept by the caller for the load)\r\nfunction KeyConflicts.report(job, list, told)\r\n    local fields = {}\r\n    for _, c in ipairs(list) do\r\n        local lost = {}\r\n        for _, bind in ipairs(c.lost) do lost[#lost + 1] = label(bind) end\r\n        local id = c.key .. '|' .. tostring(c.bound.command) .. '|' .. table.concat(lost, ',')\r\n        if not told[id] then\r\n            told[id] = true\r\n            fields[#fields + 1] = {'Key', key_name(c.key), 'warn'}\r\n            fields[#fields + 1] = {'Bound', label(c.bound)}\r\n            fields[#fields + 1] = {'Does nothing', table.concat(lost, ' / '), 'bad'}\r\n        end\r\n    end\r\n    if #fields == 0 then return end\r\n    require('shared/utils/messages/info_block').show({\r\n        tag = 'KEYS', title = job .. ' key conflict', fields = fields,\r\n        lines = {{'Keys unchanged. All possible conflicts: //gs c kc', 'dim'}},\r\n    })\r\nend\r\n\r\n--- Pairs of possible() grouped: one field per key, lost entry and subjobs,\r\n--- listing everything that can take the key from it (\"A < B\": B takes it).\r\n--- @param list table possible()\r\n--- @return table InfoBlock fields {key, text, 'warn'}\r\nlocal function grouped_fields(list)\r\n    local groups, order = {}, {}\r\n    for _, c in ipairs(list) do\r\n        local id = c.key .. '|' .. tostring(c.lost) .. '|' .. table.concat(c.subjobs, ',')\r\n        if not groups[id] then\r\n            groups[id] = {c = c, winners = {}}\r\n            order[#order + 1] = id\r\n        end\r\n        local winners = groups[id].winners\r\n        winners[#winners + 1] = short(c.bound)\r\n    end\r\n    local fields = {}\r\n    for _, id in ipairs(order) do\r\n        local g = groups[id]\r\n        fields[#fields + 1] = {key_name(g.c.key), ('[%s] %s < %s'):format(subjob_text(g.c.subjobs),\r\n            short(g.c.lost), table.concat(g.winners, ' | ')), 'warn'}\r\n    end\r\n    return fields\r\nend\r\n\r\n--- //gs c keyconflicts: every conflict this job's keys can run into.\r\n--- @param job string\r\n--- @param binds table The job's full key list\r\nfunction KeyConflicts.show_possible(job, binds)\r\n    local fields = grouped_fields(KeyConflicts.possible(binds))\r\n    local spec = {tag = 'KEYS', title = job .. ' key conflicts, all subjobs', fields = fields}\r\n    if #fields == 0 then\r\n        spec.lines = {{'No two keys can apply at once, on any subjob.', 'dim'}}\r\n    else\r\n        spec.lines = {{'\"A < B\": B takes the key while both apply. Keys unchanged.', 'dim'}}\r\n    end\r\n    require('shared/utils/messages/info_block').show(spec)\r\nend\r\n\r\nreturn KeyConflicts\r\n", "shared/utils/keybinds/key_validator.lua": "---============================================================================\r\n--- Key Validator - catch keybind typos before Windower swallows them\r\n---============================================================================\r\n--- Windower never answers a `bind`: a misspelt key (\"^numpd1\") is dropped\r\n--- without a word and the key simply does nothing. This checks a job's bind\r\n--- list on load and names every entry that cannot work:\r\n---   - key not made of modifiers (^ ! @ # ~ % $) + a known key name\r\n---   - a key with no command\r\n---\r\n--- A warning only: the bind is still sent, in case Windower knows a key name\r\n--- this list does not.\r\n---\r\n--- @file    shared/utils/keybinds/key_validator.lua\r\n--- @author  ejouanchicot\r\n--- @version 1.0\r\n--- @date    Created: 2026-09-24\r\n---============================================================================\r\n\r\nlocal KeyValidator = {}\r\n\r\nlocal MODIFIERS = '^!@#~%$'\r\n\r\nlocal KEY_NAMES = {}\r\ndo\r\n    local names = {\r\n        'escape', 'esc', 'tab', 'enter', 'return', 'space', 'backspace',\r\n        'insert', 'delete', 'home', 'end', 'pageup', 'pagedown',\r\n        'up', 'down', 'left', 'right', 'capslock', 'numlock', 'scrolllock', 'pause',\r\n        'numpad*', 'numpad+', 'numpad-', 'numpad.', 'numpad/', 'numpadenter',\r\n        '-', '=', '[', ']', ';', \"'\", ',', '.', '/', '\\\\', '`',\r\n    }\r\n    for _, name in ipairs(names) do KEY_NAMES[name] = true end\r\n    for i = 0, 9 do\r\n        KEY_NAMES[tostring(i)] = true\r\n        KEY_NAMES['numpad' .. i] = true\r\n    end\r\n    for i = 1, 15 do KEY_NAMES['f' .. i] = true end\r\n    for c = string.byte('a'), string.byte('z') do KEY_NAMES[string.char(c)] = true end\r\nend\r\n\r\n--- Whether `key` is modifiers followed by a known key name.\r\n--- @param key string e.g. \"^numpad1\"\r\n--- @return boolean\r\nfunction KeyValidator.is_valid_key(key)\r\n    local i = 1\r\n    while i < #key and MODIFIERS:find(key:sub(i, i), 1, true) do\r\n        i = i + 1\r\n    end\r\n    return KEY_NAMES[key:sub(i):lower()] == true\r\nend\r\n\r\n--- Problems in a bind list, one readable line each. Two entries on one key\r\n--- are reported by key_conflicts.lua, with the one that wins.\r\n--- @param binds table Every bind entry of the file\r\n--- @return table Array of strings (empty when all is well)\r\nfunction KeyValidator.check(binds)\r\n    local problems = {}\r\n    for _, bind in ipairs(binds or {}) do\r\n        local key, desc = bind.key, tostring(bind.desc)\r\n        if type(key) ~= 'string' then\r\n            problems[#problems + 1] = ('\"%s\": no key'):format(desc)\r\n        elseif key ~= '' then\r\n            if not KeyValidator.is_valid_key(key) then\r\n                problems[#problems + 1] = ('\"%s\": unknown key %s'):format(desc, key)\r\n            end\r\n            if not bind.command or bind.command == '' then\r\n                problems[#problems + 1] = ('\"%s\": key %s has no command'):format(desc, key)\r\n            end\r\n        end\r\n    end\r\n    return problems\r\nend\r\n\r\nreturn KeyValidator\r\n", "shared/utils/keybinds/keybind_manager.lua": "---============================================================================\n--- Keybind Manager - one engine for every job's keybinds\n---============================================================================\n--- A job's keybind file only lists its keys; this factory gives it the\n--- functions every caller already uses (entry point, HUD, KeybindGuard,\n--- state hooks): get_active_binds, bind_all, refresh, unbind_all, show_intro,\n--- show_binds. Same names and behaviour as the hand-written copies it\n--- replaces, so a job can move over without any caller changing.\n---\n--- Bind entry fields:\n---   key            Windower key (\"^numpad1\"); \"\" = HUD row only, nothing bound\n---   command        gs c command sent by the key (\"cyclestate MainWeapon\")\n---   desc           Label in the HUD and the chat lists\n---   state          Mote state the row displays\n---   subjob         Only bound under this subjob (string or list)\n---   exclude_subjob Never bound under this subjob (string or list)\n---   visible        function() -> boolean, asked again on every refresh()\n---   alt            Only bound while another box of the group plays this:\n---                  {name =, job =, subjob =, weapon =}, each optional, a\n---                  string or a list; no name = the tracked partner. Checked\n---                  again whenever a box reports a new job or weapon type\n---                  (shared/utils/dualbox/alt_states.lua)\n---   weapon         Only bound while THIS character's main hand is of this\n---                  weapon skill: 'Club', 'Sword', 'Great Katana' (string or\n---                  list; spaces and case ignored, as for `alt`). An empty\n---                  main hand is 'None'. Checked again when the main hand\n---                  changes weapon type: the keys refresh by themselves\n---                  (BindManager's per-weapon layers). An entry without the\n---                  field is not affected, and no listener is laid unless\n---                  one entry of the job uses it.\n---\n--- Keys that must be cleared on load although no entry names them any more\n--- go in <module>.retired_keys. Keys this manager bound itself are cleared\n--- anyway: what it lays down is recorded on `windower`, which outlives the\n--- sandbox, so a key removed from the file is unbound on the next load.\n---\n--- @file    shared/utils/keybinds/keybind_manager.lua\n--- @author  ejouanchicot\n--- @version 1.2\n--- @date    Created: 2026-09-24 | Updated: 2026-09-27 (key conflicts)\n---============================================================================\n\nlocal KeybindManager = {}\n\nlocal MessageFormatter = require('shared/utils/messages/message_formatter')\nlocal KeyValidator = require('shared/utils/keybinds/key_validator')\nlocal KeyConflicts = require('shared/utils/keybinds/key_conflicts')\n\n--- Keys laid down by this manager, key -> command. Kept on `windower`: a\n--- job file's own memory dies with its sandbox, the Windower binds do not.\nlocal function bound_keys()\n    windower._keybind_manager_bound = windower._keybind_manager_bound or {}\n    return windower._keybind_manager_bound\nend\n\n---============================================================================\n--- HELPERS\n---============================================================================\n\n--- True when `rule` (string, list or nil) names `subjob`.\n--- @param rule string|table|nil\n--- @param subjob string|nil\n--- @return boolean\nlocal function names_subjob(rule, subjob)\n    if type(rule) == 'table' then\n        for _, value in ipairs(rule) do\n            if value == subjob then return true end\n        end\n        return false\n    end\n    return rule ~= nil and rule == subjob\nend\n\n--- Whether a `weapon` rule names the main hand now. The main hand is read\n--- once per pass (memo): reading it lists the inventory.\n--- @param rule string|table\n--- @param memo table Per-pass cache ({weapon = skill})\n--- @return boolean\nlocal function wields(rule, memo)\n    local ok, AltStates = pcall(require, 'shared/utils/dualbox/alt_states')\n    if not ok or type(AltStates) ~= 'table' or not AltStates.own_weapon_matches then return false end\n    if memo.weapon == nil then\n        local read, skill = pcall(AltStates.weapon_skill)\n        memo.weapon = read and skill or 'None'\n    end\n    return AltStates.own_weapon_matches(rule, memo.weapon)\nend\n\n--- Whether a bind applies with the current subjob, weapon and state.\n--- @param bind table\n--- @param memo table Per-pass cache shared by the binds of one pass\n--- @return boolean\nlocal function applies(bind, memo)\n    local subjob = player and player.sub_job or nil\n    if bind.subjob and not names_subjob(bind.subjob, subjob) then return false end\n    if bind.exclude_subjob and names_subjob(bind.exclude_subjob, subjob) then return false end\n    if bind.weapon ~= nil and not wields(bind.weapon, memo) then return false end\n    if type(bind.alt) == 'table' then\n        local ok, AltStates = pcall(require, 'shared/utils/dualbox/alt_states')\n        if not ok or not AltStates.matches(bind.alt) then return false end\n    end\n    if type(bind.visible) == 'function' then\n        local ok, shown = pcall(bind.visible)\n        return ok and shown ~= false and shown ~= nil\n    end\n    return true\nend\n\n--- What the key runs:\n---   \"//sm mirror\"   console command of any addon (the // is dropped)\n---   \"/p hello\"      game chat command, sent with input\n---   raw = true      the command exactly as written\n---   anything else   gs c <command>\n--- @param bind table Bind entry\n--- @return string\nfunction KeybindManager.bind_line(bind)\n    local command = bind.command\n    if bind.raw then\n        return command\n    end\n    if command:sub(1, 2) == '//' then\n        return command:sub(3)\n    end\n    if command:sub(1, 1) == '/' then\n        return 'input ' .. command\n    end\n    return 'gs c ' .. command\nend\n\n--- key -> console line for the binds that lay down a key.\n--- @param binds table List of bind entries\n--- @return table\nlocal function key_map(binds)\n    local map = {}\n    for _, bind in ipairs(binds) do\n        if bind.key and bind.key ~= '' and bind.command then\n            map[bind.key] = KeybindManager.bind_line(bind)\n        end\n    end\n    return map\nend\n\n-- Every bind / unbind goes through the paced queue (command_queue.lua): a\n-- newer command for the same key replaces the one still waiting.\nlocal function send_bind(key, line)\n    return pcall(require('shared/utils/core/command_queue').push, key, 'bind ' .. key .. ' ' .. line)\nend\n\nlocal function send_unbind(key)\n    pcall(require('shared/utils/core/command_queue').push, key, 'unbind ' .. key)\nend\n\n--- Keys //gs c tb holds this session (temp_binds.lua), key -> command. They\n--- are left alone: a job key that is not wanted any more is not unbound\n--- under them, and one that comes back is not bound over them. Its line is\n--- still recorded in bound_keys(), so `tb del` gives it back.\n--- @return table\nlocal function temp_held()\n    local ok, held = pcall(function() return require('shared/utils/keybinds/temp_binds').current() end)\n    return ok and type(held) == 'table' and held or {}\nend\n\n--- Keys sent by the latest load, for KeybindGuard's re-assert.\nlocal function sent_this_load()\n    windower._keybind_sent_this_load = windower._keybind_sent_this_load or {}\n    return windower._keybind_sent_this_load\nend\n\n---============================================================================\n--- OPERATIONS (ctx = {job, module, applied, api})\n---============================================================================\n\n--- The entries that apply now, minus the common ones that give way to a\n--- job or custom key applying on the same key.\n--- @return table active, table yielded\nlocal function get_active_binds(ctx)\n    local applying, memo, own_keys = {}, {}, {}\n    for _, bind in ipairs(ctx.module.binds or {}) do\n        if applies(bind, memo) then\n            applying[#applying + 1] = bind\n            if not bind._common and bind.key then own_keys[bind.key] = true end\n        end\n    end\n    local active, yielded = {}, {}\n    for _, bind in ipairs(applying) do\n        if KeyConflicts.yields(bind) and own_keys[bind.key] then\n            yielded[#yielded + 1] = bind\n        else\n            active[#active + 1] = bind\n        end\n    end\n    return active, yielded\nend\n\n--- Tell the conflicts of this pass (once per load each) and keep their keys\n--- for the HUD, which draws them in the conflict color.\n--- @return boolean True when the set of keys in conflict changed\nlocal function note_conflicts(ctx, active, yielded)\n    local list = KeyConflicts.live(active, yielded)\n    ctx.conflicts_told = ctx.conflicts_told or {}\n    KeyConflicts.report(ctx.job, list, ctx.conflicts_told)\n    local keys, before, changed = {}, ctx.module._conflict_keys or {}, false\n    for _, c in ipairs(list) do\n        keys[c.key] = true\n        if not before[c.key] then changed = true end\n    end\n    for key in pairs(before) do\n        if not keys[key] then changed = true end\n    end\n    ctx.module._conflict_keys = keys\n    return changed\nend\n\n--- Redraw the HUD now. KeybindUI.update() redraws only when a Mote state\n--- changed, and a key conflict is not a state: without this the red key\n--- appeared at the next state change.\nlocal function redraw_hud()\n    if not rawget(_G, 'keybind_ui_display') then return end\n    local ok, Display = pcall(require, 'shared/utils/ui/ui_display')\n    if not (ok and Display and Display.update_display) then return end\n    local drawn, err = pcall(Display.update_display)\n    if not drawn and Display.report_error then Display.report_error(err) end\nend\n\n--- Unbind what is down but no longer wanted. The keys about to be bound are\n--- left alone: a bind overwrites, and unbinding first opened the window in\n--- which ^numpad9 went dead after a reload (see keybind_guard.lua).\nlocal function clear_unwanted(ctx, desired, held)\n    local stale = {}\n    for _, bind in ipairs(ctx.module.binds or {}) do\n        if bind.key and bind.key ~= '' then stale[bind.key] = true end\n    end\n    for _, key in ipairs(ctx.module.retired_keys or {}) do stale[key] = true end\n    for key in pairs(bound_keys()) do stale[key] = true end\n    for key in pairs(stale) do\n        if not desired[key] then\n            if not held[key] then send_unbind(key) end\n            bound_keys()[key] = nil\n        end\n    end\nend\n\n--- Bind the keyed entries of `active`, in file order. A key already down\n--- with the same command (recorded on `windower`, which outlives the job\n--- file) is not sent again: a subjob change re-binds only what changed.\n--- @return number Keys wanted, number keys sent\nlocal function lay_down(active, desired, held)\n    local wanted, sent = 0, 0\n    for _, b in ipairs(active) do\n        local line = b.command and KeybindManager.bind_line(b)\n        if line and desired[b.key] == line then\n            wanted = wanted + 1\n            if held[b.key] then\n                bound_keys()[b.key] = line\n            elseif bound_keys()[b.key] ~= line then\n                local ok, err = send_bind(b.key, line)\n                if ok then\n                    sent = sent + 1\n                    bound_keys()[b.key] = line\n                    sent_this_load()[b.key] = line\n                else\n                    MessageFormatter.show_bind_failed_error(b.key, tostring(err or 'Command execution failed'))\n                end\n            end\n        end\n    end\n    return wanted, sent\nend\n\n--- Bind every applicable key.\n--- @param silent boolean|nil Skip the intro message\n--- @return boolean True if at least one key was bound\nlocal function bind_all(ctx, silent)\n    if not ctx.module.binds or #ctx.module.binds == 0 then\n        MessageFormatter.show_no_binds_error(ctx.job)\n        return false\n    end\n    local active, yielded = get_active_binds(ctx)\n    if not silent then\n        for _, problem in ipairs(KeyValidator.check(ctx.module.binds)) do\n            MessageFormatter.show_warning(ctx.job .. ' keybinds: ' .. problem)\n        end\n    end\n    if note_conflicts(ctx, active, yielded) then redraw_hud() end\n    local desired = key_map(active)\n    windower._keybind_sent_this_load = {}\n    local held = temp_held()\n    clear_unwanted(ctx, desired, held)\n    local bound, sent = lay_down(active, desired, held)\n    ctx.applied = desired\n    require('shared/utils/debug/trace_log').log('LOAD', 'keys %s: %d wanted, %d sent', ctx.job, bound, sent)\n    if bound > 0 then\n        if not silent then ctx.api.show_intro() end\n        return true\n    end\n    -- Zero keys down while some apply: every send failed. Silence here is\n    -- what made dead keys hard to chase.\n    if next(desired) then\n        MessageFormatter.show_error(('%s keybinds: none applied - keys will not respond'):format(ctx.job))\n    end\n    return false\nend\n\n--- Record a key's job line (nil: unbound) and send it, unless //gs c tb\n--- holds the key: then only the record changes, for `tb del` to give back.\n--- @return number Commands sent (0 or 1)\nlocal function put_key(key, command, held)\n    bound_keys()[key] = command\n    if held[key] then return 0 end\n    if command then send_bind(key, command) else send_unbind(key) end\n    return 1\nend\n\n--- Send only what changed since the last bind_all/refresh: a `visible` bind\n--- can come and go while the job stays the same.\n--- @return number Commands sent\nlocal function refresh(ctx)\n    local active, yielded = get_active_binds(ctx)\n    local conflicts_moved = note_conflicts(ctx, active, yielded)\n    local desired = key_map(active)\n    local held, moved, sent = temp_held(), 0, 0\n    for key in pairs(ctx.applied) do\n        -- A key that stays, with another command, is only re-bound below:\n        -- unbinding first leaves it dead in between (see clear_unwanted)\n        if desired[key] == nil then\n            moved, sent = moved + 1, sent + put_key(key, nil, held)\n        end\n    end\n    for key, command in pairs(desired) do\n        if ctx.applied[key] ~= command then\n            moved, sent = moved + 1, sent + put_key(key, command, held)\n        end\n    end\n    ctx.applied = desired\n    -- A partner's job or a Combat Mode change moved keys or conflicts: the\n    -- HUD rows and their red keys follow at once\n    if moved > 0 or conflicts_moved then redraw_hud() end\n    return sent\nend\n\n--- The job file unloads (file_unload): its keys stay down. The next load\n--- compares them with what it wants and sends only the difference\n--- (clear_unwanted + lay_down), instead of every key unbound here and bound\n--- again a moment later: that burst is where the traced client crashes hit.\n--- @return boolean\nlocal function unbind_all(ctx)\n    if not ctx.module.binds then return false end\n    require('shared/utils/debug/trace_log').log('LOAD', 'keys %s: kept for the next load', ctx.job)\n    ctx.applied = {}\n    return true\nend\n\n--- Job intro: bound keys count, macrobook and lockstyle info.\n--- Requiring the job's MACROBOOK/LOCKSTYLE modules here also defines their\n--- globals early; nothing relies on that any more (the first macro book and\n--- lockstyle wait for the facade: EntryKit.macro_and_lockstyle).\nlocal function show_intro(ctx)\n    local jl = ctx.job:lower()\n    local macro_info, lockstyle_info\n    local ok_m, macrobook = pcall(require, 'shared/jobs/' .. jl .. '/functions/' .. ctx.job .. '_MACROBOOK')\n    local get_macro = ok_m and type(macrobook) == 'table' and macrobook['get_' .. jl .. '_macro_info']\n    if get_macro then macro_info = get_macro() end\n    local ok_l, lockstyle = pcall(require, 'shared/jobs/' .. jl .. '/functions/' .. ctx.job .. '_LOCKSTYLE')\n    if ok_l and type(lockstyle) == 'table' and lockstyle.get_info then lockstyle_info = lockstyle.get_info() end\n\n    local keyed = {}\n    for _, bind in ipairs(get_active_binds(ctx)) do\n        if bind.key and bind.key ~= '' then keyed[#keyed + 1] = bind end\n    end\n    local title = ctx.job .. ' SYSTEM LOADED'\n    if macro_info or lockstyle_info then\n        MessageFormatter.show_system_intro_complete(title, keyed, macro_info, lockstyle_info)\n    else\n        MessageFormatter.show_system_intro(title, keyed)\n    end\nend\n\nlocal function show_binds(ctx)\n    MessageFormatter.show_keybind_list(ctx.job .. ' Keybinds', get_active_binds(ctx))\nend\n\n---============================================================================\n--- PUBLIC API\n---============================================================================\n\n--- Append the player's own states and keys (<JOB>_CUSTOM.lua, see\n--- shared/utils/custom/custom_states.lua). Guarded: a broken custom file\n--- must never cost the job its regular keys.\n--- @param job string\n--- @param module table\nlocal function add_custom_states(job, module)\n    if type(module.binds) ~= 'table' then return end\n    local ok, CustomStates = pcall(require, 'shared/utils/custom/custom_states')\n    if not ok or type(CustomStates) ~= 'table' then return end\n    local loaded, err = pcall(CustomStates.load, job, module.binds)\n    if not loaded then\n        MessageFormatter.show_error(job .. '_CUSTOM.lua: ' .. tostring(err))\n    end\nend\n\n--- Refresh the job's keys when the main hand changes weapon type, when one\n--- of its entries has a `weapon` field. Nothing is laid otherwise.\n--- @param binds table|nil The job's bind list, common keys included\nlocal function watch_own_weapon(binds)\n    local wanted = false\n    for _, bind in ipairs(binds or {}) do\n        if bind.weapon ~= nil then wanted = true break end\n    end\n    if not wanted then return end\n    local ok, AltStates = pcall(require, 'shared/utils/dualbox/alt_states')\n    if ok and type(AltStates) == 'table' and AltStates.on_weapon_change then\n        AltStates.on_weapon_change('keybinds', function() KeybindManager.refresh_active() end)\n    end\nend\n\n--- Give a job's keybind module its functions.\n--- @param job string Job code (\"PLD\")\n--- @param module table Holds .binds and optionally .retired_keys\n--- @return table The same module, with get_active_binds, bind_all, refresh,\n---   unbind_all, show_intro and show_binds attached, its Combat Mode row\n---   (shared/utils/core/combat_mode.lua), and the player's custom\n---   keys, then the character's common keys (_common/keys/COMMON_KEYBINDS.lua),\n---   appended to .binds\nfunction KeybindManager.create(job, module)\n    local ctx = {job = job, module = module, applied = {}, api = module}\n    -- The first module is the job's, the one bind_all lays the keys with. The\n    -- HUD requires the key file again; the require cache (config_loader.lua)\n    -- hands it the same module, but a require that failed is not cached and\n    -- runs again, so the first one is kept.\n    if rawget(_G, '_keybind_active') == nil then _G._keybind_active = module end\n    local function bind(fn) return function(...) return fn(ctx, ...) end end\n    module.get_active_binds = bind(get_active_binds)\n    module.bind_all = bind(bind_all)\n    module.refresh = bind(refresh)\n    module.unbind_all = bind(unbind_all)\n    module.show_intro = bind(show_intro)\n    module.show_binds = bind(show_binds)\n    -- A job change keeps the keys (unbind_all); GearSwap itself unloading\n    -- clears them. file_unload cannot tell the two apart, the addon's unload\n    -- event can: GearSwap drops this handler at the next file load.\n    pcall(windower.raw_register_event, 'unload', function()\n        -- (a key //gs c tb holds is tb's: its bind stays, and lay_down sends nothing over it at the next load; unbound\n        -- here, the key did neither tb's command nor the job's after //lua reload gearswap)\n        local lines, ok_h, held = {}, pcall(temp_held)\n        held = ok_h and held or {}\n        for key in pairs(bound_keys()) do\n            if not held[key] then lines[#lines + 1] = 'unbind ' .. key end\n        end\n        if #lines > 0 then windower.send_command(table.concat(lines, '; ')) end\n        windower._keybind_manager_bound = {}\n    end)\n    if type(module.binds) == 'table' then\n        local ok_c, CombatMode = pcall(require, 'shared/utils/core/combat_mode')\n        if ok_c and CombatMode then CombatMode.attach(job, module.binds) end\n        -- Treasure Mode: THF's own, Off and hidden on the other jobs\n        local ok_t, TreasureHunter = pcall(require, 'shared/utils/equipment/treasure_hunter')\n        if ok_t and TreasureHunter then TreasureHunter.optional.attach(job, module.binds) end\n        -- Jump Auto: every job, row shown on /DRG only\n        local ok_j, AutoJump = pcall(require, 'shared/utils/drg/auto_jump')\n        if ok_j and AutoJump then AutoJump.attach(job, module.binds) end\n    end\n    add_custom_states(job, module)\n    local ok, CommonKeybinds = pcall(require, 'shared/utils/keybinds/common_keybinds')\n    if ok and CommonKeybinds then\n        CommonKeybinds.merge_into(module.binds)\n    end\n    -- keys changed in the Atelier page (<Char>/atelier/overrides/keybind_overrides.lua), over all of the above\n    local ok_o, KeyOverrides = pcall(require, 'shared/utils/keybinds/key_overrides')\n    if ok_o and KeyOverrides then KeyOverrides.apply(job, module.binds) end\n    -- start values chosen in the Atelier page (<Char>/atelier/overrides/mode_overrides.lua): every mode exists by now,\n    -- and the HUD draws after this\n    local ok_m, ModeOverrides = pcall(require, 'shared/utils/core/mode_overrides')\n    if ok_m and ModeOverrides then ModeOverrides.apply(job) end\n    watch_own_weapon(module.binds)\n    -- A row without desc (a hand-written keybind or CUSTOM file) made the\n    -- HUD's first render raise and abort the job load: name it after its\n    -- state, else its command.\n    for _, b in ipairs(type(module.binds) == 'table' and module.binds or {}) do\n        if type(b) == 'table' and type(b.desc) ~= 'string' then\n            b.desc = tostring(b.state or b.command or b.key or '?')\n        end\n    end\n    return module\nend\n\n--- Every key this manager laid down taken off, through the paced queue: for a load that binds none of its own\n--- (shared/entry/no_job_file.lua), where the keys the last job file kept for the next load would stay live. A\n--- pending re-assert of the last load's keys (keybind_guard.lua) is cancelled first.\n--- @return number Keys unbound\nfunction KeybindManager.release_all()\n    windower._keybind_guard_seq = (windower._keybind_guard_seq or 0) + 1\n    windower._keybind_sent_this_load = {}\n    local keys, held = {}, temp_held()\n    for key in pairs(bound_keys()) do keys[#keys + 1] = key end\n    for _, key in ipairs(keys) do\n        if not held[key] then send_unbind(key) end\n        bound_keys()[key] = nil\n    end\n    return #keys\nend\n\n--- Keys in conflict at the last bind_all / refresh of the job loaded now\n--- (shared/utils/keybinds/key_conflicts.lua), for the HUD.\n--- @return table Set: key -> true\nfunction KeybindManager.conflict_keys()\n    local module = rawget(_G, '_keybind_active')\n    return module and module._conflict_keys or {}\nend\n\n--- //gs c keyconflicts: every conflict the loaded job's keys can run into,\n--- over all subjobs and partner jobs.\n--- @return boolean False when no job keys are loaded\nfunction KeybindManager.show_possible_conflicts()\n    local module = rawget(_G, '_keybind_active')\n    if not (module and module.binds) then return false end\n    KeyConflicts.show_possible(player and player.main_job or '?', module.binds)\n    return true\nend\n\n--- Refresh the keys of the job loaded now (see the `alt` field, Combat\n--- Mode): what another box plays changes without this job's own state\n--- changing.\n--- @return number Commands sent (0 when no job module is loaded)\nfunction KeybindManager.refresh_active()\n    local module = rawget(_G, '_keybind_active')\n    if module and module.refresh then return module.refresh() end\n    return 0\nend\n\n_G.KeybindManager = KeybindManager\n\nreturn KeybindManager\n", "shared/utils/messages/api/messages.lua": "---============================================================================\n--- Messages API - Unified public interface for all message operations\n---============================================================================\n--- Template path of the message system: formatters call M.send / M.job with\n--- a namespace and a key; the engine fills the template from\n--- data/jobs/<job>_messages.lua (3-letter job namespace) or\n--- data/systems/<namespace>_messages.lua, and the renderer prints it.\n---\n--- Usage:\n---   local M = require('shared/utils/messages/api/messages')\n---   M.send('NAMESPACE', 'key', {param = value})\n---   M.job('BLM', 'element_cycle', {job = ..., state_type = ..., element_color = ..., element = ...})\n---   M.error(\"Something went wrong\")\n---\n--- @file shared/utils/messages/api/messages.lua\n--- @author ejouanchicot\n--- @version 1.0\n--- @date Created: 2025-11-06\n---============================================================================\n\n-- Engine and renderer are loaded when the first message is sent\nlocal MessageEngine = nil\nlocal MessageRenderer = nil\n\nlocal function get_MessageEngine()\n    if not MessageEngine then\n        MessageEngine = require('shared/utils/messages/core/message_engine')\n    end\n    return MessageEngine\nend\n\nlocal function get_MessageRenderer()\n    if not MessageRenderer then\n        MessageRenderer = require('shared/utils/messages/core/message_renderer')\n    end\n    return MessageRenderer\nend\n\nlocal Messages = {}\n\nlocal MessageCore = require('shared/utils/messages/message_core')\n\n---============================================================================\n--- CORE MESSAGING API\n---============================================================================\n\n--- Send a message from any namespace\n--- @param namespace string \"BLM\", \"COMBAT\", \"SYSTEM\", etc.\n--- @param key string Message key\n--- @param params table? Parameters to inject into template\n--- @param options table? Rendering options {level, timestamp, channel}\n--- @return boolean success, number? message_length Length of visible message (excluding color codes)\nfunction Messages.send(namespace, key, params, options)\n    params = params or {}\n    options = options or {}\n\n    local ok, message, color = pcall(function()\n        return get_MessageEngine().format(namespace, key, params)\n    end)\n\n    if not ok then\n        get_MessageRenderer().show_error(string.format(\n            \"Failed to format message %s.%s: %s\",\n            namespace, key, tostring(message)\n        ))\n        return false, 0\n    end\n\n    -- Calculate visible length (strip color codes)\n    -- Color codes are: \\x1F + 1 byte (2 bytes total)\n    local visible_message = message:gsub(string.char(0x1F) .. \".\", \"\")\n    local message_length = #visible_message\n\n    -- Only used for the renderer statistics\n    options.namespace = namespace\n\n    get_MessageRenderer().send(message, color, options)\n\n    return true, message_length\nend\n\n---============================================================================\n--- CONVENIENCE METHODS\n---============================================================================\n\n--- Send a job-specific message\n--- @param job string Job code (\"BLM\", \"BRD\", \"RDM\", etc.)\n--- @param key string Message key\n--- @param params table? Parameters\n--- @return boolean success, number message_length Same as Messages.send\nfunction Messages.job(job, key, params)\n    return Messages.send(job, key, params)\nend\n\n--- Send a combat message (WS, TP, engaged, etc.)\n--- @param key string Message key\n--- @param params table? Parameters\n--- @return boolean success, number message_length Same as Messages.send\nfunction Messages.combat(key, params)\n    return Messages.send('COMBAT', key, params)\nend\n\n--- Send a magic message (spells, buffs, debuffs)\n--- @param key string Message key\n--- @param params table? Parameters\n--- @return boolean success, number message_length Same as Messages.send\nfunction Messages.magic(key, params)\n    return Messages.send('MAGIC', key, params)\nend\n\n--- Send an ability message (JA, pet commands)\n--- Note: there is no data/systems/ability_messages.lua, so any call prints a\n--- \"Failed to format message\" error instead. No caller exists today.\n--- @param key string Message key\n--- @param params table? Parameters\n--- @return boolean success, number message_length Same as Messages.send\nfunction Messages.ability(key, params)\n    return Messages.send('ABILITY', key, params)\nend\n\n--- Send a system message (errors, warnings, info, success)\n--- @param level string \"error\"|\"warning\"|\"info\"|\"success\"|\"debug\" (unknown = info)\n--- @param message string Message text\nfunction Messages.system(level, message)\n    local colors = {\n        error = 167,\n        warning = 200,\n        info = 122,\n        success = 158,\n        debug = 8\n    }\n\n    local color = colors[level] or colors.info\n    local formatted = string.format(\"[SYSTEM] %s\", message)\n\n    get_MessageRenderer().send(formatted, color, {\n        level = (level == \"error\" and 2) or (level == \"warning\" and 1) or 0\n    })\nend\n\n---============================================================================\n--- SYSTEM MESSAGE SHORTCUTS\n---============================================================================\n\n--- Show error message\n--- @param message string Error message\nfunction Messages.error(message)\n    Messages.system('error', message)\nend\n\n--- Show warning message\n--- @param message string Warning message\nfunction Messages.warning(message)\n    Messages.system('warning', message)\nend\n\n--- Show info message\n--- @param message string Info message\nfunction Messages.info(message)\n    Messages.system('info', message)\nend\n\n--- Show success message\n--- @param message string Success message\nfunction Messages.success(message)\n    Messages.system('success', message)\nend\n\n--- Show debug message\n--- @param message string Debug message\nfunction Messages.debug(message)\n    Messages.system('debug', message)\nend\n\n---============================================================================\n--- BUILDER PATTERN (Advanced Usage)\n---============================================================================\n\n--- Create a custom message builder for one-off messages\n--- @param template string Template with {placeholders}\n--- @param color number? Optional color code (default: 1)\n--- @return table Builder object\nfunction Messages.custom(template, color)\n    local builder = {\n        template = template,\n        color = color or 1,\n        params = {},\n        options = {}\n    }\n\n    --- Set a parameter (fluent interface)\n    --- @param key string Parameter name\n    --- @param value any Parameter value\n    --- @return table self (for chaining)\n    function builder:with(key, value)\n        self.params[key] = value\n        return self\n    end\n\n    --- Set importance level\n    --- @param level number 0=all, 1=important, 2=critical\n    --- @return table self\n    function builder:level(level)\n        self.options.level = level\n        return self\n    end\n\n    --- Build and send the message. Plain gsub replacement, not the engine:\n    --- color tags are not converted and keys are used as Lua patterns.\n    function builder:send()\n        local message = self.template\n        for key, value in pairs(self.params) do\n            local placeholder = \"{\" .. key .. \"}\"\n            message = message:gsub(placeholder, tostring(value), 1)\n        end\n\n        get_MessageRenderer().send(message, self.color, self.options)\n    end\n\n    --- Preview without sending (for testing)\n    --- @return string Preview string\n    function builder:preview()\n        local message = self.template\n        for key, value in pairs(self.params) do\n            local placeholder = \"{\" .. key .. \"}\"\n            message = message:gsub(placeholder, tostring(value), 1)\n        end\n        return string.format(\"[COLOR:%d] %s\", self.color, message)\n    end\n\n    return builder\nend\n\n---============================================================================\n--- CONFIGURATION API\n---============================================================================\n\n--- Configure the message system\n--- @param config table Configuration options\n---   - enabled: boolean (master toggle)\n---   - filter_level: number (0=all, 1=important, 2=critical)\n---   - color_mode: string (\"normal\", \"colorblind\", \"monochrome\")\n---   - timestamp: boolean (add timestamps)\nfunction Messages.config(config)\n    get_MessageRenderer().configure(config)\nend\n\n--- Get current configuration\n--- @return table Current config\nfunction Messages.get_config()\n    return get_MessageRenderer().get_config()\nend\n\n--- Toggle all messages on/off\n--- @return boolean New state\nfunction Messages.toggle()\n    return get_MessageRenderer().toggle()\nend\n\n--- Set filter level\n--- @param level number 0=all, 1=important, 2=critical\nfunction Messages.set_filter_level(level)\n    get_MessageRenderer().set_filter_level(level)\nend\n\n--- Set color mode for accessibility\n--- @param mode string \"normal\", \"colorblind\", \"monochrome\"\nfunction Messages.set_color_mode(mode)\n    get_MessageRenderer().set_color_mode(mode)\nend\n\n--- Toggle timestamps\n--- @return boolean New state\nfunction Messages.toggle_timestamp()\n    return get_MessageRenderer().toggle_timestamp()\nend\n\n---============================================================================\n--- DEBUGGING & UTILITIES\n---============================================================================\n\n--- Reset statistics\nfunction Messages.reset_stats()\n    get_MessageRenderer().reset_stats()\nend\n\n--- List all available messages in a namespace (for debugging)\n--- @param namespace string\nfunction Messages.list(namespace)\n    local keys = get_MessageEngine().list_keys(namespace)\n\n    add_to_chat(160, \"-----------------------------------------------------\")\n    add_to_chat(158, string.format(\"[Messages] Namespace: %s\", namespace))\n    add_to_chat(160, \"-----------------------------------------------------\")\n    for _, key in ipairs(keys) do\n        add_to_chat(1, \"  \" .. key)\n    end\n    add_to_chat(160, \"-----------------------------------------------------\")\n    add_to_chat(158, string.format(\"Total: %d messages\", #keys))\n    add_to_chat(160, \"-----------------------------------------------------\")\nend\n\n--- Clear engine cache (for development/testing)\nfunction Messages.clear_cache()\n    get_MessageEngine().clear_cache()\n    Messages.info(\"Message cache cleared\")\nend\n\n---============================================================================\n--- INTEGRATED TEST SUITE\n---============================================================================\n\n--- Silent test runner helper\nlocal function create_test_runner()\n    local passed = 0\n    local total = 0\n\n    local function test(fn)\n        total = total + 1\n        local renderer = get_MessageRenderer()\n        local old_show_error = renderer.show_error\n        renderer.show_error = function() end\n        local ok = pcall(fn)\n        renderer.show_error = old_show_error\n        if ok then passed = passed + 1 end\n        return ok\n    end\n\n    return test, function() return passed, total end\nend\n\nlocal TEST_GRAY   = string.char(0x1F, 160)\nlocal TEST_YELLOW = string.char(0x1F, 50)\nlocal TEST_GREEN  = string.char(0x1F, 158)\nlocal TEST_RED    = string.char(0x1F, 167)\n-- Built at each use: the width follows the player's chat.width\nlocal function test_separator() return string.rep(\"=\", MessageCore.SEPARATOR_WIDTH) end\n\n-- 22 jobs plus the general suite, in api/tests/test_<job>.lua (put back on\n-- 2026-10-01: 1635 tests, all passing). Order is the order they run in.\nlocal TEST_JOBS = {\n    'system',                                    -- magic, JA, WS\n    'whm', 'blm', 'rdm', 'sch', 'geo', 'blu',    -- mages\n    'brd', 'cor',                                -- support\n    'war', 'mnk', 'thf', 'pld', 'drk', 'bst',\n    'rng', 'sam', 'nin', 'drg', 'pup', 'dnc', 'run', 'smn',\n}\n\nlocal function test_module_path(job)\n    return 'shared/utils/messages/api/tests/test_' .. job:lower()\nend\n\nlocal function show_test_header(job_filter)\n    add_to_chat(121, TEST_GRAY .. test_separator())\n    if job_filter then\n        add_to_chat(121, TEST_YELLOW .. \"[Messages] Running \" .. job_filter .. \" Test Suite\")\n    else\n        add_to_chat(121, TEST_YELLOW .. \"[Messages] Running ALL Test Suites\")\n    end\n    add_to_chat(121, TEST_GRAY .. test_separator())\n    add_to_chat(121, \" \")\nend\n\n--- Names the caller could have passed, listed when the one they did is unknown.\nlocal function show_missing_test_file(test_file)\n    add_to_chat(167, TEST_RED .. \"Test file not found: \" .. test_file .. \".lua\")\n    add_to_chat(167, TEST_RED .. \"Available tests (22 total):\")\n    add_to_chat(167, TEST_RED .. \"  SYSTEM (general)\")\n    add_to_chat(167, TEST_RED .. \"  Mages: WHM, BLM, RDM, SCH, GEO, BLU\")\n    add_to_chat(167, TEST_RED .. \"  Support: BRD, COR\")\n    add_to_chat(167, TEST_RED .. \"  Melee: WAR, MNK, THF, PLD, DRK, BST\")\n    add_to_chat(167, TEST_RED .. \"  Melee: RNG, SAM, NIN, DRG, PUP, DNC, RUN\")\n    add_to_chat(121, TEST_GRAY .. test_separator())\nend\n\n--- Run one named suite, or every suite that exists.\n--- A suite missing from the full run is skipped silently: the list names jobs\n--- that have no test file yet, and that is not an error.\n--- @return boolean False only when a suite the caller NAMED does not exist\nlocal function run_test_suites(test, job_filter)\n    if job_filter then\n        local test_file = test_module_path(job_filter)\n        local ok, test_module = pcall(require, test_file)\n        if not (ok and test_module and test_module.run) then\n            show_missing_test_file(test_file)\n            return false\n        end\n        test_module.run(test)\n        return true\n    end\n\n    for _, job in ipairs(TEST_JOBS) do\n        local ok, test_module = pcall(require, test_module_path(job))\n        if ok and test_module and test_module.run then\n            test_module.run(test)\n        end\n    end\n    return true\nend\n\nlocal function show_test_results(passed, total)\n    add_to_chat(121, \" \")\n    add_to_chat(121, TEST_GRAY .. test_separator())\n\n    if passed == total then\n        add_to_chat(121, TEST_GREEN .. string.format(\"[OK] Message System: %d/%d tests PASSED\", passed, total))\n    else\n        add_to_chat(121, TEST_RED .. string.format(\"[FAIL] Message System: %d/%d tests FAILED (%d passed)\", total - passed, total, passed))\n    end\n\n    add_to_chat(121, TEST_GRAY .. test_separator())\nend\n\n--- Run integrated test suite (all jobs or specific job)\n--- Usage: M.test() or M.test('BRD') or M.test('system')\n--- @param job_filter string|nil Optional job filter (e.g., \"BRD\", \"GEO\", \"WAR\", \"system\")\nfunction Messages.test(job_filter)\n    local test, get_stats = create_test_runner()\n\n    if job_filter then\n        job_filter = job_filter:upper()\n    end\n\n    show_test_header(job_filter)\n\n    if not run_test_suites(test, job_filter) then\n        return false\n    end\n\n    local passed, total = get_stats()\n    show_test_results(passed, total)\n\n    return passed == total\nend\n\nreturn Messages\n", "shared/utils/messages/chat_palette.lua": "---============================================================================\n--- Chat Palette - the named chat colors, with the player's overrides\n---============================================================================\n--- One place for the chat colors that have a name: the message engine's\n--- template tags ({gray}, {green}...), the MessageColors constants\n--- (SUCCESS, ERROR...) and the formatters that used to write the raw code.\n---\n--- The player remaps a color in UI_CONFIG.lua (`chat.colors`) or in game\n--- (//gs c ui chatcolor green 204):\n---   green = 204      every green in the chat\n---   success = 204    only what MessageColors calls SUCCESS (see message_colors.lua)\n--- A color left out keeps its standard code, so without overrides every\n--- message is byte-identical to the fixed codes it replaces.\n---\n--- @file shared/utils/messages/chat_palette.lua\n--- @author ejouanchicot\n--- @version 1.0\n--- @date Created: 2026-09-25\n---============================================================================\n\nlocal ChatPalette = {}\n\n--- Standard FFXI chat code of each named color (the message engine's own\n--- codes). Orange depends on the region: read from MessageColors.\nlocal BASE = {\n    cyan = 13, lightblue = 207, white = 1, gray = 160, darkgray = 8,\n    green = 158, red = 167, yellow = 50, pink = 11, healgreen = 6,\n    enhancing = 206, enfeebling = 4, divine = 22, dark = 15, bluemagic = 219,\n    blue = 122, purple = 208, itemcolor = 63, orange = false,\n    -- Help screens (//gs c help, tb help, ui help)\n    gold = 220, aqua = 159, mustard = 36, amber = 68,\n}\n\n--- Tags that are another color under a second name. They follow that color\n--- unless the player sets them on their own.\nlocal ALIASES = {\n    jobtag = 'lightblue', separatorcolor = 'gray', spellcolor = 'cyan', warningcolor = 'orange',\n}\n\n--- Every name accepted as a palette color (BASE + ALIASES).\nChatPalette.NAMES = {}\nfor name in pairs(BASE) do ChatPalette.NAMES[name] = true end\nfor name in pairs(ALIASES) do ChatPalette.NAMES[name] = true end\n\n--- The player's overrides (chat.colors), or an empty table.\n--- @return table name -> code\nfunction ChatPalette.overrides()\n    local ok, UIStyle = pcall(require, 'shared/utils/ui/ui_style')\n    if not ok or not UIStyle then return {} end\n    local ok_get, style = pcall(UIStyle.get)\n    return ok_get and style and style.chat and style.chat.colors or {}\nend\n\nlocal function standard(name)\n    if name == 'orange' then\n        local MessageColors = require('shared/utils/messages/message_colors')\n        return MessageColors.region_orange()\n    end\n    return BASE[name]\nend\n\n--- Chat code of a named color: the player's code when set, else the\n--- standard one. An alias follows its color unless set itself.\n--- @param name string Palette name (\"gray\", \"jobtag\"...)\n--- @return number|nil Code, nil for an unknown name\nfunction ChatPalette.code(name)\n    local overrides = ChatPalette.overrides()\n    if overrides[name] then return overrides[name] end\n    local base = ALIASES[name]\n    if base then return ChatPalette.code(base) end\n    return standard(name)\nend\n\n--- Inline chat color code (0x1F + code) of a named color.\n--- @param name string Palette name\n--- @return string\nfunction ChatPalette.tag(name)\n    return string.char(0x1F, ChatPalette.code(name) or 1)\nend\n\n---============================================================================\n--- JOB TAG ([RDM/DRK] in front of messages)\n---============================================================================\n\n--- False when the player turned the job tag off (chat.job_tag = false).\n--- @return boolean\nfunction ChatPalette.show_job_tag()\n    local ok, UIStyle = pcall(require, 'shared/utils/ui/ui_style')\n    if not ok or not UIStyle then return true end\n    local ok_get, style = pcall(UIStyle.get)\n    return not (ok_get and style and style.chat and style.chat.job_tag == false)\nend\n\n--- A template without its job tag:\n---   \"[{job}] \"          (color tags aside) goes, with its trailing space\n---   \"[{job} Phalanx]\"   becomes \"[Phalanx]\"\n--- \"[{job}_COMMANDS]\" or \"Main Job: {job}\" are text, not a tag, and stay.\n--- @param template string\n--- @return string\nfunction ChatPalette.strip_job_tag(template)\n    return (template:gsub('(%b[])( ?)', function(bracket, space)\n        local inner = bracket:sub(2, -2):gsub('{(%w+)}', function(name)\n            return ChatPalette.NAMES[name] and '' or '{' .. name .. '}'\n        end)\n        if inner == '{job}' or inner == '{job_tag}' then return '' end\n        if inner:find('^{job} ') or inner:find('^{job_tag} ') then\n            return (bracket:gsub('{job_?t?a?g?} ', '', 1)) .. space\n        end\n        return nil\n    end))\nend\n\nreturn ChatPalette\n", "shared/utils/messages/chat_separators.lua": "---============================================================================\r\n--- Chat Separators - the player's separator options on every chat line\r\n---============================================================================\r\n--- UI_CONFIG.lua `chat` (//gs c ui separators / sepchar / sepcolor /\r\n--- chatwidth) chooses whether separator lines are shown, their character,\r\n--- color and width. Separators are written by many modules: the message\r\n--- templates, InfoBlock, HelpScreen, formatters that build their own lines,\r\n--- and diagnostic tools that write to the chat themselves. Rather than\r\n--- relying on each of them, every chat line passes through apply():\r\n---\r\n---   \"=====...\", \"-----...\"        a separator line: dropped when separators\r\n---                                  are off, else redrawn with the player's\r\n---                                  character and color; a full-width line\r\n---                                  (69 or more) follows chat.width\r\n---   \"===== TITLE =====\",\r\n---   \"--- name --------\"           a framed title: the runs of 3+ separator\r\n---                                  characters are dropped when off, else\r\n---                                  redrawn with the player's character\r\n---   anything else                 unchanged\r\n---\r\n--- With the standard options (on, \"=\", no color, width 69) every line is\r\n--- returned untouched.\r\n---\r\n--- @file    shared/utils/messages/chat_separators.lua\r\n--- @author  ejouanchicot\r\n--- @version 1.0\r\n--- @date    Created: 2026-09-27\r\n---============================================================================\r\n\r\nlocal ChatSeparators = {}\r\n\r\nlocal SEP_CLASS = '[=%-~%*#_]'\r\nlocal RUN = SEP_CLASS .. SEP_CLASS .. SEP_CLASS .. '+'\r\nlocal DEFAULT_WIDTH = 69\r\n\r\n--- The player's chat options, or nil when they are the standard ones.\r\nlocal function options()\r\n    local ok, UIStyle = pcall(require, 'shared/utils/ui/ui_style')\r\n    if not ok or not UIStyle or not UIStyle.get then return nil end\r\n    local chat = UIStyle.get().chat or {}\r\n    local char = chat.separator_char or '='\r\n    local width = chat.width or DEFAULT_WIDTH\r\n    if chat.separators ~= false and char == '=' and not chat.separator_color and width == DEFAULT_WIDTH then\r\n        return nil\r\n    end\r\n    return {on = chat.separators ~= false, char = char, color = chat.separator_color, width = width}\r\nend\r\n\r\n--- Split a chat line into color codes (0x1E / 0x1F + one byte) and text.\r\n--- @param text string\r\n--- @return table Array of {code = s} / {text = s}\r\nlocal function segments(text)\r\n    local out, i = {}, 1\r\n    while i <= #text do\r\n        local b = text:byte(i)\r\n        if b == 30 or b == 31 then\r\n            out[#out + 1] = {code = text:sub(i, i + 1)}\r\n            i = i + 2\r\n        else\r\n            local j = i\r\n            while j <= #text and text:byte(j) ~= 30 and text:byte(j) ~= 31 do j = j + 1 end\r\n            out[#out + 1] = {text = text:sub(i, j - 1)}\r\n            i = j\r\n        end\r\n    end\r\n    return out\r\nend\r\n\r\nlocal function plain_of(parts)\r\n    local out = {}\r\n    for _, p in ipairs(parts) do out[#out + 1] = p.text or '' end\r\n    return table.concat(out)\r\nend\r\n\r\n--- `char` repeated to `n` characters (a multi-character choice is cut).\r\nlocal function rule(char, n)\r\n    return string.rep(char, math.ceil(n / #char)):sub(1, n)\r\nend\r\n\r\n--- A separator line redrawn: its first color (or the player's), the\r\n--- player's character, full width when it was full width.\r\nlocal function redraw_line(parts, length, opts)\r\n    local color = opts.color and string.char(0x1F, opts.color) or ''\r\n    if color == '' then\r\n        for _, p in ipairs(parts) do\r\n            if p.code then color = p.code break end\r\n        end\r\n    end\r\n    local n = length >= DEFAULT_WIDTH and opts.width or length\r\n    return color .. rule(opts.char, n)\r\nend\r\n\r\n--- Index of the text segment holding the title's last separator run.\r\nlocal function last_run_segment(parts)\r\n    for i = #parts, 1, -1 do\r\n        if parts[i].text and parts[i].text:find(RUN) then return i end\r\n    end\r\nend\r\n\r\n--- A framed title: separator runs dropped (off) or redrawn with the\r\n--- player's character; a full-width title follows chat.width through its\r\n--- last run.\r\nlocal function redraw_title(parts, opts, length)\r\n    local out, last = {}, last_run_segment(parts)\r\n    local delta = length >= DEFAULT_WIDTH and (opts.width - length) or 0\r\n    for i, p in ipairs(parts) do\r\n        if p.code then\r\n            out[#out + 1] = p.code\r\n        elseif opts.on then\r\n            local text = p.text:gsub(RUN, function(run) return rule(opts.char, #run) end)\r\n            if i == last and delta ~= 0 then\r\n                text = text:gsub('(' .. RUN .. ')(%s*)$', function(run, tail)\r\n                    return rule(opts.char, math.max(3, #run + delta)) .. tail\r\n                end)\r\n            end\r\n            out[#out + 1] = text\r\n        else\r\n            out[#out + 1] = (p.text:gsub('%s*' .. RUN .. '%s*', ' '))\r\n        end\r\n    end\r\n    local line = table.concat(out)\r\n    if not opts.on then line = '  ' .. line:gsub('^%s+', ''):gsub('%s+$', '') end\r\n    return line\r\nend\r\n\r\n--- The chat line as the player's separator options want it.\r\n--- @param text any The line about to be written\r\n--- @return any The line to write, or nil to write nothing\r\nfunction ChatSeparators.apply(text)\r\n    if type(text) ~= 'string' or not text:find(SEP_CLASS .. SEP_CLASS .. SEP_CLASS) then return text end\r\n    local opts = options()\r\n    if not opts then return text end\r\n    local parts = segments(text)\r\n    local trimmed = plain_of(parts):match('^%s*(.-)%s*$')\r\n    if #trimmed >= 5 and not trimmed:find('[^=%-~%*#_]') then\r\n        if not opts.on then return nil end\r\n        return redraw_line(parts, #trimmed, opts)\r\n    end\r\n    if trimmed:find('^' .. RUN .. '%s') and trimmed:find('%s' .. RUN .. '$') then\r\n        return redraw_title(parts, opts, #plain_of(parts))\r\n    end\r\n    return text\r\nend\r\n\r\nreturn ChatSeparators\r\n", "shared/utils/messages/core/message_engine.lua": "---============================================================================\r\n--- Message Engine - Template compilation and formatting\r\n---============================================================================\r\n--- Loads a namespace's template file on first use (data/jobs/ for 3-letter\r\n--- all-caps namespaces, data/systems/ otherwise), compiles each template once\r\n--- and caches the compiled function.\r\n---\r\n--- @file shared/utils/messages/core/message_engine.lua\r\n--- @author ejouanchicot\r\n--- @version 1.0\r\n--- @date Created: 2025-11-06\r\n---============================================================================\r\n\r\nlocal MessageEngine = {}\r\n\r\n-- Only used for the region-specific orange.\r\nlocal MessageColors = require('shared/utils/messages/message_colors')\r\n\r\n-- Compiled templates, keyed by template string. Like every module local, this\r\n-- is rebuilt each time GearSwap loads a job: require is cached per sandbox.\r\nlocal _template_cache = {}\r\n\r\n-- Loaded namespace tables, keyed by namespace\r\nlocal _message_data = {}\r\n\r\n-- The two tables above are always empty at this point, so this reset changes\r\n-- nothing; kept because _G.MESSAGE_ENGINE_LOADED is listed by global_probe.\r\nif _G.MESSAGE_ENGINE_LOADED then\r\n    _template_cache = {}\r\n    _message_data = {}\r\nend\r\n_G.MESSAGE_ENGINE_LOADED = true\r\n\r\nlocal ChatPalette = require('shared/utils/messages/chat_palette')\r\n\r\n-- Color tag -> inline FFXI color code (0x1F followed by the code byte).\r\n-- These are the standard codes and the list of known tags; a message takes\r\n-- its codes from ChatPalette at each render, so the player's chat.colors\r\n-- (UI_CONFIG.lua) apply without a reload.\r\n-- These codes are this engine's own: they do not all match MessageColors\r\n-- (e.g. cyan is 13 here, MessageColors.SPELL is 205). Only orange and\r\n-- warningcolor are read from MessageColors.\r\nlocal COLOR_CODES = {\r\n    -- Main colors\r\n    cyan = string.char(0x1F, 13),     -- Cyan (spells) - SPELL color\r\n    lightblue = string.char(0x1F, 207), -- Light Blue (job tags)\r\n    white = string.char(0x1F, 1),     -- White (spells/abilities)\r\n    gray = string.char(0x1F, 160),    -- Gray (descriptions/arrows)\r\n    darkgray = string.char(0x1F, 8),  -- Dark Gray (debug headers)\r\n\r\n    -- Status colors\r\n    green = string.char(0x1F, 158),   -- Green (success/buffs)\r\n    red = string.char(0x1F, 167),     -- Red (errors/debuffs)\r\n    yellow = string.char(0x1F, 50),   -- Yellow (JA)\r\n    pink = string.char(0x1F, 11),     -- Pink/Rose (WS/Damage - code 011)\r\n    healgreen = string.char(0x1F, 6), -- Heal Green (Healing spells - code 006)\r\n    enhancing = string.char(0x1F, 206), -- Enhancing Magic (buffs - code 206)\r\n    enfeebling = string.char(0x1F, 4), -- Enfeebling Magic (debuffs - code 004)\r\n    divine = string.char(0x1F, 22),   -- Divine Magic (holy dmg - code 022)\r\n    dark = string.char(0x1F, 15),     -- Dark Magic (drains/aspirs - code 015)\r\n    bluemagic = string.char(0x1F, 219), -- Blue Magic (BLU spells - code 219)\r\n    orange = string.char(0x1F, MessageColors.get_warning_color()),   -- Orange (warnings) - region-specific\r\n    blue = string.char(0x1F, 122),    -- Blue (info)\r\n    purple = string.char(0x1F, 208),  -- Purple (debuffs)\r\n\r\n    -- Help screens (//gs c help, tb help, ui help)\r\n    gold = string.char(0x1F, 220),    -- Help title\r\n    aqua = string.char(0x1F, 159),    -- Help commands\r\n    mustard = string.char(0x1F, 36),  -- Help separators and parameters\r\n    amber = string.char(0x1F, 68),    -- Help group headings\r\n\r\n    -- Semantic aliases. Tag names must not collide with template parameter\r\n    -- names: a parameter named like a tag is rendered as that color.\r\n    jobtag = string.char(0x1F, 207),  -- Same as lightblue (job tags)\r\n    separatorcolor = string.char(0x1F, 160), -- Same as gray (separators) - renamed to avoid conflict\r\n    spellcolor = string.char(0x1F, 13),    -- Same as cyan (spells) - renamed to avoid conflict\r\n    itemcolor = string.char(0x1F, 63),     -- Pale yellow (items) - code 063\r\n    warningcolor = string.char(0x1F, MessageColors.get_warning_color()),  -- Same as orange (warnings) - region-specific\r\n}\r\n\r\n---============================================================================\r\n--- TEMPLATE COMPILATION (Performance Critical)\r\n---============================================================================\r\n\r\n--- Compile a template into an optimized function\r\n--- Parse once, reuse N times\r\n--- Supports {param} for parameters and {color} for inline colors. A color\r\n--- runs until the next color tag; {/} is not recognized and is printed as is.\r\n--- @param template string Template with {placeholders} and {color} tags\r\n--- @return function Compiled template function\r\nlocal function compile_template(template)\r\n    -- The job tag option changes the template itself: cache per setting\r\n    local show_tag = ChatPalette.show_job_tag()\r\n    local cache_key = (show_tag and '1' or '0') .. template\r\n    if _template_cache[cache_key] then\r\n        return _template_cache[cache_key]\r\n    end\r\n    if not show_tag then\r\n        template = ChatPalette.strip_job_tag(template)\r\n    end\r\n\r\n    -- Split the template into literal / color / param parts\r\n    local parts = {}\r\n    local placeholders = {}\r\n    local pos = 1\r\n\r\n    while pos <= #template do\r\n        -- Next {color} or {param}\r\n        local open_start, open_end, content = template:find(\"{([%w_]+)}\", pos)\r\n\r\n        -- Determine next token\r\n        if not open_start then\r\n            -- No more tokens, rest is literal\r\n            if pos <= #template then\r\n                table.insert(parts, {\r\n                    type = \"literal\",\r\n                    value = template:sub(pos)\r\n                })\r\n            end\r\n            break\r\n        end\r\n\r\n        -- Literal text before token\r\n        if open_start > pos then\r\n            table.insert(parts, {\r\n                type = \"literal\",\r\n                value = template:sub(pos, open_start - 1)\r\n            })\r\n        end\r\n\r\n        -- Check if it's a color or parameter\r\n        if COLOR_CODES[content] then\r\n            -- It's a color code\r\n            table.insert(parts, {\r\n                type = \"color\",\r\n                color = content\r\n            })\r\n        else\r\n            -- It's a parameter\r\n            table.insert(parts, {\r\n                type = \"param\",\r\n                key = content\r\n            })\r\n            table.insert(placeholders, content)\r\n        end\r\n\r\n        pos = open_end + 1\r\n    end\r\n\r\n    -- Generate the compiled function (closure)\r\n    local compiled_fn = function(params)\r\n        local result_parts = {}\r\n\r\n        for _, part in ipairs(parts) do\r\n            if part.type == \"literal\" then\r\n                table.insert(result_parts, part.value)\r\n            elseif part.type == \"color\" then\r\n                -- Insert color code (the player's palette, else standard)\r\n                if COLOR_CODES[part.color] then\r\n                    table.insert(result_parts, ChatPalette.tag(part.color))\r\n                end\r\n            else -- param\r\n                local value = params[part.key]\r\n\r\n                if value == nil then\r\n                    error(string.format(\r\n                        \"MessageEngine: Missing parameter '%s' in template\",\r\n                        part.key\r\n                    ))\r\n                end\r\n                table.insert(result_parts, tostring(value))\r\n            end\r\n        end\r\n\r\n        return table.concat(result_parts)\r\n    end\r\n\r\n    -- Cache for performance\r\n    _template_cache[cache_key] = compiled_fn\r\n\r\n    return compiled_fn\r\nend\r\n\r\n---============================================================================\r\n--- DATA LOADING (Lazy Loading Pattern)\r\n---============================================================================\r\n\r\n--- Load message data from file (lazy loading)\r\n--- @param namespace string \"BLM\", \"COMBAT\", etc.\r\n--- @return boolean success\r\nfunction MessageEngine.load(namespace)\r\n    -- Already loaded?\r\n    if _message_data[namespace] then\r\n        return true\r\n    end\r\n\r\n    -- Determine path based on namespace\r\n    local path\r\n    if namespace:upper() == namespace and #namespace == 3 then\r\n        -- Job (3-letter uppercase: BLM, BRD, etc.)\r\n        path = 'shared/utils/messages/data/jobs/' .. namespace:lower() .. '_messages'\r\n    else\r\n        -- System (COMBAT, MAGIC, UI, etc.)\r\n        path = 'shared/utils/messages/data/systems/' .. namespace:lower() .. '_messages'\r\n    end\r\n\r\n    -- Try to load\r\n    local success, data = pcall(require, path)\r\n\r\n    if not success then\r\n        error(string.format(\r\n            \"MessageEngine: Failed to load namespace '%s' from '%s'\\nError: %s\",\r\n            namespace, path, tostring(data)\r\n        ))\r\n        return false\r\n    end\r\n\r\n    -- Validate data structure\r\n    if type(data) ~= \"table\" then\r\n        error(string.format(\r\n            \"MessageEngine: Invalid data for namespace '%s' - expected table, got %s\",\r\n            namespace, type(data)\r\n        ))\r\n        return false\r\n    end\r\n\r\n    -- Store in cache\r\n    _message_data[namespace] = data\r\n\r\n    return true\r\nend\r\n\r\n---============================================================================\r\n--- FORMATTING API\r\n---============================================================================\r\n\r\n--- Format a message from template\r\n--- @param namespace string \"BLM\", \"COMBAT\", etc.\r\n--- @param key string Message key\r\n--- @param params table Parameters to inject\r\n--- @return string message, number color\r\nfunction MessageEngine.format(namespace, key, params)\r\n    params = params or {}\r\n\r\n    -- Ensure data is loaded (lazy loading)\r\n    if not _message_data[namespace] then\r\n        local ok = MessageEngine.load(namespace)\r\n        if not ok then\r\n            return \"[ERROR] Failed to load \" .. namespace, 167\r\n        end\r\n    end\r\n\r\n    -- Get template data\r\n    local template_data = _message_data[namespace][key]\r\n    if not template_data then\r\n        error(string.format(\r\n            \"MessageEngine: Unknown message '%s.%s'\",\r\n            namespace, key\r\n        ))\r\n    end\r\n\r\n    -- Validate template data structure\r\n    if not template_data.template then\r\n        error(string.format(\r\n            \"MessageEngine: Missing 'template' field for '%s.%s'\",\r\n            namespace, key\r\n        ))\r\n    end\r\n\r\n    -- Compile template (cached)\r\n    local compiled = compile_template(template_data.template)\r\n\r\n    -- Format message\r\n    local message = compiled(params)\r\n    local color = template_data.color or 1\r\n\r\n    return message, color\r\nend\r\n\r\n---============================================================================\r\n--- UTILITY FUNCTIONS\r\n---============================================================================\r\n\r\n--- Get all keys in a namespace (for debugging)\r\n--- @param namespace string\r\n--- @return table keys\r\nfunction MessageEngine.list_keys(namespace)\r\n    if not _message_data[namespace] then\r\n        MessageEngine.load(namespace)\r\n    end\r\n\r\n    local keys = {}\r\n    for key, _ in pairs(_message_data[namespace] or {}) do\r\n        table.insert(keys, key)\r\n    end\r\n    table.sort(keys)\r\n\r\n    return keys\r\nend\r\n\r\n--- Clear cache (for testing/reloading)\r\nfunction MessageEngine.clear_cache()\r\n    _template_cache = {}\r\n    _message_data = {}\r\nend\r\n\r\n--- Get cache stats (for debugging)\r\n--- @return table stats\r\nfunction MessageEngine.get_stats()\r\n    local template_count = 0\r\n    for _ in pairs(_template_cache) do\r\n        template_count = template_count + 1\r\n    end\r\n\r\n    local namespace_count = 0\r\n    local message_count = 0\r\n    for _, data in pairs(_message_data) do\r\n        namespace_count = namespace_count + 1\r\n        for _ in pairs(data) do\r\n            message_count = message_count + 1\r\n        end\r\n    end\r\n\r\n    return {\r\n        compiled_templates = template_count,\r\n        loaded_namespaces = namespace_count,\r\n        total_messages = message_count\r\n    }\r\nend\r\n\r\n-- Read-only view of the colour tags, for message_validator.lua\r\nMessageEngine.COLOR_CODES = COLOR_CODES\r\n\r\nreturn MessageEngine\r\n", "shared/utils/messages/core/message_renderer.lua": "---============================================================================\n--- Message Renderer - Smart chat output with filtering and configuration\n---============================================================================\n--- Last step of the template path: applies the toggle, filter level, color\n--- scheme and timestamp settings, splits multi-line messages and calls\n--- add_to_chat. No production caller changes any setting, so the defaults\n--- below are what the player always gets.\n---\n--- @file shared/utils/messages/core/message_renderer.lua\n--- @author ejouanchicot\n--- @version 1.0\n--- @date Created: 2025-11-06\n---============================================================================\n\nlocal MessageRenderer = {}\n\n---============================================================================\n--- CONFIGURATION\n---============================================================================\n\n-- Global configuration\nlocal _config = {\n    enabled = true,                  -- Master toggle\n    filter_level = 0,                -- 0=all, 1=important, 2=critical\n    color_mode = \"normal\",           -- \"normal\", \"colorblind\", \"monochrome\"\n    timestamp = false,               -- Add timestamps\n    prefix_style = \"brackets\"        -- Not read anywhere\n}\n\n-- Color scheme definitions (accessibility)\nlocal COLOR_SCHEMES = {\n    normal = {\n        -- Standard FFXI chat colors\n        default = 1,\n        info = 122,\n        success = 158,\n        warning = 200,\n        error = 167,\n        debug = 8,\n        combat = 200,\n        magic = 1,\n        ability = 158\n    },\n\n    colorblind = {\n        -- High contrast, color-blind friendly\n        default = 1,\n        info = 122,      -- Blue\n        success = 122,   -- Blue instead of green\n        warning = 200,   -- Purple\n        error = 167,     -- Red\n        debug = 8,       -- Gray\n        combat = 200,\n        magic = 1,\n        ability = 122\n    },\n\n    monochrome = {\n        -- For players who prefer no colors\n        default = 1,\n        info = 1,\n        success = 1,\n        warning = 8,\n        error = 8,\n        debug = 8,\n        combat = 1,\n        magic = 1,\n        ability = 1\n    }\n}\n\n-- Statistics tracking\nlocal _stats = {\n    total_sent = 0,\n    by_namespace = {},\n    by_color = {},\n    errors = 0\n}\n\n---============================================================================\n--- RENDERING FUNCTIONS\n---============================================================================\n\n--- Send message to chat with rendering options\n--- @param message string The formatted message\n--- @param color number FFXI color code\n--- @param options table? {level = number (filter level), namespace = string (stats), channel = number (chat channel in place of the template's)}\nfunction MessageRenderer.send(message, color, options)\n    options = options or {}\n\n    -- Check if enabled (master toggle)\n    if not _config.enabled then\n        return\n    end\n\n    -- Check filter level\n    local level = options.level or 0\n    if level < _config.filter_level then\n        return -- Filtered out\n    end\n\n    -- Apply color scheme transformation\n    if _config.color_mode ~= \"normal\" then\n        color = MessageRenderer.transform_color(color)\n    end\n    -- A chat channel chosen by the caller (a block shown in the synthesis window:\n    -- info_block.lua spec.channel); the template's own colour codes stay\n    if options.channel then\n        color = options.channel\n    end\n\n    -- Ensure message is a string\n    message = tostring(message)\n\n    -- Add timestamp if enabled\n    if _config.timestamp then\n        local time = os.date(\"%H:%M:%S\")\n        message = string.format(\"[%s] %s\", time, message)\n    end\n\n    -- One add_to_chat per line (fixes FFXI alignment issues with \\n).\n    -- Empty lines are dropped: templates use \"\\n \\n\" for a blank line.\n    if message:find(\"\\n\") then\n        local lines = {}\n        for line in message:gmatch(\"[^\\n]+\") do\n            table.insert(lines, line)\n        end\n\n        for _, line in ipairs(lines) do\n            add_to_chat(color, line)\n        end\n    else\n        add_to_chat(color, message)\n    end\n\n    -- Update statistics\n    _stats.total_sent = _stats.total_sent + 1\n\n    if options.namespace then\n        _stats.by_namespace[options.namespace] = (_stats.by_namespace[options.namespace] or 0) + 1\n    end\n\n    _stats.by_color[color] = (_stats.by_color[color] or 0) + 1\nend\n\n--- Transform color code based on current color scheme\n--- @param color number Original color\n--- @return number Transformed color\nfunction MessageRenderer.transform_color(color)\n    local scheme = COLOR_SCHEMES[_config.color_mode]\n    if not scheme then\n        return color\n    end\n\n    -- Map common colors to semantic types\n    local color_map = {\n        [1] = scheme.default,\n        [8] = scheme.debug,\n        [122] = scheme.info,\n        [158] = scheme.success,\n        [167] = scheme.error,\n        [200] = scheme.warning\n    }\n\n    return color_map[color] or color\nend\n\n---============================================================================\n--- CONFIGURATION API\n---============================================================================\n\n--- Configure renderer settings\n--- @param config table Configuration options\nfunction MessageRenderer.configure(config)\n    for key, value in pairs(config) do\n        if _config[key] ~= nil then\n            _config[key] = value\n        end\n    end\nend\n\n--- Get current configuration\n--- @return table Current config\nfunction MessageRenderer.get_config()\n    return _config\nend\n\n--- Toggle all messages on/off\n--- @return boolean New state\nfunction MessageRenderer.toggle()\n    _config.enabled = not _config.enabled\n\n    local status = _config.enabled and \"enabled\" or \"disabled\"\n    add_to_chat(158, \"[Messages] System \" .. status)\n\n    return _config.enabled\nend\n\n--- Set filter level\n--- @param level number 0=all, 1=important, 2=critical\nfunction MessageRenderer.set_filter_level(level)\n    _config.filter_level = level\n\n    local levels = {\"all\", \"important\", \"critical\"}\n    add_to_chat(158, string.format(\n        \"[Messages] Filter level: %s\",\n        levels[level + 1] or \"unknown\"\n    ))\nend\n\n--- Set color mode\n--- @param mode string \"normal\", \"colorblind\", \"monochrome\"\nfunction MessageRenderer.set_color_mode(mode)\n    if not COLOR_SCHEMES[mode] then\n        add_to_chat(167, \"[Messages] Unknown color mode: \" .. mode)\n        return\n    end\n\n    _config.color_mode = mode\n    add_to_chat(158, \"[Messages] Color mode: \" .. mode)\nend\n\n--- Toggle timestamps\n--- @return boolean New state\nfunction MessageRenderer.toggle_timestamp()\n    _config.timestamp = not _config.timestamp\n\n    local status = _config.timestamp and \"enabled\" or \"disabled\"\n    add_to_chat(158, \"[Messages] Timestamps \" .. status)\n\n    return _config.timestamp\nend\n\n---============================================================================\n--- STATISTICS & DEBUGGING\n---============================================================================\n\n--- Reset statistics\nfunction MessageRenderer.reset_stats()\n    _stats = {\n        total_sent = 0,\n        by_namespace = {},\n        by_color = {},\n        errors = 0\n    }\n    add_to_chat(158, \"[Messages] Statistics reset\")\nend\n\n---============================================================================\n--- ERROR HANDLING\n---============================================================================\n\n--- Show error message\n--- @param error_msg string Error message\nfunction MessageRenderer.show_error(error_msg)\n    _stats.errors = _stats.errors + 1\n    add_to_chat(167, \"[MessageSystem ERROR] \" .. error_msg)\nend\n\nreturn MessageRenderer\n", "shared/utils/messages/data/systems/status_messages.lua": "---============================================================================\r\n--- STATUS Message Data - Status Messages (error, warning, success, info)\r\n---============================================================================\r\n--- Pure data file for status messages\r\n--- Loaded by the message engine when a formatter sends a key from it (api/messages.lua)\r\n---\r\n--- @file shared/utils/messages/data/systems/status_messages.lua\r\n--- @author ejouanchicot\r\n--- @version 1.0\r\n--- @date Created: 2025-11-06\r\n---============================================================================\r\n\r\nlocal MessageColors = require('shared/utils/messages/message_colors')\r\n\r\nreturn {\r\n    ---========================================================================\r\n    --- BASIC STATUS MESSAGES\r\n    ---========================================================================\r\n\r\n    error = {\r\n        template = \"Error: {message}\",\r\n        color = 167\r\n    },\r\n\r\n    warning = {\r\n        template = \"Warning: {message}\",\r\n        color = MessageColors.get_warning_color()\r\n    },\r\n\r\n    success = {\r\n        template = \"{message}\",\r\n        color = 158\r\n    },\r\n\r\n    info = {\r\n        template = \"{message}\",\r\n        color = 1\r\n    },\r\n\r\n    -- Mote's own state line, reproduced for when the HUD is hidden and the\r\n    -- new value would otherwise go unreported. Colour 122 is Mote's.\r\n    state_display = {\r\n        template = \"{state_name}: {value}\",\r\n        color = 122\r\n    },\r\n\r\n    ---========================================================================\r\n    --- TP STATUS MESSAGES\r\n    ---========================================================================\r\n\r\n    tp_ready = {\r\n        template = \"{gray}=====================================================================\\n{gray}[{lightblue}{job}{gray}] {yellow}TP >= {tp_value} {gray}({green}READY{gray})\\n{gray}=====================================================================\",\r\n        color = 1\r\n    },\r\n\r\n    tp_required = {\r\n        template = \"{gray}=====================================================================\\n{gray}[{lightblue}{job}{gray}] Ability: {yellow}{ability} {gray}({red}{current_tp}/{required_tp} TP{gray})\\n{gray}=====================================================================\",\r\n        color = 1\r\n    },\r\n}\r\n", "shared/utils/messages/formatters/ui/message_status.lua": "---============================================================================\r\n--- Status Message Formatter - Status Messages\r\n---============================================================================\r\n--- Backs MessageFormatter.show_error/warning/success/info (one string each),\r\n--- state display and TP lines. Templates: data/systems/status_messages.lua.\r\n---\r\n--- @file    shared/utils/messages/formatters/ui/message_status.lua\r\n--- @author  ejouanchicot\r\n--- @version 2.0\r\n--- @date    Created: 2025-11-06\r\n---============================================================================\r\n\r\nlocal MessageStatus = {}\r\nlocal M = require('shared/utils/messages/api/messages')\r\n\r\n---============================================================================\r\n--- BASIC STATUS MESSAGES\r\n---============================================================================\r\n\r\n--- Show error message\r\n--- @param message string Error message text\r\nfunction MessageStatus.show_error(message)\r\n    M.send('STATUS', 'error', {message = message})\r\nend\r\n\r\n--- Show warning message\r\n--- @param message string Warning message text\r\nfunction MessageStatus.show_warning(message)\r\n    M.send('STATUS', 'warning', {message = message})\r\nend\r\n\r\n--- Show success message\r\n--- @param message string Success message text\r\nfunction MessageStatus.show_success(message)\r\n    M.send('STATUS', 'success', {message = message})\r\nend\r\n\r\n--- Show info message\r\n--- @param message string Info message text\r\nfunction MessageStatus.show_info(message)\r\n    M.send('STATUS', 'info', {message = message})\r\nend\r\n\r\n--- Show a state change the way Mote-Include would have shown it.\r\n--- @param state_name string Name of the state that changed\r\n--- @param value string New value of that state\r\nfunction MessageStatus.show_state_display(state_name, value)\r\n    M.send('STATUS', 'state_display', {\r\n        state_name = state_name,\r\n        value = value\r\n    })\r\nend\r\n\r\n---============================================================================\r\n--- TP STATUS MESSAGES\r\n---============================================================================\r\n\r\n--- Show TP ready message\r\n--- @param job string Job abbreviation (e.g., \"SAM\")\r\n--- @param tp_value number TP threshold reached\r\nfunction MessageStatus.show_tp_ready(job, tp_value)\r\n    M.send('STATUS', 'tp_ready', {\r\n        job = job,\r\n        tp_value = tostring(tp_value)\r\n    })\r\nend\r\n\r\n---============================================================================\r\n--- MODULE EXPORT\r\n---============================================================================\r\n\r\nreturn MessageStatus\r\n", "shared/utils/messages/message_colors.lua": "---============================================================================\r\n--- Message Colors - Centralized Color Configuration for All Messages\r\n---============================================================================\r\n--- Central configuration for all color codes used in the messaging system.\r\n--- This ensures consistency across all message types and makes it easy to\r\n--- adjust colors globally.\r\n---\r\n--- REGION-SPECIFIC COLORS:\r\n--- Orange/Warning color codes differ by FFXI region (POL account):\r\n---   US Region (NBCP): Code 057 = Orange\r\n---   EU Region (BQJS): Code 003 = Orange equivalent for EU\r\n---   JP Region: Code 057 = Orange\r\n---\r\n--- Region is configured in <Char>/_common/display/REGION_CONFIG.lua (exposed by the\r\n--- entry point as _G.RegionConfig). Users add their character name to that\r\n--- file to set their region.\r\n---\r\n--- _G.ORANGE_COLOR_CODE and _G.DETECTED_FFXI_REGION are also honored as\r\n--- overrides, but nothing sets them: //gs c setregion is not implemented.\r\n---\r\n--- @file shared/utils/messages/message_colors.lua\r\n--- @author ejouanchicot\r\n--- @version 1.4\r\n--- @date Created: 2025-10-02 | Updated: 2025-10-12 - Added config-based region detection\r\n---============================================================================\r\n\r\nlocal MessageColors = {}\r\n\r\n-- _G.RegionConfig is read at each use, not at require time: entry files set it\r\n-- after config_loader, which already pulls this module in, and require is\r\n-- cached from that point on.\r\nlocal function region_config()\r\n    return rawget(_G, 'RegionConfig') or {}\r\nend\r\n\r\n---============================================================================\r\n--- REGION DETECTION\r\n---============================================================================\r\n\r\n--- Get orange/warning color code based on detected region\r\n--- @return number warning_code Region-specific warning color code\r\nlocal function get_region_orange()\r\n    -- Priority 1: explicit color override (no setter exists today)\r\n    if _G.ORANGE_COLOR_CODE then\r\n        return _G.ORANGE_COLOR_CODE\r\n    end\r\n\r\n    -- Priority 2: explicit region override (no setter exists today)\r\n    if _G.DETECTED_FFXI_REGION then\r\n        if _G.DETECTED_FFXI_REGION == \"EU\" then\r\n            return 003  -- Orange equivalent for EU\r\n        else\r\n            return 057  -- Orange (US/JP)\r\n        end\r\n    end\r\n\r\n    -- Priority 3: <Char>/_common/display/REGION_CONFIG.lua\r\n    local RegionConfig = region_config()\r\n    if RegionConfig.get_region and player and player.name then\r\n        local region = RegionConfig.get_region(player.name)\r\n        if RegionConfig.get_orange_code then\r\n            return RegionConfig.get_orange_code(region)\r\n        end\r\n    end\r\n\r\n    -- Priority 4: Default to US (most common)\r\n    return 057\r\nend\r\n\r\nlocal region_traced = false\r\n\r\n--- Record which orange this load ended up with (//gs c trace), once the\r\n--- region config is there.\r\n--- @param code number\r\nlocal function trace_region(code)\r\n    local RegionConfig = region_config()\r\n    if region_traced or not RegionConfig.get_region then return end\r\n    region_traced = true\r\n    local ok, Trace = pcall(require, 'shared/utils/debug/trace_log')\r\n    if ok and Trace then\r\n        local region = player and player.name and RegionConfig.get_region(player.name)\r\n        Trace.log('REGION', 'orange %s (region %s)', code, region)\r\n    end\r\nend\r\n\r\n---============================================================================\r\n--- FLAT COLOR DEFINITIONS (all at root level for easy access)\r\n---============================================================================\r\n\r\n-- Standard codes. MessageColors.X reads them through the metatable below,\r\n-- so the player's chat.colors (UI_CONFIG.lua) can replace any of them.\r\nlocal DEFAULTS = {}\r\n\r\n-- Action types\r\nDEFAULTS.SPELL = 205          -- Cyan - Magic spells\r\nDEFAULTS.JA = 50              -- Yellow - Job Abilities\r\nDEFAULTS.WS = 50              -- Yellow - Weapon Skills\r\nDEFAULTS.ITEM_COLOR = 211     -- Item color - All items\r\n\r\n-- UI Elements\r\nDEFAULTS.SEPARATOR = 160      -- Gray - Separators, info text\r\nDEFAULTS.GRAY = 160           -- Gray - Alias for SEPARATOR\r\nDEFAULTS.JOB_TAG = 207        -- Light Blue - Job tags [WAR]\r\nDEFAULTS.HEADER = 207         -- Light Blue - Headers\r\nDEFAULTS.INFO_HEADER = 207    -- Light Blue - Info headers (alias)\r\nDEFAULTS.INFO = 158           -- Green - Info text/counts\r\n\r\n-- Status/States\r\nDEFAULTS.SUCCESS = 158        -- Green - Success, Ready, Active\r\nDEFAULTS.ERROR = 167          -- Red - Errors\r\nDEFAULTS.WARNING = 057        -- Region-specific Orange - Warnings (resolved at use)\r\nDEFAULTS.DEBUFF = 208         -- Purple - Debuffs\r\nDEFAULTS.READY = 158          -- Green - Ready state\r\nDEFAULTS.ACTIVE = 158         -- Green - Active state\r\nDEFAULTS.COOLDOWN = 125       -- Dark red - Cooldown timers\r\nDEFAULTS.BLOCKED = 167        -- Red - Blocked actions\r\nDEFAULTS.WS_BLOCKED = 200     -- Orange - WS blocked\r\nDEFAULTS.RANGE_ERROR = 167    -- Red - Range errors\r\n\r\n-- TP Colors\r\nDEFAULTS.TP_NORMAL = 1        -- White - 1000-1999 TP\r\nDEFAULTS.TP_ENHANCED = 207    -- Light Blue - 2000-2999 TP\r\nDEFAULTS.TP_ULTIMATE = 158    -- Green - 3000 TP\r\nDEFAULTS.TP_LABEL = 160       -- Gray - TP label\r\n\r\n-- System/Keybinds\r\nDEFAULTS.SYSTEM_LOADED = 207  -- Light Blue - System loaded messages\r\nDEFAULTS.KEYBIND_KEY = 158    -- Green - Keybind keys\r\nDEFAULTS.KEYBIND_DESC = 160   -- Gray - Keybind descriptions\r\n\r\n--- Palette color each constant follows when the player remaps that color\r\n--- (chat.colors.green = N also changes SUCCESS, READY...). Constants with no\r\n--- palette color of the same code (SPELL 205, ITEM_COLOR 211, COOLDOWN 125,\r\n--- WS_BLOCKED 200) only change when set by their own name.\r\nlocal FOLLOWS = {\r\n    JA = 'yellow', WS = 'yellow',\r\n    SEPARATOR = 'gray', GRAY = 'gray', TP_LABEL = 'gray', KEYBIND_DESC = 'gray',\r\n    JOB_TAG = 'lightblue', HEADER = 'lightblue', INFO_HEADER = 'lightblue',\r\n    TP_ENHANCED = 'lightblue', SYSTEM_LOADED = 'lightblue',\r\n    INFO = 'green', SUCCESS = 'green', READY = 'green', ACTIVE = 'green',\r\n    TP_ULTIMATE = 'green', KEYBIND_KEY = 'green',\r\n    ERROR = 'red', BLOCKED = 'red', RANGE_ERROR = 'red',\r\n    WARNING = 'orange', DEBUFF = 'purple', TP_NORMAL = 'white',\r\n}\r\n\r\n--- Constant names a player can set in chat.colors (lowercase: success...).\r\nMessageColors.SETTABLE = {}\r\nfor name in pairs(DEFAULTS) do MessageColors.SETTABLE[name:lower()] = true end\r\n\r\nlocal function player_colors()\r\n    local ok, ChatPalette = pcall(require, 'shared/utils/messages/chat_palette')\r\n    return ok and ChatPalette and ChatPalette.overrides() or {}\r\nend\r\n\r\n-- MessageColors.SUCCESS etc.: the player's own code for that name, else the\r\n-- code of the palette color it follows when the player remapped it, else\r\n-- the standard code. Read at each use, like before (callers never cached).\r\nsetmetatable(MessageColors, {__index = function(_, key)\r\n    local default = DEFAULTS[key]\r\n    if default == nil then return nil end\r\n    if key == 'WARNING' then\r\n        default = get_region_orange()\r\n        trace_region(default)\r\n    end\r\n    local colors = player_colors()\r\n    local own = colors[key:lower()]\r\n    if own then return own end\r\n    local follows = FOLLOWS[key]\r\n    if follows and colors[follows] then return colors[follows] end\r\n    return default\r\nend})\r\n\r\n---============================================================================\r\n--- HELPER FUNCTIONS\r\n---============================================================================\r\n\r\n--- Get color code for TP value\r\n--- @param tp number TP value\r\n--- @return number color_code The color code for the TP value\r\nfunction MessageColors.get_tp_color(tp)\r\n    if tp >= 3000 then\r\n        return MessageColors.TP_ULTIMATE\r\n    elseif tp >= 2000 then\r\n        return MessageColors.TP_ENHANCED\r\n    else\r\n        return MessageColors.TP_NORMAL\r\n    end\r\nend\r\n\r\n--- Get current orange/warning color dynamically (for runtime calls)\r\n--- @return number warning_code Current region-specific warning color\r\nfunction MessageColors.get_warning_color()\r\n    local colors = player_colors()\r\n    return colors.warning or colors.orange or get_region_orange()\r\nend\r\n\r\n--- The region's orange, ignoring the player's colors (standard for the\r\n--- palette's orange: reading WARNING there would loop back to the palette).\r\n--- @return number\r\nfunction MessageColors.region_orange()\r\n    return get_region_orange()\r\nend\r\n\r\nreturn MessageColors\r\n", "shared/utils/messages/message_core.lua": "---============================================================================\n--- Message Core - Base colors and utilities for all message modules\n---============================================================================\n--- Color-code builder, job tag, fixed-width separator and a few direct-output\n--- helpers. The helpers call add_to_chat themselves: this module is a last\n--- rendering level, like the formatters (CODE_QUALITY §6).\n---\n--- @file shared/utils/messages/message_core.lua\n--- @author ejouanchicot\n--- @version 2.0\n--- @date Created: 2025-10-02 | Updated: 2025-10-02 - Centralized color configuration\n---============================================================================\n\nlocal MessageCore = {}\n\nlocal MessageColors = require('shared/utils/messages/message_colors')\nMessageCore.COLORS = MessageColors\n\n--- Standard width of every chat separator line, sized to the chat window.\nMessageCore.DEFAULT_SEPARATOR_WIDTH = 69\n\n--- MessageCore.SEPARATOR_WIDTH is read at each use: the player's chat.width\n--- (UI_CONFIG.lua, //gs c ui chatwidth) when set, else the standard 69.\nsetmetatable(MessageCore, {__index = function(_, key)\n    if key ~= 'SEPARATOR_WIDTH' then return nil end\n    local ok, UIStyle = pcall(require, 'shared/utils/ui/ui_style')\n    local width = ok and UIStyle.get().chat.width\n    return width or MessageCore.DEFAULT_SEPARATOR_WIDTH\nend})\n\n--- Create FFXI color code string\n--- @param color_code number FFXI color code (1-255)\n--- @return string Formatted color code for inline use\nfunction MessageCore.create_color_code(color_code)\n    if not color_code or type(color_code) ~= \"number\" then\n        error(\"create_color_code: Invalid color_code (got \" .. tostring(color_code) .. \" of type \" .. type(color_code) .. \")\")\n    end\n    return string.char(0x1F, color_code)\nend\n\n--- Convert GearSwap key symbols to user-friendly display names\n--- @param key string Raw key binding (e.g., \"!1\", \"^f1\")\n--- @return string User-friendly key name (e.g., \"ALT+1\", \"CTRL+F1\")\nfunction MessageCore.convert_key_display(key)\n    local converted = key\n    converted = converted:gsub(\"!\", \"ALT+\")\n    converted = converted:gsub(\"%^\", \"CTRL+\")\n    converted = converted:gsub(\"~\", \"SHIFT+\")\n    converted = converted:gsub(\"@\", \"WIN+\")\n    converted = converted:gsub(\"f(%d+)\", \"F%1\")\n    return converted:upper()\nend\n\n--- Display a colored separator line (FIXED LENGTH)\n--- @param length number Ignored - separator is always SEPARATOR_WIDTH characters\nfunction MessageCore.show_separator(length)\n    -- Player's choice in UI_CONFIG.lua `chat` (on/off, character, color)\n    local ok, UIStyle = pcall(require, 'shared/utils/ui/ui_style')\n    local chat = ok and UIStyle.get().chat or {}\n    if chat.separators == false then return end\n\n    local char = chat.separator_char or \"=\"\n    local color = MessageCore.create_color_code(chat.separator_color or MessageCore.COLORS.SEPARATOR)\n    local separator = string.rep(char, math.ceil(MessageCore.SEPARATOR_WIDTH / #char)):sub(1, MessageCore.SEPARATOR_WIDTH)\n    add_to_chat(1, color .. separator)\nend\n\n--- \"[RDM/DRK] \" in front of a message, or \"\" when the player turned the job\n--- tag off (UI_CONFIG.lua chat.job_tag = false, //gs c ui jobtag off).\n--- @return string\nfunction MessageCore.job_prefix()\n    local ok, ChatPalette = pcall(require, 'shared/utils/messages/chat_palette')\n    if ok and ChatPalette and not ChatPalette.show_job_tag() then return \"\" end\n    return \"[\" .. MessageCore.get_job_tag() .. \"] \"\nend\n\n--- Get dynamic job tag [MAIN/SUB] based on current player state\n--- @return string Job tag (e.g., \"WAR/SAM\", \"PLD/BLU\", \"PLD\")\nfunction MessageCore.get_job_tag()\n    if not player then return \"JOB\" end\n\n    local main_job = player.main_job or \"JOB\"\n    local sub_job = player.sub_job\n\n    if sub_job and sub_job ~= \"NON\" and sub_job ~= \"\" then\n        return string.format(\"%s/%s\", main_job, sub_job)\n    else\n        return main_job\n    end\nend\n\n---============================================================================\n--- STANDARD MESSAGE FUNCTIONS\n---============================================================================\n\n--- Display info message (cyan)\n--- @param message string Message to display\nfunction MessageCore.info(message)\n    add_to_chat(121, MessageCore.job_prefix() .. message)\nend\n\n--- Display success message (green)\n--- @param message string Message to display\nfunction MessageCore.success(message)\n    add_to_chat(158, MessageCore.job_prefix() .. message)\nend\n\n--- Display error message (red)\n--- @param message string Message to display\nfunction MessageCore.error(message)\n    add_to_chat(167, MessageCore.job_prefix() .. message)\nend\n\n--- Display warning message (region orange, like every other warning)\n--- @param message string Message to display\nfunction MessageCore.warning(message)\n    add_to_chat(MessageColors.WARNING, MessageCore.job_prefix() .. message)\nend\n\n--- Send a pre-formatted message that already contains embedded color codes\n--- (built via `create_color_code`). Uses chat color 001 (neutral) so the\n--- embedded codes are honored verbatim. This is the canonical entry point\n--- for module-specific formatters that build their own colored output;\n--- always preferred over a raw `add_to_chat(001, ...)` so we have one\n--- choke point if we ever need to filter/route chat output centrally.\n--- @param message string Pre-formatted message with embedded color codes\nfunction MessageCore.raw(message)\n    add_to_chat(001, message)\nend\n\n---============================================================================\n--- UTILITY MESSAGES\n---============================================================================\n\n--- Show AutoMove callback error\n--- @param error_msg string Error message\nfunction MessageCore.show_automove_error(error_msg)\n    add_to_chat(167, string.format(\"[AutoMove] Callback error: %s\", error_msg))\nend\n\n--- Show config loader error\n--- @param module_name string Module name (e.g., 'ConfigLoader', 'WHM')\n--- @param error_msg string Error message\nfunction MessageCore.show_config_error(module_name, error_msg)\n    add_to_chat(167, string.format('[%s] %s', module_name, error_msg))\nend\n\n--- Show UI module error\n--- @param error_msg string Error message\nfunction MessageCore.show_ui_error(error_msg)\n    add_to_chat(167, string.format('[UI] %s', error_msg))\nend\n\n--- Show UI module info\n--- @param info_msg string Info message\nfunction MessageCore.show_ui_info(info_msg)\n    add_to_chat(122, string.format('[UI] %s', info_msg))\nend\n\n--- Show test mode message\n--- @param test_msg string Test mode message\nfunction MessageCore.show_test_mode(test_msg)\n    add_to_chat(8, string.format('[TEST MODE] %s', test_msg))\nend\n\n---============================================================================\n--- MODULE EXPORT\n---============================================================================\n\n---============================================================================\n--- CHAT OPTIONS ON EVERY LINE\n---============================================================================\n\n-- The player's separator options (on/off, character, color, width) apply to\n-- every chat line of this job file, whoever writes it: templates, InfoBlock,\n-- formatters that build their own lines, diagnostic tools, Mote. The sandbox\n-- add_to_chat is the one place they all share (chat_separators.lua). Once\n-- per sandbox: a job load gets a fresh _G and a fresh add_to_chat.\nif not rawget(_G, '__chat_separators_installed') and type(rawget(_G, 'add_to_chat')) == 'function' then\n    _G.__chat_separators_installed = true\n    local raw_add_to_chat = rawget(_G, 'add_to_chat')\n    local Separators = nil\n    _G.add_to_chat = function(color, text, ...)\n        if not Separators then\n            local ok, mod = pcall(require, 'shared/utils/messages/chat_separators')\n            if ok and mod then Separators = mod end\n        end\n        if Separators then\n            text = Separators.apply(text)\n            if text == nil then return end\n        end\n        return raw_add_to_chat(color, text, ...)\n    end\nend\n\nreturn MessageCore\n", "shared/utils/messages/message_formatter.lua": "---============================================================================\r\n--- MessageFormatter - Facade for all message modules\r\n---============================================================================\r\n--- Single entry point for chat messages. Every show_* function is a thin\r\n--- wrapper that requires its formatter module on first call, so a job only\r\n--- loads the formatters it actually uses.\r\n---\r\n--- Some BST formatter functions are exposed under two names (show_bst_* and\r\n--- the unprefixed name). //gs c msgtests requires every\r\n--- job formatter function to be exported here under its own name.\r\n---\r\n--- @file shared/utils/messages/message_formatter.lua\r\n--- @author ejouanchicot\r\n--- @version 2.0\r\n--- @date Created: 2025-11-03\r\n---============================================================================\r\n\r\nlocal MessageFormatter = {}\r\n\r\n-- Core module\r\nlocal _MessageCore = nil\r\nlocal function get_MessageCore()\r\n    if not _MessageCore then _MessageCore = require('shared/utils/messages/message_core') end\r\n    return _MessageCore\r\nend\r\n\r\n-- UI modules\r\nlocal _MessageKeybinds, _MessageSystem, _MessageStatus = nil, nil, nil\r\nlocal function get_MessageKeybinds()\r\n    if not _MessageKeybinds then _MessageKeybinds = require('shared/utils/messages/formatters/ui/message_keybinds') end\r\n    return _MessageKeybinds\r\nend\r\nlocal function get_MessageSystem()\r\n    if not _MessageSystem then _MessageSystem = require('shared/utils/messages/formatters/system/message_system') end\r\n    return _MessageSystem\r\nend\r\nlocal function get_MessageStatus()\r\n    if not _MessageStatus then _MessageStatus = require('shared/utils/messages/formatters/ui/message_status') end\r\n    return _MessageStatus\r\nend\r\n\r\n-- Combat modules\r\nlocal _MessageCooldowns, _MessageCombat, _JABuffs = nil, nil, nil\r\nlocal function get_MessageCooldowns()\r\n    if not _MessageCooldowns then _MessageCooldowns = require('shared/utils/messages/formatters/combat/message_cooldowns') end\r\n    return _MessageCooldowns\r\nend\r\nlocal function get_MessageCombat()\r\n    if not _MessageCombat then _MessageCombat = require('shared/utils/messages/formatters/combat/message_combat') end\r\n    return _MessageCombat\r\nend\r\nlocal function get_JABuffs()\r\n    if not _JABuffs then _JABuffs = require('shared/utils/messages/formatters/combat/message_ja_buffs') end\r\n    return _JABuffs\r\nend\r\n\r\n-- Magic modules\r\nlocal _MessageBuffs, _MessageDebuffs = nil, nil\r\nlocal function get_MessageBuffs()\r\n    if not _MessageBuffs then _MessageBuffs = require('shared/utils/messages/formatters/magic/message_buffs') end\r\n    return _MessageBuffs\r\nend\r\nlocal function get_MessageDebuffs()\r\n    if not _MessageDebuffs then _MessageDebuffs = require('shared/utils/messages/formatters/magic/message_debuffs') end\r\n    return _MessageDebuffs\r\nend\r\n\r\n-- System modules\r\nlocal _MessageEquipment = nil\r\nlocal function get_MessageEquipment()\r\n    if not _MessageEquipment then _MessageEquipment = require('shared/utils/messages/formatters/system/message_equipment') end\r\n    return _MessageEquipment\r\nend\r\n\r\n-- Utility modules\r\nlocal _RollMessages, _PartyMessages = nil, nil\r\nlocal function get_RollMessages()\r\n    if not _RollMessages then _RollMessages = require('shared/utils/messages/utilities/roll_messages') end\r\n    return _RollMessages\r\nend\r\nlocal function get_PartyMessages()\r\n    if not _PartyMessages then _PartyMessages = require('shared/utils/messages/utilities/party_messages') end\r\n    return _PartyMessages\r\nend\r\n\r\n-- Job-specific modules (LAZY LOADED for performance)\r\n-- These modules are only loaded when their functions are first called\r\nlocal _BRDMessages, _RDMMessages, _BLMMessages, _MessageBST = nil, nil, nil, nil\r\nlocal _GEOMessages, _MessageCOR = nil, nil\r\n\r\nlocal function get_BRDMessages()\r\n    if not _BRDMessages then _BRDMessages = require('shared/utils/messages/formatters/jobs/message_brd') end\r\n    return _BRDMessages\r\nend\r\nlocal function get_RDMMessages()\r\n    if not _RDMMessages then _RDMMessages = require('shared/utils/messages/formatters/jobs/message_rdm') end\r\n    return _RDMMessages\r\nend\r\nlocal function get_BLMMessages()\r\n    if not _BLMMessages then _BLMMessages = require('shared/utils/messages/formatters/jobs/message_blm') end\r\n    return _BLMMessages\r\nend\r\nlocal function get_MessageBST()\r\n    if not _MessageBST then _MessageBST = require('shared/utils/messages/formatters/jobs/message_bst') end\r\n    return _MessageBST\r\nend\r\nlocal function get_GEOMessages()\r\n    if not _GEOMessages then _GEOMessages = require('shared/utils/messages/formatters/jobs/message_geo') end\r\n    return _GEOMessages\r\nend\r\nlocal function get_MessageCOR()\r\n    if not _MessageCOR then _MessageCOR = require('shared/utils/messages/formatters/jobs/message_cor') end\r\n    return _MessageCOR\r\nend\r\n\r\n-- Public API (lazy wrappers - loaded on first call)\r\n\r\n-- Expose colors for external use (lazy)\r\nMessageFormatter.COLORS = setmetatable({}, {\r\n    __index = function(_, key) return get_MessageCore().COLORS[key] end\r\n})\r\n\r\n-- Core utilities (lazy wrappers)\r\nMessageFormatter.convert_key_display = function(...) return get_MessageCore().convert_key_display(...) end\r\nMessageFormatter.show_separator = function(...) return get_MessageCore().show_separator(...) end\r\nMessageFormatter.get_job_tag = function(...) return get_MessageCore().get_job_tag(...) end\r\n\r\n-- Job Ability Buffs (Global - Works for ALL jobs)\r\nMessageFormatter.show_ja_activated = function(...) return get_JABuffs().show_activated(...) end\r\n\r\n-- Keybind functions\r\nMessageFormatter.show_keybind_list = function(...) return get_MessageKeybinds().show_keybind_list(...) end\r\nMessageFormatter.format_keybind_line = function(...) return get_MessageKeybinds().format_keybind_line(...) end\r\nMessageFormatter.show_no_binds_error = function(...) return get_MessageKeybinds().show_no_binds_error(...) end\r\nMessageFormatter.show_bind_failed_error = function(...) return get_MessageKeybinds().show_bind_failed_error(...) end\r\n\r\n-- System functions\r\nMessageFormatter.show_system_intro = function(...) return get_MessageSystem().show_system_intro(...) end\r\nMessageFormatter.show_system_intro_complete = function(...) return get_MessageSystem().show_system_intro_complete(...) end\r\nMessageFormatter.show_color_test_header = function(...) return get_MessageSystem().show_color_test_header(...) end\r\nMessageFormatter.show_color_test_sample = function(...) return get_MessageSystem().show_color_test_sample(...) end\r\nMessageFormatter.show_color_test_footer = function(...) return get_MessageSystem().show_color_test_footer(...) end\r\n\r\n-- Status functions\r\nMessageFormatter.show_error = function(...) return get_MessageStatus().show_error(...) end\r\nMessageFormatter.show_warning = function(...) return get_MessageStatus().show_warning(...) end\r\nMessageFormatter.show_success = function(...) return get_MessageStatus().show_success(...) end\r\nMessageFormatter.show_info = function(...) return get_MessageStatus().show_info(...) end\r\nMessageFormatter.show_state_display = function(...) return get_MessageStatus().show_state_display(...) end\r\nMessageFormatter.show_tp_ready = function(...) return get_MessageStatus().show_tp_ready(...) end\r\n\r\n-- Cooldown functions\r\nMessageFormatter.show_spell_cooldown = function(...) return get_MessageCooldowns().show_spell_cooldown(...) end\r\nMessageFormatter.show_ability_cooldown = function(...) return get_MessageCooldowns().show_ability_cooldown(...) end\r\nMessageFormatter.show_cooldown_message = function(...) return get_MessageCooldowns().show_cooldown_message(...) end\r\nMessageFormatter.show_multi_status = function(...) return get_MessageCooldowns().show_multi_status(...) end\r\n\r\nMessageFormatter.get_spell_recast_seconds = function(...) return get_MessageCooldowns().get_spell_recast_seconds(...) end\r\nMessageFormatter.get_ability_recast_seconds = function(...) return get_MessageCooldowns().get_ability_recast_seconds(...) end\r\n\r\n-- Combat functions\r\nMessageFormatter.show_range_error = function(...) return get_MessageCombat().show_range_error(...) end\r\nMessageFormatter.show_ws_validation_error = function(...) return get_MessageCombat().show_ws_validation_error(...) end\r\nMessageFormatter.show_ability_tp_error = function(...) return get_MessageCombat().show_ability_tp_error(...) end\r\nMessageFormatter.show_target_error = function(...) return get_MessageCombat().show_target_error(...) end\r\nMessageFormatter.show_ws_tp = function(...) return get_MessageCombat().show_ws_tp(...) end\r\nMessageFormatter.show_ws_activated = function(...) return get_MessageCombat().show_ws_activated(...) end\r\nMessageFormatter.show_spell_activated = function(...) return get_MessageCombat().show_spell_activated(...) end\r\nMessageFormatter.show_spell_cast = function(...) return get_MessageCombat().show_spell_cast(...) end\r\nMessageFormatter.show_waltz_heal = function(...) return get_MessageCombat().show_waltz_heal(...) end\r\n\r\n-- Buff functions\r\nMessageFormatter.show_buff_status = function(...) return get_MessageBuffs().show_buff_status(...) end\r\n\r\n-- Equipment check functions\r\nMessageFormatter.show_check_header = function(...) return get_MessageEquipment().show_check_header(...) end\r\nMessageFormatter.show_missing_item = function(...) return get_MessageEquipment().show_missing_item(...) end\r\nMessageFormatter.show_storage_item = function(...) return get_MessageEquipment().show_storage_item(...) end\r\nMessageFormatter.show_check_summary = function(...) return get_MessageEquipment().show_check_summary(...) end\r\nMessageFormatter.show_check_error = function(...) return get_MessageEquipment().show_check_error(...) end\r\nMessageFormatter.show_no_sets_found = function(...) return get_MessageEquipment().show_no_sets_found(...) end\r\n\r\n-- Debuff blocking functions\r\nMessageFormatter.show_spell_blocked = function(...) return get_MessageDebuffs().show_spell_blocked(...) end\r\nMessageFormatter.show_ja_blocked = function(...) return get_MessageDebuffs().show_ja_blocked(...) end\r\nMessageFormatter.show_ws_blocked = function(...) return get_MessageDebuffs().show_ws_blocked(...) end\r\nMessageFormatter.show_item_blocked = function(...) return get_MessageDebuffs().show_item_blocked(...) end\r\nMessageFormatter.show_action_blocked = function(...) return get_MessageDebuffs().show_action_blocked(...) end\r\nMessageFormatter.show_silence_cure_success = function(...) return get_MessageDebuffs().show_silence_cure_success(...) end\r\nMessageFormatter.show_no_silence_cure = function(...) return get_MessageDebuffs().show_no_silence_cure(...) end\r\n\r\n-- Roll functions (COR)\r\nMessageFormatter.show_roll_result = function(...) return get_RollMessages().show_roll_result(...) end\r\nMessageFormatter.show_roll_bust = function(...) return get_RollMessages().show_roll_bust(...) end\r\nMessageFormatter.show_roll_double_up_window = function(...) return get_RollMessages().show_roll_double_up_window(...) end\r\nMessageFormatter.show_roll_double_up_expired = function(...) return get_RollMessages().show_roll_double_up_expired(...) end\r\nMessageFormatter.show_no_active_roll = function(...) return get_RollMessages().show_no_active_roll(...) end\r\nMessageFormatter.show_active_rolls = function(...) return get_RollMessages().show_active_rolls(...) end\r\nMessageFormatter.show_rolls_cleared = function(...) return get_RollMessages().show_rolls_cleared(...) end\r\nMessageFormatter.show_invalid_roll_value = function(...) return get_RollMessages().show_invalid_roll_value(...) end\r\n\r\n-- Party Tracking (Universal - usable by any job)\r\nMessageFormatter.show_party_members = function(...) return get_PartyMessages().show_party_members(...) end\r\n\r\nMessageFormatter.show_marcato_used = function(...) return get_BRDMessages().show_marcato_used(...) end\r\nMessageFormatter.show_pianissimo_used = function(...) return get_BRDMessages().show_pianissimo_used(...) end\r\nMessageFormatter.show_pianissimo_target = function(...) return get_BRDMessages().show_pianissimo_target(...) end\r\nMessageFormatter.show_ability_command = function(...) return get_BRDMessages().show_ability_command(...) end\r\nMessageFormatter.show_instrument_locked = function(...) return get_BRDMessages().show_instrument_locked(...) end\r\nMessageFormatter.show_instrument_released = function(...) return get_BRDMessages().show_instrument_released(...) end\r\nMessageFormatter.show_daurdabla_dummy = function(...) return get_BRDMessages().show_daurdabla_dummy(...) end\r\nMessageFormatter.show_songs_casting = function(...) return get_BRDMessages().show_songs_casting(...) end\r\nMessageFormatter.show_song_pack = function(...) return get_BRDMessages().show_song_pack(...) end\r\nMessageFormatter.show_dummy_casting = function(...) return get_BRDMessages().show_dummy_casting(...) end\r\nMessageFormatter.show_lullaby_cast = function(...) return get_BRDMessages().show_lullaby_cast(...) end\r\nMessageFormatter.show_elegy_cast = function(...) return get_BRDMessages().show_elegy_cast(...) end\r\nMessageFormatter.show_requiem_cast = function(...) return get_BRDMessages().show_requiem_cast(...) end\r\nMessageFormatter.show_threnody_cast = function(...) return get_BRDMessages().show_threnody_cast(...) end\r\nMessageFormatter.show_carol_cast = function(...) return get_BRDMessages().show_carol_cast(...) end\r\nMessageFormatter.show_etude_cast = function(...) return get_BRDMessages().show_etude_cast(...) end\r\nMessageFormatter.show_song_refinement = function(...) return get_BRDMessages().show_song_refinement(...) end\r\nMessageFormatter.show_song_refinement_failed = function(...) return get_BRDMessages().show_song_refinement_failed(...) end\r\nMessageFormatter.show_no_element_selected = function(...) return get_BRDMessages().show_no_element_selected(...) end\r\nMessageFormatter.show_no_carol_element = function(...) return get_BRDMessages().show_no_carol_element(...) end\r\nMessageFormatter.show_no_etude_type = function(...) return get_BRDMessages().show_no_etude_type(...) end\r\nMessageFormatter.show_no_song_in_slot = function(...) return get_BRDMessages().show_no_song_in_slot(...) end\r\nMessageFormatter.show_pack_not_found = function(...) return get_BRDMessages().show_pack_not_found(...) end\r\n\r\nMessageFormatter.show_element_list = function(...) return get_RDMMessages().show_element_list(...) end\r\nMessageFormatter.show_storm_current = function(...) return get_RDMMessages().show_storm_current(...) end\r\nMessageFormatter.show_no_enspell_selected = function(...) return get_RDMMessages().show_no_enspell_selected(...) end\r\nMessageFormatter.show_gain_spell_not_configured = function(...) return get_RDMMessages().show_gain_spell_not_configured(...) end\r\nMessageFormatter.show_bar_element_not_configured = function(...) return get_RDMMessages().show_bar_element_not_configured(...) end\r\nMessageFormatter.show_bar_ailment_not_configured = function(...) return get_RDMMessages().show_bar_ailment_not_configured(...) end\r\nMessageFormatter.show_spike_not_configured = function(...) return get_RDMMessages().show_spike_not_configured(...) end\r\nMessageFormatter.show_storm_requires_sch = function(...) return get_RDMMessages().show_storm_requires_sch(...) end\r\nMessageFormatter.show_phalanx_downgrade = function(...) return get_RDMMessages().show_phalanx_downgrade(...) end\r\nMessageFormatter.show_phalanx_upgrade = function(...) return get_RDMMessages().show_phalanx_upgrade(...) end\r\n\r\n-- GEO functions (Geomancer) - LAZY LOADED\r\nMessageFormatter.show_indi_cast = function(...) return get_GEOMessages().show_indi_cast(...) end\r\nMessageFormatter.show_geo_cast = function(...) return get_GEOMessages().show_geo_cast(...) end\r\nMessageFormatter.show_spell_refined = function(...) return get_GEOMessages().show_spell_refined(...) end\r\nMessageFormatter.show_no_tier_available = function(...) return get_GEOMessages().show_no_tier_available(...) end\r\n\r\n-- BLM functions (Black Mage) - LAZY LOADED\r\nMessageFormatter.show_element_cycle = function(...) return get_BLMMessages().show_element_cycle(...) end\r\nMessageFormatter.show_storm_cycle = function(...) return get_BLMMessages().show_storm_cycle(...) end\r\nMessageFormatter.show_spell_refinement = function(...) return get_BLMMessages().show_spell_refinement(...) end\r\nMessageFormatter.show_mp_conservation = function(...) return get_BLMMessages().show_mp_conservation(...) end\r\nMessageFormatter.show_arts_already_active = function(...) return get_BLMMessages().show_arts_already_active(...) end\r\nMessageFormatter.show_stratagem_no_charges = function(...) return get_BLMMessages().show_stratagem_no_charges(...) end\r\nMessageFormatter.show_spell_replacement_error = function(...) return get_BLMMessages().show_spell_replacement_error(...) end\r\nMessageFormatter.show_spell_refinement_error = function(...) return get_BLMMessages().show_spell_refinement_error(...) end\r\nMessageFormatter.show_spell_recasts_error = function(...) return get_BLMMessages().show_spell_recasts_error(...) end\r\nMessageFormatter.show_breakga_blocked = function(...) return get_BLMMessages().show_breakga_blocked(...) end\r\n\r\n-- BST functions (Beastmaster) - LAZY LOADED\r\n-- Legacy names with show_bst_ prefix (backward compatibility)\r\n\r\n-- Ecosystem Messages\r\nMessageFormatter.show_bst_ecosystem_change = function(...) return get_MessageBST().show_ecosystem_change(...) end\r\nMessageFormatter.show_bst_species_change = function(...) return get_MessageBST().show_species_change(...) end\r\nMessageFormatter.show_bst_correlation = function(...) return get_MessageBST().show_correlation(...) end\r\n\r\n-- Broth/Jug Messages\r\nMessageFormatter.show_bst_broth_equip = function(...) return get_MessageBST().show_broth_equip(...) end\r\nMessageFormatter.show_bst_broth_list = function(...) return get_MessageBST().show_broth_list(...) end\r\nMessageFormatter.show_bst_ready_moves_list = function(...) return get_MessageBST().show_ready_moves_list(...) end\r\n\r\nMessageFormatter.show_bst_pet_engage = function(...) return get_MessageBST().show_pet_engage(...) end\r\nMessageFormatter.show_bst_pet_disengage = function(...) return get_MessageBST().show_pet_disengage(...) end\r\n\r\nMessageFormatter.show_bst_ready_move_use = function(...) return get_MessageBST().show_ready_move_use(...) end\r\nMessageFormatter.show_bst_ready_move_auto_engage = function(...) return get_MessageBST().show_ready_move_auto_engage(...) end\r\nMessageFormatter.show_bst_ready_move_auto_sequence = function(...) return get_MessageBST().show_ready_move_auto_sequence(...) end\r\n\r\n-- Error Messages\r\nMessageFormatter.show_error_no_pet = function(...) return get_MessageBST().show_error_no_pet(...) end\r\nMessageFormatter.show_error_no_ready_moves = function(...) return get_MessageBST().show_error_no_ready_moves(...) end\r\nMessageFormatter.show_error_invalid_index = function(...) return get_MessageBST().show_error_invalid_index(...) end\r\nMessageFormatter.show_error_index_out_of_range = function(...) return get_MessageBST().show_error_index_out_of_range(...) end\r\nMessageFormatter.show_error_module_not_loaded = function(...) return get_MessageBST().show_error_module_not_loaded(...) end\r\n\r\nMessageFormatter.show_ecosystem_change = function(...) return get_MessageBST().show_ecosystem_change(...) end\r\nMessageFormatter.show_species_change = function(...) return get_MessageBST().show_species_change(...) end\r\nMessageFormatter.show_broth_equip = function(...) return get_MessageBST().show_broth_equip(...) end\r\nMessageFormatter.show_pet_engage = function(...) return get_MessageBST().show_pet_engage(...) end\r\nMessageFormatter.show_pet_disengage = function(...) return get_MessageBST().show_pet_disengage(...) end\r\nMessageFormatter.show_ready_move_use = function(...) return get_MessageBST().show_ready_move_use(...) end\r\nMessageFormatter.show_ready_move_auto_engage = function(...) return get_MessageBST().show_ready_move_auto_engage(...) end\r\nMessageFormatter.show_ready_move_auto_sequence = function(...) return get_MessageBST().show_ready_move_auto_sequence(...) end\r\n\r\n-- COR functions (Corsair) - LAZY LOADED\r\nMessageFormatter.show_rolltracker_load_failed = function(...) return get_MessageCOR().show_rolltracker_load_failed(...) end\r\nMessageFormatter.show_packets_load_failed = function(...) return get_MessageCOR().show_packets_load_failed(...) end\r\nMessageFormatter.show_resources_load_failed = function(...) return get_MessageCOR().show_resources_load_failed(...) end\r\n\r\n--- Print a gray debug line tagged with a prefix.\r\n--- @param prefix string Tag shown in brackets (e.g. 'PERF', job code)\r\n--- @param message string Debug text\r\nfunction MessageFormatter.show_debug(prefix, message)\r\n    local MessageRenderer = require('shared/utils/messages/core/message_renderer')\r\n    local formatted = string.format('[%s] %s', prefix, message)\r\n    MessageRenderer.send(formatted, 8)  -- Color 8 = gray debug\r\nend\r\n\r\nreturn MessageFormatter\r\n", "shared/utils/ui/COLOR_SYSTEM.lua": "---============================================================================\n--- Color System - Centralized Color Management for UI Elements\n---============================================================================\n--- Centralized color management for all UI elements across all jobs.\n--- Provides consistent color coding for elements, stats, spells, and modes.\n--- Supports per-character customization via <character>/config/UI_COLOR_CONFIG.lua,\n--- read once when this module loads.\n---\n--- @file shared/utils/ui/COLOR_SYSTEM.lua\n--- @author ejouanchicot\n--- @version 4.0\n--- @date Created: 2025-11-03 (updated 2025-11-10)\n---============================================================================\n\nlocal ColorSystem = {}\n\n---============================================================================\n--- CHARACTER-SPECIFIC COLOR LOADING\n---============================================================================\n\n-- Try to load character-specific color config (Tetsouo/Kaories)\nlocal char_name = player and player.name or nil\nlocal custom_colors = nil\n\nif char_name then\n    local success, UIColorConfig = require('shared/utils/core/char_paths').load('common', 'UI_COLOR_CONFIG', nil, char_name)\n    if success and UIColorConfig then\n        custom_colors = UIColorConfig\n    end\nend\n\n---============================================================================\n--- STATIC COLOR DEFINITIONS (WITH CUSTOM OVERRIDE SUPPORT)\n---============================================================================\n\n-- Element colors (can be overridden by custom config)\nlocal element_colors = {\n    -- Basic elements\n    Fire = \"\\\\cs(255,100,100)\",\n    Water = \"\\\\cs(100,150,255)\",\n    Lightning = \"\\\\cs(255,150,255)\",\n    Ice = \"\\\\cs(150,200,255)\",\n    Wind = \"\\\\cs(150,255,150)\",\n    Earth = \"\\\\cs(200,150,100)\",\n    Light = \"\\\\cs(255,255,255)\",\n    Dark = \"\\\\cs(150,100,200)\",\n\n    -- Spell name aliases\n    Thunder = \"\\\\cs(255,150,255)\",\n    Aero = \"\\\\cs(150,255,150)\",\n    Stone = \"\\\\cs(200,150,100)\",\n    Blizzard = \"\\\\cs(150,200,255)\",\n\n    -- RUN Runes (Latin names)\n    Ignis = \"\\\\cs(255,100,100)\",    -- Fire\n    Gelus = \"\\\\cs(150,200,255)\",    -- Ice\n    Flabra = \"\\\\cs(150,255,150)\",   -- Wind\n    Tellus = \"\\\\cs(200,150,100)\",   -- Earth\n    Sulpor = \"\\\\cs(255,150,255)\",   -- Lightning\n    Unda = \"\\\\cs(100,150,255)\",     -- Water\n    Lux = \"\\\\cs(255,255,255)\",      -- Light\n    Tenebrae = \"\\\\cs(150,100,200)\", -- Dark\n\n    -- Tier 2 spells (-ra variants)\n    Thundara = \"\\\\cs(255,150,255)\",\n    Aera = \"\\\\cs(150,255,150)\",       -- GEO AOE Wind\n    Aerora = \"\\\\cs(150,255,150)\",\n    Stonera = \"\\\\cs(200,150,100)\",\n    Blizzara = \"\\\\cs(150,200,255)\",\n    Fira = \"\\\\cs(255,100,100)\",\n    Watera = \"\\\\cs(100,150,255)\",\n\n    -- Tier 3 spells\n    Thundaga = \"\\\\cs(255,150,255)\",\n    Aeroga = \"\\\\cs(150,255,150)\",\n    Stonega = \"\\\\cs(200,150,100)\",\n    Blizzaga = \"\\\\cs(150,200,255)\",\n    Firaga = \"\\\\cs(255,100,100)\",\n    Waterga = \"\\\\cs(100,150,255)\",\n\n    -- Tier 4 spells (Aja)\n    Thundaja = \"\\\\cs(255,150,255)\",\n    Aeroja = \"\\\\cs(150,255,150)\",\n    Stoneja = \"\\\\cs(200,150,100)\",\n    Blizzaja = \"\\\\cs(150,200,255)\",\n    Firaja = \"\\\\cs(255,100,100)\",\n    Waterja = \"\\\\cs(100,150,255)\",\n\n    -- Storm variants\n    Firestorm = \"\\\\cs(255,100,100)\",\n    Sandstorm = \"\\\\cs(200,150,100)\",\n    Thunderstorm = \"\\\\cs(255,150,255)\",\n    Hailstorm = \"\\\\cs(150,200,255)\",\n    Windstorm = \"\\\\cs(150,255,150)\",\n    Rainstorm = \"\\\\cs(100,150,255)\",\n    Voidstorm = \"\\\\cs(150,100,200)\",\n    Aurorastorm = \"\\\\cs(255,255,255)\"\n}\n\n-- Stat colors (static)\nlocal stat_colors = {\n    STR = \"\\\\cs(255,100,100)\",\n    DEX = \"\\\\cs(255,150,255)\",\n    VIT = \"\\\\cs(200,150,100)\",\n    AGI = \"\\\\cs(150,255,150)\",\n    INT = \"\\\\cs(150,100,200)\",\n    MND = \"\\\\cs(150,200,255)\",\n    CHR = \"\\\\cs(255,255,255)\"\n}\n\n-- Special colors (static)\nlocal special_colors = {\n    PDT = \"\\\\cs(255,200,100)\",\n    MDT = \"\\\\cs(150,200,255)\",\n    Normal = \"\\\\cs(255,255,255)\",   -- White (default/neutral state)\n    Refresh = \"\\\\cs(150,255,150)\",  -- Green (MP recovery/safe)\n    Potency = \"\\\\cs(150,255,150)\",  -- Green (healing power/safe)\n    SIRD = \"\\\\cs(255,200,100)\",     -- Orange like PDT (defensive/interrupt resist)\n    Solace = \"\\\\cs(150,255,150)\",   -- Green (cure/healing focus)\n    Misery = \"\\\\cs(255,100,100)\",   -- Red (damage/offensive focus)\n    [\"true\"] = \"\\\\cs(150,255,150)\",\n    [\"false\"] = \"\\\\cs(255,100,100)\",\n    unknown = \"\\\\cs(128,128,128)\",\n    bar_ailment = \"\\\\cs(255,200,150)\"  -- NOTE: never read (Bar-ailments use element colors)\n}\n\n-- Spell colors (can be overridden by custom config)\nlocal en_spell_colors = {}\nlocal spike_colors = {}\nlocal storm_colors = {}\nlocal quick_draw_colors = {}\n\n---============================================================================\n--- CUSTOM COLOR OVERRIDE (Apply character-specific colors)\n---============================================================================\n\nif custom_colors then\n    -- Helper to convert RGB {r,g,b} to \"\\\\cs(r,g,b)\"\n    local function rgb_to_code(rgb)\n        if not rgb or #rgb < 3 then return nil end\n        return string.format(\"\\\\cs(%d,%d,%d)\", rgb[1], rgb[2], rgb[3])\n    end\n\n    -- Override element colors\n    if custom_colors.elements then\n        for name, rgb in pairs(custom_colors.elements) do\n            local code = rgb_to_code(rgb)\n            if code then\n                element_colors[name] = code\n            end\n        end\n    end\n\n    -- Override stat colors\n    if custom_colors.stats then\n        for name, rgb in pairs(custom_colors.stats) do\n            local code = rgb_to_code(rgb)\n            if code then\n                stat_colors[name] = code\n            end\n        end\n    end\n\n    -- Override mode colors\n    if custom_colors.modes then\n        for name, rgb in pairs(custom_colors.modes) do\n            local code = rgb_to_code(rgb)\n            if code then\n                special_colors[name] = code\n            end\n        end\n    end\n\n    -- Override bar ailment color\n    if custom_colors.bar_spells and custom_colors.bar_spells.ailment then\n        local code = rgb_to_code(custom_colors.bar_spells.ailment)\n        if code then\n            special_colors.bar_ailment = code\n        end\n    end\n\n    -- Override special colors (true/false/unknown)\n    if custom_colors.special then\n        for name, rgb in pairs(custom_colors.special) do\n            local code = rgb_to_code(rgb)\n            if code then\n                special_colors[name] = code\n            end\n        end\n    end\n\n    -- Override En spell colors\n    if custom_colors.spells and custom_colors.spells.en then\n        for spell_name, rgb in pairs(custom_colors.spells.en) do\n            local code = rgb_to_code(rgb)\n            if code then\n                en_spell_colors[spell_name] = code\n            end\n        end\n    end\n\n    -- Override Spike spell colors\n    if custom_colors.spells and custom_colors.spells.spikes then\n        for spell_name, rgb in pairs(custom_colors.spells.spikes) do\n            local code = rgb_to_code(rgb)\n            if code then\n                spike_colors[spell_name] = code\n            end\n        end\n    end\n\n    -- Override Storm spell colors\n    if custom_colors.spells and custom_colors.spells.storms then\n        for spell_name, rgb in pairs(custom_colors.spells.storms) do\n            local code = rgb_to_code(rgb)\n            if code then\n                storm_colors[spell_name] = code\n            end\n        end\n    end\n\n    -- Override Quick Draw colors (COR)\n    if custom_colors.jobs and custom_colors.jobs.quick_draw then\n        for shot_name, rgb in pairs(custom_colors.jobs.quick_draw) do\n            local code = rgb_to_code(rgb)\n            if code then\n                quick_draw_colors[shot_name] = code\n            end\n        end\n    end\nend\n\n---============================================================================\n--- HELPER FUNCTIONS\n---============================================================================\n\n--- Get color for Gain spells based on stat\nlocal function get_gain_color(value)\n    if value:find(\"STR\") then\n        return element_colors.Fire       -- Fire element\n    elseif value:find(\"DEX\") then\n        return element_colors.Wind       -- Wind element\n    elseif value:find(\"VIT\") then\n        return element_colors.Earth      -- Earth element\n    elseif value:find(\"AGI\") then\n        return element_colors.Lightning  -- Thunder/Lightning element\n    elseif value:find(\"INT\") then\n        return element_colors.Ice        -- Ice element\n    elseif value:find(\"MND\") then\n        return element_colors.Water      -- Water element\n    elseif value:find(\"CHR\") then\n        return element_colors.Light      -- Light element\n    end\n    return \"\\\\cs(255,100,100)\" -- Fallback red\nend\n\n--- Get color for Storm spells\nlocal function get_storm_color(value)\n    -- Check custom colors first\n    if storm_colors[value] then\n        return storm_colors[value]\n    end\n\n    -- Fallback to element colors\n    if value:find(\"Fire\") then\n        return element_colors.Fire\n    elseif value:find(\"Sand\") or value:find(\"Stone\") then\n        return element_colors.Earth\n    elseif value:find(\"Thunder\") then\n        return element_colors.Lightning\n    elseif value:find(\"Hail\") or value:find(\"Bliz\") then\n        return element_colors.Ice\n    elseif value:find(\"Rain\") or value:find(\"Water\") then\n        return element_colors.Water\n    elseif value:find(\"Wind\") then\n        return element_colors.Wind\n    elseif value:find(\"Void\") then\n        return element_colors.Dark\n    elseif value:find(\"Aurora\") then\n        return element_colors.Light\n    end\n    return nil\nend\n\n--- Get color for Bar element spells\nlocal function get_bar_element_color(value)\n    -- Support both old forms (Barfira) and new forms (Barfire)\n    if value:find(\"Barfir\") then  -- Matches both Barfira and Barfire\n        return element_colors.Fire\n    elseif value:find(\"Barbliz\") then  -- Matches both Barblizzara and Barblizzard\n        return element_colors.Ice\n    elseif value:find(\"Baraer\") then  -- Matches both Baraera and Baraero\n        return element_colors.Wind\n    elseif value:find(\"Barston\") then  -- Matches both Barstonra and Barstone\n        return element_colors.Earth\n    elseif value:find(\"Barthund\") then  -- Matches both Barthundra and Barthunder\n        return element_colors.Lightning\n    elseif value:find(\"Barwater\") or value:find(\"Barwatera\") then\n        return element_colors.Water\n    end\n    return nil\nend\n\n--- Get color for Bar ailment spells (based on element association)\nlocal function get_bar_ailment_color(value)\n    -- Fire element ailments\n    if value:find(\"Barparalyz\") then  -- Barparalyze/Barparalyzra\n        return element_colors.Fire\n    -- Ice element ailments\n    elseif value:find(\"Barsilence\") then  -- Barsilence/Barsilencera\n        return element_colors.Ice\n    -- Wind element ailments\n    elseif value:find(\"Barpetr\") then  -- Barpetrify/Barpetra\n        return element_colors.Wind\n    -- Thunder element ailments\n    elseif value:find(\"Barpoison\") then  -- Barpoison/Barpoisonra\n        return element_colors.Lightning\n    -- Water element ailments\n    elseif value:find(\"Baramnesi\") or value:find(\"Barvir\") then  -- Baramnesia/Baramnesra, Barvirus/Barvira\n        return element_colors.Water\n    -- Light element ailments\n    elseif value:find(\"Barsleep\") or value:find(\"Barblind\") then  -- Barsleep/Barsleepra, Barblind/Barblindra\n        return element_colors.Light\n    end\n    return nil\nend\n\n--- Get color for En spells\nlocal function get_en_spell_color(value)\n    -- Check custom colors first\n    if en_spell_colors[value] then\n        return en_spell_colors[value]\n    end\n\n    -- Fallback to element colors\n    if value:find(\"Enfire\") then\n        return element_colors.Fire\n    elseif value:find(\"Enblizzard\") then\n        return element_colors.Ice\n    elseif value:find(\"Enaero\") then\n        return element_colors.Wind\n    elseif value:find(\"Enstone\") then\n        return element_colors.Earth\n    elseif value:find(\"Enthunder\") then\n        return element_colors.Lightning\n    elseif value:find(\"Enwater\") then\n        return element_colors.Water\n    end\n    return nil\nend\n\n--- Get color for Spike spells\nlocal function get_spike_color(value)\n    -- Check custom colors first\n    if spike_colors[value] then\n        return spike_colors[value]\n    end\n\n    -- Fallback to element colors\n    if value == \"Blaze Spikes\" then\n        return element_colors.Fire\n    elseif value == \"Ice Spikes\" then\n        return element_colors.Ice\n    elseif value == \"Shock Spikes\" then\n        return element_colors.Lightning\n    end\n    return nil\nend\n\n--- Get color for Quick Draw spells (COR)\nlocal function get_quick_draw_color(value)\n    -- Check custom colors first\n    if quick_draw_colors[value] then\n        return quick_draw_colors[value]\n    end\n\n    -- Fallback to element colors\n    if value == \"Fire Shot\" then\n        return element_colors.Fire\n    elseif value == \"Ice Shot\" then\n        return element_colors.Blizzard\n    elseif value == \"Wind Shot\" then\n        return element_colors.Aero\n    elseif value == \"Earth Shot\"  then\n        return element_colors.Stone\n    elseif value == \"Thunder Shot\"  then\n        return element_colors.Thunder\n    elseif value == \"Water Shot\"  then\n        return element_colors.Water\n    elseif value == \"Light Shot\"  then\n        return element_colors.Light\n    elseif value == \"Dark Shot\"  then\n        return element_colors.Dark\n    end\n    return nil\nend\n\n---============================================================================\n--- MAIN COLOR RESOLUTION\n---============================================================================\n\nlocal DEFAULT_COLOR = \"\\\\cs(255,255,255)\"\n\n-- What the description says the value IS decides which palette to look it up\n-- in. Order matters, and \"Element\" already covers GEO's \"Elemental\".\nlocal DESCRIPTION_PALETTES = {\n    { keyword = \"Element\",    palette = element_colors },\n    { keyword = \"AOE\",        palette = element_colors },\n    { keyword = \"Etude\",      palette = stat_colors    },\n    { keyword = \"Rune\",       palette = element_colors },\n    { keyword = \"Light\",      palette = element_colors },\n    { keyword = \"Dark\",       palette = element_colors },\n    { keyword = \"Aja\",        palette = element_colors },\n    { keyword = \"Storm\",      palette = element_colors },\n    { keyword = \"Quick Draw\", palette = element_colors },\n}\n\n-- Mode names that colour themselves wherever they appear in a value, checked\n-- in order: a value holding both takes the first.\nlocal MODE_SUBSTRINGS = {\n    'PDT', 'MDT', 'Normal', 'Refresh', 'Potency', 'SIRD', 'Solace', 'Misery',\n}\n\n-- Each recognises one family of spell names and returns nil for the rest.\nlocal SPELL_COLOR_PROBES = {\n    get_bar_element_color,\n    get_bar_ailment_color,\n    get_en_spell_color,\n    get_spike_color,\n    get_quick_draw_color,\n}\n\n-- Literal values whose colour never depends on context.\nlocal EXACT_VALUE_COLORS = {\n    ['true']  = 'true',  ['True']  = 'true',  ['On']  = 'true',  ['on']  = 'true',\n    ['false'] = 'false', ['False'] = 'false', ['Off'] = 'false', ['off'] = 'false',\n    ['unknown'] = 'unknown', ['Unknown'] = 'unknown', ['N/A'] = 'unknown',\n}\n\n--- Colour the description asks for, if it names a kind this value belongs to.\n--- @param value string State value\n--- @param description string State description (never nil here)\n--- @return string|nil Colour code, or nil to keep looking\nlocal function color_from_description(value, description)\n    for _, rule in ipairs(DESCRIPTION_PALETTES) do\n        if description:find(rule.keyword) and rule.palette[value] then\n            return rule.palette[value]\n        end\n    end\n\n    if description:find(\"Storm\") then\n        return get_storm_color(value)\n    end\n\n    return nil\nend\n\n--- Colour the value carries on its own, whatever the description says.\n--- @param value string State value\n--- @return string|nil Colour code, or nil if the value is not recognised\nlocal function color_from_value(value)\n    for _, name in ipairs(MODE_SUBSTRINGS) do\n        if value:find(name) then\n            return special_colors[name]\n        end\n    end\n\n    for _, probe in ipairs(SPELL_COLOR_PROBES) do\n        local color = probe(value)\n        if color then return color end\n    end\n\n    local exact = EXACT_VALUE_COLORS[value]\n    return exact and special_colors[exact] or nil\nend\n\n--- Get color for a value based on context\n--- @param value string State value as shown in the UI\n--- @param description string|nil What kind of value it is (element, rune, etude...)\n--- @return string Colour code; white when nothing matches. Gain values always\n---         resolve in get_gain_color (fallback red when no stat is recognised).\nfunction ColorSystem.get_value_color(value, description)\n    if description and description:find(\"Gain\") then\n        return get_gain_color(value)\n    end\n\n    if description then\n        local by_description = color_from_description(value, description)\n        if by_description then return by_description end\n    end\n\n    -- Symbolic rather than elemental: Saber Dance is the offensive stance,\n    -- Fan Dance the defensive one.\n    if description and description:find(\"Dance\") then\n        if value == \"Saber Dance\" then\n            return element_colors.Fire\n        elseif value == \"Fan Dance\" then\n            return \"\\\\cs(150,255,150)\"\n        end\n    end\n\n    return color_from_value(value) or DEFAULT_COLOR\nend\n\nreturn ColorSystem\n", "shared/utils/ui/UI_DISPLAY_BUILDER.lua": "---============================================================================\n--- UI Display Builder - Centralized Job Display Logic\n---============================================================================\n--- Sorts a job's keybinds into the HUD sections (spells, abilities, weapons,\n--- modes) from an explicit `section` field or, failing that, from patterns\n--- matched against the state name. Shared by every job.\n---\n--- @file shared/utils/ui/UI_DISPLAY_BUILDER.lua\n--- @author ejouanchicot\n--- @version 1.0\n--- @date Created: 2025-09-26\n---============================================================================\n\nlocal UIDisplayBuilder = {}\n\nlocal KeybindLoader = require('shared/utils/ui/UI_LOADER')\nlocal UIStyle = require('shared/utils/ui/ui_style')\n\n---============================================================================\n--- KEYBIND CATEGORIZATION SYSTEM\n---============================================================================\n\n-- State categorization patterns (plain substring match via string.find).\n-- mode_patterns are checked first, then spell, ja, weapon.\nlocal categorization_rules = {\n    spell_patterns = {\n        \"Spell\", \"Element\", \"Tier\", \"Aja\", \"Storm\", \"Bar\", \"EnSpell\", \"Spike\",\n        \"Gain\", \"Ecosystem\", \"species\", \"RuneElement\", \"Light\", \"Dark\", \"Rune\",\n        \"BRDRotation\", \"VictoryMarch\",  -- BRD song settings (no BRDRotation state exists today)\n        \"Etude\",  -- BRD Etude stat buffs (EtudeType: STR/DEX/VIT/AGI/INT/MND/CHR)\n        \"QuickDraw\",  -- COR Quick Draw element selection\n        \"Roll\", \"Luzaf\",  -- COR Phantom Roll selection (MainRoll, SubRoll, LuzafRing)\n        \"Indi\", \"Geo\", \"AOE\"  -- GEO Geocolure/Indicolure/AOE spells\n    },\n\n    ja_patterns = {\n        \"Step\", \"BRDSong\",  -- DNC steps, BRD song slots (BRDSong1..5)\n        \"WS\"  -- Weaponskill slots (WS1..WS5), rebuilt per equipped weapon\n    },\n\n    weapon_patterns = {\n        \"Weapon\", \"WeaponSet\", \"SubSet\", \"Proc\",\n        \"Instrument\"  -- BRD MainInstrument: the instrument IS the range slot\n    },\n\n    mode_patterns = {\n        \"Mode\", \"Combat\", \"Engaged\", \"Idle\", \"Enfeeble\", \"Nuke\", \"PetIdleMode\", \"AutoPetEngage\",\n        \"Rotation\",\n        \"Xp\",  -- XP mode for PLD/RDM\n        \"PhalanxSIRD\",  -- Phalanx SIRD override for PLD\n        \"UseAltStep\",  -- DNC step configuration mode (must be before ja_patterns check)\n        \"Auto\",  -- Auto-trigger states (ClimacticAuto, etc.)\n        \"Lock\",  -- Lock states (RangeLock for THF, etc.)\n        \"Marcato\",  -- BRD auto-Marcato song selection (MarcatoSong: HonorMarch/AriaPassion/Off)\n        \"Dance\",  -- DNC dance selection (Dance: Saber Dance/Fan Dance)\n        \"Samba\",  -- DNC samba selection (Samba: Haste/Drain II/Aspir)\n        -- BLM stratagem toggles: listed here so they land in modes rather than\n        -- matching the generic \"AOE\" spell pattern checked further down.\n        \"SneakInvi\",\n        \"Klimaform\",\n        \"Favor\",  -- SMN AvatarFavor toggle\n        \"Regen\"   -- PLD /SCH and /RUN: sets.idleRegen laid over the idle set\n    }\n}\n\n--- Section names accepted in a bind's `section` field -> HUD bucket.\nlocal SECTION_ALIASES = {\n    mode = \"mode\", modes = \"mode\",\n    spell = \"spell\", spells = \"spell\",\n    ability = \"ja\", abilities = \"ja\", ja = \"ja\",\n    weapon = \"weapon\", weapons = \"weapon\",\n}\n\n--- Check if a state matches any pattern in a category\n--- @param state_name string The state name to check\n--- @param patterns table List of patterns to match against\n--- @return boolean True if state matches any pattern\nlocal function matches_category(state_name, patterns)\n    for _, pattern in ipairs(patterns) do\n        if state_name:find(pattern) then\n            return true\n        end\n    end\n    return false\nend\n\n--- Categorize a keybind based on its state\n--- @param bind table Keybind object with key, desc, state\n--- @return string Category name (spell, ja, weapon, mode, other)\nlocal function categorize_keybind(bind)\n    -- The player's own choice (UI_CONFIG layout.move_to_section) wins over all\n    local forced = UIStyle.forced_section(bind)\n    if forced then\n        return forced\n    end\n\n    -- An explicit section (custom states, see custom_states.lua) wins over\n    -- guessing from the state name.\n    if SECTION_ALIASES[bind.section] then\n        return SECTION_ALIASES[bind.section]\n    end\n\n    if not bind.state then\n        return \"other\"\n    end\n\n    -- Check mode patterns FIRST (specific patterns like UseAltStep before generic \"Step\")\n    if matches_category(bind.state, categorization_rules.mode_patterns) then\n        return \"mode\"\n    elseif matches_category(bind.state, categorization_rules.spell_patterns) then\n        return \"spell\"\n    elseif matches_category(bind.state, categorization_rules.ja_patterns) then\n        return \"ja\"\n    elseif matches_category(bind.state, categorization_rules.weapon_patterns) then\n        return \"weapon\"\n    end\n\n    -- Anything unmatched is a mode rather than nothing. extract_display_keys\n    -- builds four buckets and has nowhere to put an \"other\", so a state whose\n    -- name matched no pattern used to be dropped without a word - which is how\n    -- BRD's MainInstrument and SMN's AvatarFavor, both the job's signature\n    -- ^numpad3 slot, were missing from the HUD while their keys worked fine.\n    -- A row in a section you did not expect is a far cheaper mistake than a\n    -- row that is not there at all.\n    return \"mode\"\nend\n\n--- Filter out reverse keybinds (those with arrows)\n--- @param keybinds table List of keybind objects\n--- @return table Filtered keybinds without reverse arrows\nlocal function filter_reverse_keybinds(keybinds)\n    local filtered = {}\n    for _, bind in ipairs(keybinds) do\n        if not bind.desc:find(\"←\") then\n            table.insert(filtered, bind)\n        end\n    end\n    return filtered\nend\n\n---============================================================================\n--- DISPLAY KEY EXTRACTION\n---============================================================================\n\n--- The HUD section of one row (spell, ja, weapon, mode, other), for the\n--- renderer: a row without a key ('') is drawn only in its own section.\n--- @param bind table Keybind entry\n--- @return string\nfunction UIDisplayBuilder.categorize(bind)\n    return categorize_keybind(bind)\nend\n\n--- Extract display keys for each category from job keybinds\n--- @param job string The job abbreviation\n--- @param keybinds table|nil The rows ui_display already built (BRD song slots\n---   included); read from the job's keybind file when not given\n--- @return table Categories with their respective keys\nfunction UIDisplayBuilder.extract_display_keys(job, keybinds)\n    if not keybinds then\n        keybinds = KeybindLoader.get_job_keybinds(job)\n        -- Add job-specific elements (like BRD song slots), as\n        -- ui_display.get_current_job_keybinds() does for the rendered rows.\n        if keybinds then\n            keybinds = KeybindLoader.add_job_specific_elements(job, keybinds)\n        end\n    end\n\n    if not keybinds then\n        return {\n            spell_keys = {},\n            ja_keys = {},\n            weapon_keys = {},\n            mode_keys = {}\n        }\n    end\n\n    -- Filter out reverse keybinds for cleaner display\n    keybinds = filter_reverse_keybinds(keybinds)\n\n    -- Categorize keybinds\n    local categories = {\n        spell_keys = {},\n        ja_keys = {},\n        weapon_keys = {},\n        mode_keys = {}\n    }\n\n    for _, bind in ipairs(keybinds) do\n        local category = categorize_keybind(bind)\n\n        if category == \"spell\" then\n            table.insert(categories.spell_keys, bind.key)\n        elseif category == \"ja\" then\n            table.insert(categories.ja_keys, bind.key)\n        elseif category == \"weapon\" then\n            table.insert(categories.weapon_keys, bind.key)\n        elseif category == \"mode\" then\n            table.insert(categories.mode_keys, bind.key)\n        end\n    end\n\n    return categories\nend\n\n---============================================================================\n--- MAIN DISPLAY BUILDER FUNCTION\n---============================================================================\n\n--- Build complete display key structure for a job. No row is ever sorted\n--- into the enhancing section: the name stays accepted in the section order\n--- (UI_CONFIG.lua, <JOB>_HUD.lua) and draws nothing.\n--- @param job string The job abbreviation\n--- @param keybinds table|nil Rows already built by the caller (see extract_display_keys)\n--- @return table Complete display structure with all key categories\nfunction UIDisplayBuilder.build_display_structure(job, keybinds)\n    local categories = UIDisplayBuilder.extract_display_keys(job, keybinds)\n    categories.spell_keys = categories.spell_keys or {}\n    categories.ja_keys = categories.ja_keys or {}\n    categories.weapon_keys = categories.weapon_keys or {}\n    categories.mode_keys = categories.mode_keys or {}\n    return categories\nend\n\nreturn UIDisplayBuilder\n", "shared/utils/ui/UI_FORMATTER.lua": "---============================================================================\r\n--- UI Formatter - Text Formatting and Layout Management\r\n---============================================================================\r\n--- Handles all text formatting, headers, alignment, and color formatting\r\n--- for the keybind UI system.\r\n---\r\n--- @file shared/utils/ui/UI_FORMATTER.lua\r\n--- @author ejouanchicot\r\n--- @version 1.0\r\n--- @date Created: 2025-09-26\r\n---============================================================================\r\n\r\nlocal UIFormatter = {}\r\n\r\nlocal UIConfig = _G.UIConfig or {}  -- Set by config_loader.lua (only read by get_statistics)\r\nlocal ColorSystem = require('shared/utils/ui/COLOR_SYSTEM')\r\nlocal UIStyle = require('shared/utils/ui/ui_style')\r\n\r\n---============================================================================\r\n--- HEADER AND TITLE FORMATTING\r\n---============================================================================\r\n\r\n-- Job title mappings\r\nlocal job_titles = {\r\n    BRD = \"Bard Settings\",\r\n    THF = \"Thief Settings\",\r\n    WAR = \"Warrior Settings\",\r\n    PLD = \"Paladin Settings\",\r\n    DNC = \"Dancer Settings\",\r\n    BST = \"Beastmaster Settings\",\r\n    BLM = \"Black Mage Settings\",\r\n    BLU = \"Blue Mage Settings\",\r\n    DRG = \"Dragoon Settings\",\r\n    RDM = \"Red Mage Settings\",\r\n    SCH = \"Scholar Settings\",\r\n    RNG = \"Ranger Settings\",\r\n    COR = \"Corsair Settings\",\r\n    GEO = \"Geomancer Settings\",\r\n    NIN = \"Ninja Settings\",\r\n    RUN = \"Rune Fencer Settings\"\r\n}\r\n\r\n--- Calculate EXACT total UI width by measuring actual lines\r\n--- @param keybinds table List of keybinds\r\n--- @param key_column_width number Calculated key column width\r\n--- @param function_column_width number Calculated function column width\r\n--- @param get_all_values_func function Function to get ALL possible state values (for max width calculation)\r\n--- @return number Exact width for UI (separators, centering, everything)\r\nfunction UIFormatter.calculate_content_width(keybinds, key_column_width, function_column_width, get_all_values_func)\r\n    local max_width = 0\r\n    local layout = UIStyle.get().layout\r\n    local sp = layout.spacing\r\n    local left, gap, gap_value = string.rep(\" \", sp.left), string.rep(\" \", sp.gap), string.rep(\" \", sp.gap_value)\r\n    -- Standard layout: byte length, as it always was (a \"●\" counts 3, which\r\n    -- leaves 2 columns of slack on the right). Exact layouts count columns.\r\n    local measure = sp.exact and UIStyle.display_len or string.len\r\n\r\n    -- Measure header first (same margins and gaps as the rendered lines)\r\n    local formatted_key = string.format(\"%-\" .. key_column_width .. \"s\", \"Key\")\r\n    local formatted_func = string.format(\"%-\" .. function_column_width .. \"s\", \"Function\")\r\n    local header_line = left .. formatted_key .. gap .. formatted_func .. gap_value .. \"Current\"\r\n    max_width = measure(header_line)\r\n\r\n    -- Measure each keybind line with ALL possible values to find absolute maximum width\r\n    if get_all_values_func then\r\n        for _, bind in ipairs(keybinds) do\r\n            -- Get ALL possible values for this state\r\n            local all_values = get_all_values_func(bind.state)\r\n\r\n            local formatted_key_line = string.format(\"%-\" .. key_column_width .. \"s\", UIStyle.display_key(bind.key))\r\n            local formatted_desc_line = string.format(\"%-\" .. function_column_width .. \"s\", bind.desc)\r\n            local prefix = left .. formatted_key_line .. gap .. formatted_desc_line .. gap_value .. layout.bullet .. \" \"\r\n\r\n            -- Test with each possible value to find the longest\r\n            for _, value in ipairs(all_values) do\r\n                max_width = math.max(max_width, measure(prefix .. value))\r\n            end\r\n        end\r\n    end\r\n\r\n    -- Right margin (padding added directly in format strings)\r\n    return max_width + sp.right\r\nend\r\n\r\n--- Create the UI header with title and legend\r\n--- @param job string The job abbreviation\r\n--- @param content_width number Total UI content width for centering\r\n--- @return string Formatted header text\r\nfunction UIFormatter.create_header(job, content_width)\r\n    -- Use global config state instead of local UIConfig\r\n    if not _G.ui_display_config or not _G.ui_display_config.show_header then\r\n        return \"\"\r\n    end\r\n\r\n    local title = job_titles[job] or job .. \" Settings\"\r\n\r\n    local text = \"\"\r\n\r\n    -- Add top margin (empty line with padding and color code for background)\r\n    text = text .. \"\\\\cs(0,0,0)\" .. string.rep(\" \", content_width) .. \"\\\\cr\\n\"\r\n\r\n    -- Center the title (accounting for 2 space left margin already in content_width)\r\n    local title_length = string.len(title)\r\n    local padding = math.floor((content_width - title_length) / 2)\r\n    padding = math.max(2, padding)  -- Minimum 2 for left margin\r\n    local centered_title = string.rep(\" \", padding) .. title\r\n\r\n    -- Title in bright color (right margin added via content_width calculation)\r\n    text = text .. UIStyle.color('title') .. centered_title .. \"  \\\\cr\\n\"\r\n\r\n    -- Separator line under title (with 2 space margins on both sides)\r\n    if content_width then\r\n        text = text .. \"  \" .. UIStyle.color('separator', \"\\\\cs(100,180,255)\") .. string.rep(\"=\", content_width - 4) .. \"  \\\\cr\\n\"\r\n    end\r\n\r\n    -- Symbol legend (optional). Keys written out in words need no legend.\r\n    if _G.ui_display_config and _G.ui_display_config.show_legend\r\n        and UIStyle.get().layout.key_style ~= 'words' then\r\n        local legend_color = UIStyle.color('legend')\r\n        for _, line in ipairs(UIFormatter.legend_lines(UIStyle.get().layout.legend)) do\r\n            text = text .. legend_color .. line .. \"\\\\cr\\n\"\r\n        end\r\n    end\r\n\r\n    return text\r\nend\r\n\r\n--- Legend lines, two items per line with 2 space margins on both sides.\r\n--- The first column is 18 wide (wider when an item needs it).\r\n--- @param items table Legend texts (\"^ = Ctrl\", ...)\r\n--- @return table Lines without color codes\r\nfunction UIFormatter.legend_lines(items)\r\n    local col1_width = 18\r\n    for i = 1, #items, 2 do\r\n        col1_width = math.max(col1_width, string.len(\"● \" .. items[i]) + 3)\r\n    end\r\n    local lines = {}\r\n    for i = 1, #items, 2 do\r\n        if items[i + 1] then\r\n            lines[#lines + 1] = string.format(\"  %-\" .. col1_width .. \"s● %s  \", \"● \" .. items[i], items[i + 1])\r\n        else\r\n            lines[#lines + 1] = \"  ● \" .. items[i] .. \"  \"\r\n        end\r\n    end\r\n    return lines\r\nend\r\n\r\n--- Create column headers with dynamic alignment\r\n--- @param key_column_width number Width of the key column\r\n--- @param function_column_width number Width of the function column\r\n--- @param content_width number Total UI content width for top margin\r\n--- @return string Formatted column headers\r\nfunction UIFormatter.create_column_headers(key_column_width, function_column_width, content_width)\r\n    -- Use global config state instead of local UIConfig\r\n    if not _G.ui_display_config or not _G.ui_display_config.show_column_headers then\r\n        return \"\"\r\n    end\r\n\r\n    local text = \"\"\r\n\r\n    -- Add top margin if NO header (header adds its own margin)\r\n    if not _G.ui_display_config.show_header and content_width then\r\n        text = text .. \"\\\\cs(0,0,0)\" .. string.rep(\" \", content_width) .. \"\\\\cr\\n\"\r\n    end\r\n\r\n    -- Build header with colors (Consolas monospace = safe)\r\n    local formatted_key = string.format(\"%-\" .. key_column_width .. \"s\", \"Key\")\r\n    local formatted_func = string.format(\"%-\" .. function_column_width .. \"s\", \"Function\")\r\n\r\n    -- Multiple colors for header columns (same margins and gaps as the rows)\r\n    local sp = UIStyle.get().layout.spacing\r\n    text = text .. string.rep(\" \", sp.left)\r\n        .. UIStyle.color('column_key') .. formatted_key .. string.rep(\" \", sp.gap)\r\n        .. UIStyle.color('column_function') .. formatted_func .. string.rep(\" \", sp.gap_value)\r\n        .. UIStyle.color('column_current') .. \"Current\" .. string.rep(\" \", sp.right) .. \"\\\\cr\\n\"\r\n\r\n    return text\r\nend\r\n\r\n---============================================================================\r\n--- SECTION TITLE FORMATTING\r\n---============================================================================\r\n\r\n--- Create a centered section title\r\n--- @param title string The section title\r\n--- @param content_width number Total UI content width (optional)\r\n--- @return string Formatted centered title\r\nfunction UIFormatter.create_section_title(title, content_width)\r\n    if not content_width then\r\n        -- Fallback to left-aligned with margin\r\n        return \"    \" .. title  -- 4 space left margin for fallback\r\n    end\r\n\r\n    -- Calculate padding to center the title (accounting for 2 space left margin already in content_width)\r\n    local title_length = string.len(title)\r\n    local padding = math.floor((content_width - title_length) / 2)\r\n\r\n    -- Ensure minimum padding (at least 2 for left margin)\r\n    padding = math.max(2, padding)\r\n\r\n    return string.rep(\" \", padding) .. title\r\nend\r\n\r\n--- Get appropriate section title for job and category\r\n--- @param job string The job abbreviation\r\n--- @param category string The section category (spell, ja, weapon, mode, enhancing)\r\n--- @return string The section title\r\nfunction UIFormatter.get_section_title(job, category)\r\n    local custom = UIStyle.get().layout.section_titles[category]\r\n    if custom then\r\n        return custom\r\n    end\r\n    if category == \"spell\" then\r\n        if job == \"BST\" then\r\n            return \"Pet Abilities\"\r\n        elseif job == \"BRD\" then\r\n            return \"Song Settings\"\r\n        elseif job == \"COR\" then\r\n            return \"Rolls & Quick Draw\"\r\n        else\r\n            return \"Spells\"\r\n        end\r\n    elseif category == \"ja\" then\r\n        if job == \"BRD\" then\r\n            return \"Song Slots\"\r\n        elseif job == \"WAR\" then\r\n            -- WAR fills this section with its weapon-aware WS slots, not JAs\r\n            return \"Weapon Skills\"\r\n        else\r\n            return \"JA\"\r\n        end\r\n    elseif category == \"weapon\" then\r\n        return \"Weapons\"\r\n    elseif category == \"mode\" then\r\n        return \"Modes\"\r\n    elseif category == \"enhancing\" then\r\n        return \"Enhancing\"\r\n    else\r\n        return category:upper()\r\n    end\r\nend\r\n\r\n---============================================================================\r\n--- KEYBIND LINE FORMATTING\r\n---============================================================================\r\n\r\n--- Format a single keybind line with perfect column alignment\r\n--- @param bind table Keybind object {key, desc, state}\r\n--- @param key_column_width number Width for key column alignment\r\n--- @param function_column_width number Width for function column alignment\r\n--- @param get_state_value_func function Function to get state values\r\n--- @param value_column_width number|nil Value column width (value left unpadded when nil)\r\n--- @return string Formatted keybind line\r\nfunction UIFormatter.format_keybind_line(bind, key_column_width, function_column_width, get_state_value_func, value_column_width)\r\n    -- Get current state value\r\n    local value = get_state_value_func(bind.state, bind.key)\r\n\r\n    -- Format with dynamic widths using %-Ns for left-align padding\r\n    local layout = UIStyle.get().layout\r\n    local sp = layout.spacing\r\n    local formatted_key = string.format(\"%-\" .. key_column_width .. \"s\", UIStyle.display_key(bind.key))\r\n    local formatted_desc = string.format(\"%-\" .. function_column_width .. \"s\", bind.desc)\r\n\r\n    local desc_color = UIStyle.color('description')\r\n    -- A key a partner or subjob key covers right now (UI_SECTIONS hud_rows)\r\n    local key_color = bind.conflict and UIStyle.color('conflict')\r\n        or UIStyle.color('key', desc_color)\r\n    local value_color = UIStyle.color('value', ColorSystem.get_value_color(value, bind.desc))\r\n\r\n    -- Pad value to fixed width (if value_column_width provided)\r\n    local formatted_value = value\r\n    if value_column_width then\r\n        local value_padding = value_column_width - (UIStyle.display_len(layout.bullet) + 1)\r\n        formatted_value = string.format(\"%-\" .. value_padding .. \"s\", value)\r\n    end\r\n\r\n    -- Consolas is monospace: color codes don't break the alignment.\r\n    -- Layout: <left>key<gap>desc<gap_value><bullet> value<right>\r\n    local desc_prefix = key_color ~= desc_color and desc_color or \"\"\r\n    return string.rep(\" \", sp.left) .. key_color .. formatted_key .. string.rep(\" \", sp.gap)\r\n        .. desc_prefix .. formatted_desc .. string.rep(\" \", sp.gap_value)\r\n        .. value_color .. layout.bullet .. \" \" .. formatted_value .. string.rep(\" \", sp.right) .. \"\\\\cr\\n\"\r\nend\r\n\r\n---============================================================================\r\n--- UTILITY FUNCTIONS\r\n---============================================================================\r\n\r\n--- Calculate optimal key column width from keybinds\r\n--- @param keybinds table List of keybind objects\r\n--- @return number Optimal column width\r\nfunction UIFormatter.calculate_key_column_width(keybinds)\r\n    local width = 2 -- Minimum width\r\n    for _, bind in ipairs(keybinds) do\r\n        width = math.max(width, string.len(UIStyle.display_key(bind.key)))\r\n    end\r\n    return width\r\nend\r\n\r\n--- Calculate optimal function/description column width from keybinds\r\n--- @param keybinds table List of keybind objects\r\n--- @return number Optimal column width\r\nfunction UIFormatter.calculate_function_column_width(keybinds)\r\n    local width = 8 -- Minimum width (length of \"Function\")\r\n    for _, bind in ipairs(keybinds) do\r\n        width = math.max(width, string.len(bind.desc))\r\n    end\r\n    return width\r\nend\r\n\r\n--- Calculate optimal value column width (max of ALL possible values)\r\n--- @param keybinds table List of keybinds\r\n--- @param get_all_values_func function Function to get ALL possible state values\r\n--- @return number Maximum value width\r\nfunction UIFormatter.calculate_value_column_width(keybinds, get_all_values_func)\r\n    local width = 7  -- \"Current\" header length\r\n    local prefix_width = UIStyle.display_len(UIStyle.get().layout.bullet) + 1\r\n\r\n    if get_all_values_func then\r\n        for _, bind in ipairs(keybinds) do\r\n            -- Get ALL possible values for this state\r\n            local all_values = get_all_values_func(bind.state)\r\n\r\n            -- Find the longest value\r\n            for _, value in ipairs(all_values) do\r\n                local value_width = string.len(value) + prefix_width\r\n                width = math.max(width, value_width)\r\n            end\r\n        end\r\n    end\r\n\r\n    return width\r\nend\r\n\r\n--- Add section separator line with dynamic width\r\n--- @param width number Width for separator\r\n--- @return string Separator line\r\nfunction UIFormatter.create_section_separator(width)\r\n    if not width then\r\n        width = 50  -- Default fallback\r\n    end\r\n    -- Add 2 space margins on both sides and adjust separator width accordingly\r\n    return \"  \" .. UIStyle.color('separator', \"\\\\cs(80,160,255)\") .. string.rep(\"=\", width - 4) .. \"  \\\\cr\\n\"\r\nend\r\n\r\n--- Create colored section header\r\n--- @param title string The section title\r\n--- @param content_width number Total UI content width (optional)\r\n--- @return string Colored section header\r\nfunction UIFormatter.create_colored_section_header(title, content_width)\r\n    local centered_title = UIFormatter.create_section_title(title, content_width)\r\n\r\n    -- Add spacing before section (with background) instead of simple \\n\r\n    local spacing = \"\"\r\n    if content_width then\r\n        spacing = \"\\\\cs(0,0,0)\" .. string.rep(\" \", content_width) .. \"\\\\cr\\n\"\r\n    else\r\n        spacing = \"\\n\"\r\n    end\r\n\r\n    -- Fixed 2 space right margin (symmetrical with left margin in centered_title);\r\n    -- the blank line under the title is dropped in the compact layout.\r\n    local after = UIStyle.get().layout.spacing.title_gap and \"\\n\" or \"\"\r\n    return spacing .. UIStyle.color('section_title') .. centered_title .. \"  \\\\cr\\n\" .. after\r\nend\r\n\r\nreturn UIFormatter\r\n", "shared/utils/ui/UI_LOADER.lua": "---============================================================================\n--- Keybind Configuration Loader - Character-Aware System\n---============================================================================\n--- Loads a job's keybind configuration, <Character>/<job>/keys/<JOB>_KEYBINDS.lua\n--- (CharPaths.module('job', ...), shared/utils/core/char_paths.lua). When it\n--- does not load, the HUD shows no rows: EntryKit.keybind_error has already\n--- said why in the chat.\n---\n--- @file shared/utils/ui/UI_LOADER.lua\n--- @author ejouanchicot\n--- @version 1.0\n--- @date Created: 2025-01-26\n---============================================================================\n\nlocal KeybindLoader = {}\n\n---============================================================================\n--- MAIN LOADING FUNCTION\n---============================================================================\n\n--- Get keybind configuration for the specified job\n--- @param job string The job abbreviation (BRD, WAR, etc.)\n--- @return table|nil Keybind configuration or nil if not found\nfunction KeybindLoader.get_job_keybinds(job)\n    -- Validation: ensure we have a job\n    if not job or job == \"UNK\" then\n        return nil\n    end\n\n    -- Format: war/keys/WAR_KEYBINDS.lua\n    local config_path = require('shared/utils/core/char_paths').module('job', job:upper() .. '_KEYBINDS', job)\n\n    local success, keybind_config = pcall(require, config_path)\n\n    if success and keybind_config then\n        -- If module has get_active_binds() function, use it (supports subjob filtering)\n        if keybind_config.get_active_binds and type(keybind_config.get_active_binds) == 'function' then\n            return keybind_config.get_active_binds()\n        end\n\n        -- Otherwise, return the binds table directly (legacy support)\n        if keybind_config.binds then\n            return keybind_config.binds\n        end\n    end\n\n    -- require failed (missing file OR an error inside the file), or the\n    -- module exposes neither get_active_binds nor binds. The error is not kept.\n    return nil\nend\n\n---============================================================================\n--- SPECIAL ADDITIONS\n---============================================================================\n\n--- Add job-specific display elements (non-keybind items)\n--- Returns a COPY: get_job_keybinds() hands back the config module's own binds\n--- table, which require() caches for the whole session. Appending in place made\n--- the BRD song slots pile up on every redraw (10 slots on the first render,\n--- 20 on the second, ...).\n--- @param job string The job abbreviation\n--- @param keybinds table The existing keybind table\n--- @return table New keybind table with the job's display-only additions\nfunction KeybindLoader.add_job_specific_elements(job, keybinds)\n    local result = {}\n    for i, bind in ipairs(keybinds or {}) do\n        result[i] = bind\n    end\n\n    -- BRD: Add song slot displays\n    if job == \"BRD\" then\n        for i = 1, 5 do\n            table.insert(result, {\n                key = \"\", -- No key, display only\n                desc = \"Slot \" .. i,\n                state = \"BRDSong\" .. i  -- BRDSong1..5 states (BRD_STATES.lua)\n            })\n        end\n    end\n\n    return result\nend\n\n---============================================================================\n--- MODULE EXPORT\n---============================================================================\n\nreturn KeybindLoader\n", "shared/utils/ui/UI_SECTIONS.lua": "---============================================================================\n--- UI Sections - Display Section Rendering Engine\n---============================================================================\n--- Handles rendering of all UI sections (spells, weapons, modes, etc.)\n--- from the key lists built by UI_DISPLAY_BUILDER, with consistent formatting.\n---\n--- @file shared/utils/ui/UI_SECTIONS.lua\n--- @author ejouanchicot\n--- @version 1.0\n--- @date Created: 2025-09-26\n---============================================================================\n\nlocal UISections = {}\n\n-- Captured once when this module loads (set by config_loader.lua). Later\n-- changes to _G.UIConfig or the persisted section_* settings are not seen here.\nlocal UIConfig = _G.UIConfig or {}\n\n-- Provide default sections if not loaded\nif not UIConfig.sections then\n    UIConfig.sections = {\n        spells = true,\n        enhancing = true,\n        job_abilities = true,\n        weapons = true,\n        modes = true\n    }\nend\n\nlocal UIFormatter = require('shared/utils/ui/UI_FORMATTER')\nlocal UIStyle = require('shared/utils/ui/ui_style')\n\n--- The section a row belongs to (UI_DISPLAY_BUILDER.lua categorize).\n--- @param bind table\n--- @return string|nil\nlocal function row_section(bind)\n    local ok, Builder = pcall(require, 'shared/utils/ui/UI_DISPLAY_BUILDER')\n    return ok and Builder and Builder.categorize and Builder.categorize(bind) or nil\nend\n\n---============================================================================\n--- SECTION RENDERING ENGINE\n---============================================================================\n\n--- Render a single section with keybinds\n--- @param section_name string Name of the section (spell, ja, weapon, mode)\n--- @param keys table List of keys for this section\n--- @param keybinds table All keybinds\n--- @param job string Current job\n--- @param key_column_width number Column width for alignment\n--- @param function_column_width number Function column width for alignment\n--- @param get_state_value_func function Function to get state values\n--- @param content_width number Total UI content width for centering\n--- @param value_column_width number Value column width for fixed padding\n--- @return string Rendered section text\nlocal function render_section(section_name, keys, keybinds, job, key_column_width, function_column_width, get_state_value_func, content_width, value_column_width)\n    if not keys or #keys == 0 then\n        return \"\"\n    end\n\n    local text = \"\"\n    local section_found = false\n    local current_subjob = player and player.sub_job or nil\n\n    for _, bind in ipairs(keybinds) do\n        for _, section_key in ipairs(keys) do\n            -- Every row without a key shares the key '': matching on the key\n            -- alone drew each one in every section that had one (BRD's song\n            -- slots under Modes as soon as a mode had no key)\n            if bind.key == section_key and (bind.key ~= '' or row_section(bind) == section_name) then\n                -- A list of subjobs was already filtered by get_active_binds;\n                -- only the single-subjob form is left to test here, for bind\n                -- files that do not go through it.\n                if type(bind.subjob) == 'string' and bind.subjob ~= current_subjob then\n                    break\n                end\n\n                if not section_found then\n                    -- Add section header (centered)\n                    local section_title = UIFormatter.get_section_title(job, section_name)\n                    text = text .. UIFormatter.create_colored_section_header(section_title, content_width)\n                    section_found = true\n                end\n\n                -- Add the keybind line (with fixed value column width)\n                text = text .. UIFormatter.format_keybind_line(bind, key_column_width, function_column_width, get_state_value_func, value_column_width)\n                break\n            end\n        end\n    end\n\n    return text\nend\n\n---============================================================================\n--- MAIN SECTION RENDERING FUNCTIONS\n---============================================================================\n\n--- Render spells section\n--- @param display_structure table Display structure from UIDisplayBuilder\n--- @param keybinds table All keybinds\n--- @param job string Current job\n--- @param key_column_width number Column width for alignment\n--- @param function_column_width number Function column width for alignment\n--- @param get_state_value_func function Function to get state values\n--- @param content_width number Total UI content width\n--- @param value_column_width number Value column width for fixed padding\n--- @return string Rendered spells section\nfunction UISections.render_spells_section(display_structure, keybinds, job, key_column_width, function_column_width, get_state_value_func, content_width, value_column_width)\n    if not UIConfig.sections.spells then\n        return \"\"\n    end\n    return render_section(\"spell\", display_structure.spell_keys, keybinds, job, key_column_width, function_column_width, get_state_value_func, content_width, value_column_width)\nend\n\n--- Render enhancing section (for RDM and similar jobs)\n--- @param display_structure table Display structure from UIDisplayBuilder\n--- @param keybinds table All keybinds\n--- @param job string Current job\n--- @param key_column_width number Column width for alignment\n--- @param function_column_width number Function column width for alignment\n--- @param get_state_value_func function Function to get state values\n--- @param content_width number Total UI content width\n--- @param value_column_width number Value column width for fixed padding\n--- @return string Rendered enhancing section\nfunction UISections.render_enhancing_section(display_structure, keybinds, job, key_column_width, function_column_width, get_state_value_func, content_width, value_column_width)\n    if not UIConfig.sections.enhancing or not display_structure.enhancing_keys then\n        return \"\"\n    end\n\n    return render_section(\"enhancing\", display_structure.enhancing_keys, keybinds, job, key_column_width, function_column_width,\n        get_state_value_func, content_width, value_column_width)\nend\n\n--- Render JA (Job Abilities) section\n--- @param display_structure table Display structure from UIDisplayBuilder\n--- @param keybinds table All keybinds\n--- @param job string Current job\n--- @param key_column_width number Column width for alignment\n--- @param function_column_width number Function column width for alignment\n--- @param get_state_value_func function Function to get state values\n--- @param content_width number Total UI content width\n--- @param value_column_width number Value column width for fixed padding\n--- @return string Rendered JA section\nfunction UISections.render_ja_section(display_structure, keybinds, job, key_column_width, function_column_width, get_state_value_func, content_width, value_column_width)\n    if not UIConfig.sections.job_abilities then\n        return \"\"\n    end\n\n    return render_section(\"ja\", display_structure.ja_keys, keybinds, job, key_column_width, function_column_width, get_state_value_func, content_width, value_column_width)\nend\n\n--- Render weapons section\n--- @param display_structure table Display structure from UIDisplayBuilder\n--- @param keybinds table All keybinds\n--- @param job string Current job\n--- @param key_column_width number Column width for alignment\n--- @param function_column_width number Function column width for alignment\n--- @param get_state_value_func function Function to get state values\n--- @param content_width number Total UI content width\n--- @param value_column_width number Value column width for fixed padding\n--- @return string Rendered weapons section\nfunction UISections.render_weapons_section(display_structure, keybinds, job, key_column_width, function_column_width, get_state_value_func, content_width, value_column_width)\n    if not UIConfig.sections.weapons then\n        return \"\"\n    end\n    return render_section(\"weapon\", display_structure.weapon_keys, keybinds, job, key_column_width, function_column_width, get_state_value_func, content_width, value_column_width)\nend\n\n--- Render modes section\n--- @param display_structure table Display structure from UIDisplayBuilder\n--- @param keybinds table All keybinds\n--- @param job string Current job\n--- @param key_column_width number Column width for alignment\n--- @param function_column_width number Function column width for alignment\n--- @param get_state_value_func function Function to get state values\n--- @param content_width number Total UI content width\n--- @param value_column_width number Value column width for fixed padding\n--- @return string Rendered modes section\nfunction UISections.render_modes_section(display_structure, keybinds, job, key_column_width, function_column_width, get_state_value_func, content_width, value_column_width)\n    if not UIConfig.sections.modes then\n        return \"\"\n    end\n    return render_section(\"mode\", display_structure.mode_keys, keybinds, job, key_column_width, function_column_width, get_state_value_func, content_width, value_column_width)\nend\n\n---============================================================================\n--- COMPLETE UI RENDERING\n---============================================================================\n\n--- Rows as the HUD draws them. A common entry with no state (console\n--- command, partner roll) never gets a row, even when it shares a key with a\n--- job state. A row whose key is in conflict right now (two entries apply on\n--- it, KeybindManager / key_conflicts.lua) is a copy flagged `conflict`: the\n--- formatter draws its key in the conflict color. The keys themselves are\n--- left as configured; the chat names the entry that is bound.\n--- @param keybinds table Active keybinds, in bind order\n--- @return table The same list when nothing changes, else a new list\nlocal function hud_rows(keybinds)\n    local conflict = {}\n    local ok, KeybindManager = pcall(require, 'shared/utils/keybinds/keybind_manager')\n    if ok and KeybindManager and KeybindManager.conflict_keys then conflict = KeybindManager.conflict_keys() end\n    local rows, changed = {}, false\n    for _, bind in ipairs(keybinds) do\n        if bind._common and not bind.state and not bind.section then\n            changed = true\n        elseif bind.key and conflict[bind.key] then\n            local copy = {}\n            for k, v in pairs(bind) do copy[k] = v end\n            copy.conflict = true\n            rows[#rows + 1] = copy\n            changed = true\n        else\n            rows[#rows + 1] = bind\n        end\n    end\n    return changed and rows or keybinds\nend\n\n--- The rows a section will actually draw. Binds with no state (the common\n--- keys, \"Alts: follow me (toggle)\"...) are in the job's list but in no\n--- section: counting them sized the label column for a row never shown.\n--- @param display_structure table Section key lists from UIDisplayBuilder\n--- @param keybinds table All keybinds\n--- @return table The shown rows (all rows when no section lists a key)\nlocal function shown_rows(display_structure, keybinds)\n    local in_section = {}\n    for _, field in ipairs({\"spell_keys\", \"ja_keys\", \"weapon_keys\", \"mode_keys\", \"enhancing_keys\"}) do\n        for _, key in ipairs(display_structure[field] or {}) do in_section[key] = true end\n    end\n    local rows = {}\n    for _, bind in ipairs(keybinds) do\n        if bind.key and in_section[bind.key] then rows[#rows + 1] = bind end\n    end\n    return #rows > 0 and rows or keybinds\nend\n\n--- The first section opens with one blank line. With nothing above it (no\n--- header, no column headers) that line is the HUD's top margin: replace it\n--- with layout.margin_top blank lines.\n--- @param body string Rendered sections\n--- @param blank string One blank background line\n--- @param lines number Blank lines wanted on top\n--- @return string\nlocal function top_margin(body, blank, lines)\n    local cfg = _G.ui_display_config\n    if cfg and (cfg.show_header or cfg.show_column_headers) then return body end\n    if lines == 1 or body:sub(1, #blank) ~= blank then return body end\n    return string.rep(blank, lines) .. body:sub(#blank + 1)\nend\n\n--- HUD bucket -> section renderer (same arguments for all five).\nlocal SECTION_RENDERERS = {\n    spell = UISections.render_spells_section,\n    enhancing = UISections.render_enhancing_section,\n    ja = UISections.render_ja_section,\n    weapon = UISections.render_weapons_section,\n    mode = UISections.render_modes_section,\n}\n\n--- Render all sections for a complete UI display\n--- @param display_structure table Display structure from UIDisplayBuilder\n--- @param keybinds table All keybinds\n--- @param job string Current job\n--- @param get_state_value_func function Function to get current state value\n--- @param get_all_values_func function Function to get all possible state values (for width)\n--- @return string Complete rendered UI text\nfunction UISections.render_complete_ui(display_structure, keybinds, job, get_state_value_func, get_all_values_func)\n    -- Rows the player hid (layout.hide_rows) take no room in the widths either\n    keybinds = UIStyle.ordered_rows(UIStyle.visible_rows(hud_rows(keybinds)))\n    local shown = shown_rows(display_structure, keybinds)\n\n    -- Calculate optimal column widths and EXACT content width using ALL possible values\n    local key_column_width = UIFormatter.calculate_key_column_width(shown)\n    local function_column_width = UIFormatter.calculate_function_column_width(shown)\n    local value_column_width = UIFormatter.calculate_value_column_width(shown, get_all_values_func)\n    local content_width = UIFormatter.calculate_content_width(shown, key_column_width, function_column_width, get_all_values_func)\n\n    local text = \"\"\n\n    -- Header (pass content_width for centering title)\n    text = text .. UIFormatter.create_header(job, content_width)\n\n    -- Separator only when both header and legend are shown\n    if not _G.ui_display_config or not _G.ui_display_config.show_header then\n        -- No separator needed\n    elseif _G.ui_display_config.show_legend and UIStyle.get().layout.key_style ~= 'words' then\n        -- Separator after legend\n        text = text .. UIFormatter.create_section_separator(content_width)\n    end\n\n    -- Column headers (pass content_width for top margin)\n    text = text .. UIFormatter.create_column_headers(key_column_width, function_column_width, content_width)\n\n    -- Sections in the player's order (the job's <JOB>_HUD.lua, else\n    -- layout.section_order), no separators between them\n    local layout = UIStyle.get().layout\n    local blank = \"\\\\cs(0,0,0)\" .. string.rep(\" \", content_width) .. \"\\\\cr\\n\"\n    local body = \"\"\n    for _, bucket in ipairs(UIStyle.section_order(job)) do\n        body = body .. SECTION_RENDERERS[bucket](display_structure, keybinds, job, key_column_width,\n            function_column_width, get_state_value_func, content_width, value_column_width)\n    end\n    text = text .. top_margin(body, blank, layout.spacing.margin_top)\n\n    -- Universal Commands (footer)\n    text = text .. UISections.render_commands_footer(job, content_width)\n\n    -- Bottom margin if NO footer (footer adds its own margin)\n    if not _G.ui_display_config or not _G.ui_display_config.show_footer then\n        text = text .. string.rep(blank, layout.spacing.margin_bottom)\n    end\n    if layout.spacing.exact then\n        -- The texts box draws a final newline as one more empty line (the\n        -- \"fixed ~19 px of border\" measured in ui_section_toggles.lua)\n        text = text:gsub(\"\\n$\", \"\")\n    end\n\n    return text\nend\n\n--- Render simple command footer\n--- @param job string Current job\n--- @param content_width number Dynamic content width\n--- @return string Rendered commands footer\nfunction UISections.render_commands_footer(job, content_width)\n    -- Use global config state instead of local UIConfig\n    if not _G.ui_display_config or not _G.ui_display_config.show_footer then\n        return \"\"\n    end\n\n    local command_text = \"//gs c ui\"\n    local command_length = string.len(command_text)\n    local padding = math.floor((content_width - command_length) / 2)\n    padding = math.max(2, padding)  -- Minimum 2 for left margin\n\n    local centered_command = string.rep(\" \", padding) .. command_text\n\n    -- Add fixed 2 space right margin (symmetrical with left padding)\n    local footer_text = UIFormatter.create_section_separator(content_width) .. UIStyle.color('footer') .. centered_command .. \"  \\\\cr\\n\"\n\n    -- Add bottom margin (empty line with padding and color code for background)\n    footer_text = footer_text .. \"\\\\cs(0,0,0)\" .. string.rep(\" \", content_width) .. \"\\\\cr\\n\"\n\n    return footer_text\nend\n\nreturn UISections\n", "shared/utils/ui/hud_job_config.lua": "---============================================================================\n--- HUD Job Config - a job's own HUD settings, in its config folder\n---============================================================================\n--- <Character>/<job>/display/<JOB>_HUD.lua holds what the HUD does on that\n--- job only: its section order and its row order. Each list, when not\n--- empty, replaces UI_CONFIG.lua's layout.section_order / layout.row_order\n--- (the defaults of every job) on that job.\n---\n---   return {\n---       section_order = {'weapons', 'modes', 'spells'},\n---       row_order = {'TreasureMode', 'HybridMode'},\n---   }\n---\n--- Read once per job and per load. //gs c ui order / roworder rewrite it\n--- whole through render(): the explanation, the job's own states (read in\n--- its _KEYBINDS.lua) and both lists, the one not changed kept.\n---\n--- @file    shared/utils/ui/hud_job_config.lua\n--- @author  ejouanchicot\n--- @version 1.2\n--- @date    Created: 2026-09-27\n---============================================================================\n\nlocal HudJobConfig = {}\n\nlocal HEADER = [[\n-- HUD settings of this job only. UI_CONFIG.lua holds the defaults of every\n-- job (layout.section_order, layout.row_order); a list here that is not\n-- empty replaces the default on this job. Empty or missing = the default.\n--\n-- section_order: order of the HUD sections on this job. Names: spells,\n--   abilities, weapons, modes (enhancing is accepted and stays empty). Those\n--   left out follow in the standard order.\n-- row_order: order of the rows inside each section on this job. The rows\n--   named come first in their section, in this order; the others follow in\n--   the order of the job's _KEYBINDS file. Names = the states as written in\n--   the _KEYBINDS file (capitals included), or keys.\n--\n-- Example:\n--   section_order = {'weapons', 'modes', 'spells'},\n--   row_order = {'MainWeapon', 'SubWeapon', 'TreasureMode', 'HybridMode'},\n--\n-- In game (this job, or name one: //gs c ui order THF weapons modes):\n--   //gs c ui order weapons modes spells          this job's section order\n--   //gs c ui roworder TreasureMode HybridMode    this job's row order\n--   //gs c ui order reset / roworder reset        back to the default\n--   //gs c ui order all ... / roworder all ...    the default of every job\n-- A command puts the names typed first and keeps the others after them, in\n-- their order (a job without its own list starts from the default one).\n-- The commands rewrite this file; editing it by hand works too (//gs reload).\n]]\n\nlocal FIELDS = {'section_order', 'row_order'}\n\n--- <Character>/<job>/display/<JOB>_HUD.lua, or nil before the player is known.\n--- @param job string Job code\n--- @return string|nil\nfunction HudJobConfig.path(job)\n    if not (job and player and player.name and windower and windower.addon_path) then return nil end\n    return require('shared/utils/core/char_paths').writable('job', job:upper() .. '_HUD.lua', job)\nend\n\nlocal function cache()\n    _G._hud_job_config = _G._hud_job_config or {}\n    return _G._hud_job_config\nend\n\n--- The job's settings table (empty when the file is missing or broken).\n--- @param job string\n--- @return table\nfunction HudJobConfig.get(job)\n    local key = job and job:upper()\n    if not key then return {} end\n    local known = cache()[key]\n    if known ~= nil then return known end\n    local path = HudJobConfig.path(key)\n    -- a broken file is named in chat, and the HUD keeps its default order (module_cache.lua, read_char_file)\n    local label = path and path:match('data/(.-)%.lua$')\n    local data = require('shared/utils/core/module_cache').read_char_file(path, label or (key .. '_HUD')) or {}\n    cache()[key] = data\n    return data\nend\n\n--- One of the job's own lists ('section_order' / 'row_order'), or nil when\n--- it has none (the default applies).\n--- @param job string\n--- @param field string\n--- @return table|nil\nfunction HudJobConfig.list(job, field)\n    local list = HudJobConfig.get(job)[field]\n    if type(list) == 'table' and #list > 0 then return list end\n    return nil\nend\n\n--- The job's own row order, or nil.\n--- @param job string\n--- @return table|nil\nfunction HudJobConfig.row_order(job)\n    return HudJobConfig.list(job, 'row_order')\nend\n\n--- The job's own section order, or nil.\n--- @param job string\n--- @return table|nil\nfunction HudJobConfig.section_order(job)\n    return HudJobConfig.list(job, 'section_order')\nend\n\n---============================================================================\n--- FILE TEXT\n---============================================================================\n\nlocal function lua_list(list)\n    local names = {}\n    for i, name in ipairs(list) do\n        names[i] = \"'\" .. tostring(name):gsub(\"'\", \"\\\\'\") .. \"'\"\n    end\n    return '{' .. table.concat(names, ', ') .. '}'\nend\n\n--- The state names of a job's keybind file, in file order (no duplicates).\n--- @param keybinds_path string|nil\n--- @return table\nlocal function job_states(keybinds_path)\n    local file = keybinds_path and io.open(keybinds_path, 'r')\n    if not file then return {} end\n    local states, seen = {}, {}\n    for line in file:lines() do\n        -- A comment line (\"-- Format: {... state = \"state_name\" ...}\") is not a key\n        if not line:match('^%s*%-%-') then\n            for name in line:gmatch('state%s*=%s*[\"\\']([%w_]+)[\"\\']') do\n                if not seen[name] then\n                    seen[name] = true\n                    states[#states + 1] = name\n                end\n            end\n        end\n    end\n    file:close()\n    return states\nend\n\n--- \"-- States of this job (THF_KEYBINDS.lua): A, B, ...\" cut at 76 columns.\nlocal function states_comment(job, states)\n    if #states == 0 then return '' end\n    local lines = {}\n    local line = ('-- States of this job (%s_KEYBINDS.lua):'):format(job:upper())\n    for i, name in ipairs(states) do\n        local word = ' ' .. name .. (i < #states and ',' or '')\n        if #line + #word > 76 then\n            lines[#lines + 1] = line\n            line = '--  ' .. word\n        else\n            line = line .. word\n        end\n    end\n    lines[#lines + 1] = line\n    lines[#lines + 1] = '-- Also on every job: CombatMode, AutoMedicine and the common keys.'\n    return table.concat(lines, '\\n') .. '\\n'\nend\n\n--- The whole file text: explanation, this job's states, the two lists (a\n--- missing or empty one written commented out).\n--- @param job string\n--- @param data table {section_order =, row_order =}\n--- @param keybinds_path string|nil The job's _KEYBINDS.lua, for its states\n--- @return string\nfunction HudJobConfig.render(job, data, keybinds_path)\n    local lines = {}\n    for _, name in ipairs(FIELDS) do\n        local value = data[name]\n        if type(value) == 'table' and #value > 0 then\n            lines[#lines + 1] = ('    %s = %s,'):format(name, lua_list(value))\n        else\n            lines[#lines + 1] = ('    -- %s = {},'):format(name)\n        end\n    end\n    return HEADER .. states_comment(job, job_states(keybinds_path))\n        .. 'return {\\n' .. table.concat(lines, '\\n') .. '\\n}\\n'\nend\n\n--- Write one of the job's lists (nil = none: the default applies); the\n--- other list of the file is kept.\n--- @param job string\n--- @param field string 'section_order' or 'row_order'\n--- @param list table|nil\n--- @return boolean saved\n--- @return string|nil error\nfunction HudJobConfig.set_list(job, field, list)\n    local current = HudJobConfig.get(job)\n    local path = HudJobConfig.path(job)\n    local file = path and io.open(path, 'w')\n    if not file then return false, 'cannot write ' .. tostring(path) end\n    local data = {}\n    for _, name in ipairs(FIELDS) do data[name] = current[name] end\n    data[field] = list\n    -- the job's keys are not beside its HUD file (<job>/keys/ against <job>/display/): asked for by name; the\n    -- same folder only in an old layout\n    local keybinds_path = require('shared/utils/core/char_paths').file('job', job:upper() .. '_KEYBINDS.lua', job)\n        or path:gsub('_HUD%.lua$', '_KEYBINDS.lua')\n    file:write(HudJobConfig.render(job, data, keybinds_path))\n    file:close()\n    cache()[job:upper()] = nil\n    return true\nend\n\nreturn HudJobConfig\n", "shared/utils/ui/ui_style.lua": "---============================================================================\n--- UI Style - the player's HUD and chat look, read from UI_CONFIG.lua\n---============================================================================\n--- Resolves the optional `layout`, `colors` and `chat` tables of\n--- <Character>/_common/display/UI_CONFIG.lua into one checked table. Every option\n--- left out keeps the look the HUD had before these options existed, so a\n--- config without them renders exactly as it always did.\n---\n--- A wrong value (unknown section, bad color...) is reported once in chat\n--- and replaced by its default: a typo must never cost the player the HUD.\n---\n--- @file shared/utils/ui/ui_style.lua\n--- @author ejouanchicot\n--- @version 1.0\n--- @date Created: 2026-09-25\n---============================================================================\n\nlocal UIStyle = {}\n\n--- Section names a player writes -> HUD bucket used by the renderer.\nlocal SECTION_NAMES = {\n    spells = 'spell', spell = 'spell',\n    enhancing = 'enhancing',\n    abilities = 'ja', ability = 'ja', ja = 'ja',\n    weapons = 'weapon', weapon = 'weapon',\n    modes = 'mode', mode = 'mode',\n}\n\n--- Historical render order, used for any section the player's order omits.\nlocal DEFAULT_ORDER = {'spell', 'enhancing', 'ja', 'weapon', 'mode'}\n\n--- Column spacing. `normal` is the historical layout.\nlocal SPACING = {\n    normal  = {left = 2, gap = 4, gap_value = 4, right = 2, title_gap = true,\n               margin_top = 1, margin_bottom = 1, padding = 0},\n    compact = {left = 1, gap = 2, gap_value = 2, right = 1, title_gap = false,\n               margin_top = 0, margin_bottom = 0, padding = 4},\n}\n\n--- Historical colors. nil = no override (key: same as description; value:\n--- automatic per-value colors from COLOR_SYSTEM).\nlocal DEFAULT_COLORS = {\n    title = {255, 255, 255},\n    section_title = {120, 220, 255},\n    key = nil,\n    description = {180, 180, 180},\n    value = nil,\n    legend = {255, 215, 0},\n    separator = nil,\n    footer = {128, 128, 128},\n    column_key = {100, 180, 255},\n    column_function = {120, 200, 255},\n    column_current = {140, 220, 255},\n    conflict = {255, 80, 80},  -- key a partner / subjob key covers right now\n}\n\nlocal COLOR_NAMES = {\n    title = true, section_title = true, key = true, description = true,\n    value = true, legend = true, separator = true, footer = true,\n    column_key = true, column_function = true, column_current = true,\n    conflict = true,\n}\n\n--- Historical legend: the four key modifiers.\nlocal DEFAULT_LEGEND = {'^ = Ctrl', '! = Alt', '@ = Windows', '~ = Shift'}\n\n--- Bullet names -> symbol. The FFXI chat line cannot send symbols like \"●\",\n--- so `//gs c ui bullet` takes a name. The symbols are from the WGL4 set,\n--- which Consolas (the HUD's font) covers.\nlocal BULLETS = {\n    dot = '●', circle = '○', square = '■', smallsquare = '▪', triangle = '►',\n    diamond = '◊', arrow = '→', gt = '>', dash = '-', star = '*', none = '',\n}\n--- Name of a bullet symbol (\"●\" -> \"dot\"), for the chat, which cannot print it.\n--- @param bullet string|nil Symbol or name as written in UI_CONFIG.lua\n--- @return string\nfunction UIStyle.bullet_name(bullet)\n    bullet = bullet or '●'\n    for name, symbol in pairs(BULLETS) do\n        if symbol == bullet then return name end\n    end\n    return bullet:find('[\\128-\\255]') and '(symbol)' or bullet\nend\n\nUIStyle.BULLET_NAMES = {'dot', 'circle', 'square', 'smallsquare', 'triangle', 'diamond', 'arrow', 'gt', 'dash', 'star', 'none'}\n\nlocal cache_source, cache = nil, nil\n\n---============================================================================\n--- VALIDATION HELPERS\n---============================================================================\n\nlocal function warn(problems, text)\n    problems[#problems + 1] = text\nend\n\n--- {r, g, b} with each part 0-255, else nil.\nlocal function valid_rgb(value)\n    if type(value) ~= 'table' or #value ~= 3 then return false end\n    for i = 1, 3 do\n        local n = value[i]\n        if type(n) ~= 'number' or n < 0 or n > 255 then return false end\n    end\n    return true\nend\n\nlocal function resolve_order(raw, problems)\n    local order, seen = {}, {}\n    if raw ~= nil and type(raw) ~= 'table' then\n        warn(problems, 'layout.section_order must be a list')\n        raw = nil\n    end\n    for _, name in ipairs(raw or {}) do\n        local bucket = SECTION_NAMES[tostring(name):lower()]\n        if not bucket then\n            warn(problems, ('layout.section_order: unknown section \"%s\"'):format(tostring(name)))\n        elseif not seen[bucket] then\n            order[#order + 1] = bucket\n            seen[bucket] = true\n        end\n    end\n    for _, bucket in ipairs(DEFAULT_ORDER) do\n        if not seen[bucket] then order[#order + 1] = bucket end\n    end\n    return order\nend\n\n--- state/key -> bucket. Enhancing is left out: no state is ever sorted there.\nlocal function resolve_moves(raw, problems)\n    local moves = {}\n    if raw == nil then return moves end\n    if type(raw) ~= 'table' then\n        warn(problems, 'layout.move_to_section must be a table')\n        return moves\n    end\n    for name, section in pairs(raw) do\n        local bucket = SECTION_NAMES[tostring(section):lower()]\n        if not bucket or bucket == 'enhancing' then\n            warn(problems, ('layout.move_to_section.%s: unknown section \"%s\"'):format(tostring(name), tostring(section)))\n        else\n            moves[tostring(name):lower()] = bucket\n        end\n    end\n    return moves\nend\n\n--- A list of state names or keys -> position (1 = first).\n--- A list of state names or keys -> position (1 = first). Names are kept\n--- in lower case: a row is found whatever the case typed (abyproc = AbyProc).\nlocal function rank_of(list)\n    local rank = {}\n    for i, name in ipairs(list) do\n        local key = tostring(name):lower()\n        if rank[key] == nil then rank[key] = i end\n    end\n    return rank\nend\n\n--- The value a {name = value} table (names in lower case) gives a row, by\n--- its state first, else its key.\nlocal function by_row(map, bind)\n    return (bind.state and map[bind.state:lower()]) or (bind.key and map[bind.key:lower()]) or nil\nend\n\n--- layout.row_order: a list for every job, or {all = {...}, THF = {...}}\n--- (`all` is the default; a job's own list, when not empty, replaces it on\n--- that job; job codes in any case).\n--- @return table {all = rank, jobs = {JOB = rank}}\nlocal function resolve_row_order(raw, problems)\n    local order = {all = {}, jobs = {}}\n    if raw == nil then return order end\n    if type(raw) ~= 'table' then\n        warn(problems, 'layout.row_order must be a list, or {all = {...}, THF = {...}}')\n        return order\n    end\n    order.all = rank_of(raw)\n    for name, list in pairs(raw) do\n        if type(name) == 'string' then\n            if type(list) ~= 'table' then\n                warn(problems, ('layout.row_order.%s must be a list'):format(name))\n            elseif name:lower() == 'all' then\n                order.all = rank_of(list)\n            elseif #list > 0 then\n                -- An empty list leaves the job on `all`\n                order.jobs[name:upper()] = rank_of(list)\n            end\n        end\n    end\n    return order\nend\n\nlocal function resolve_set(raw, label, problems)\n    local set = {}\n    if raw == nil then return set end\n    if type(raw) ~= 'table' then\n        warn(problems, label .. ' must be a list')\n        return set\n    end\n    for _, name in ipairs(raw) do set[tostring(name):lower()] = true end\n    return set\nend\n\n--- Legend texts: a list of up to 8 texts, else the standard four.\nlocal function resolve_legend(raw, problems)\n    if raw == nil then return DEFAULT_LEGEND end\n    if type(raw) ~= 'table' or #raw == 0 or #raw > 8 then\n        warn(problems, 'layout.legend must be a list of 1 to 8 texts')\n        return DEFAULT_LEGEND\n    end\n    for _, item in ipairs(raw) do\n        if type(item) ~= 'string' then\n            warn(problems, 'layout.legend must be a list of texts')\n            return DEFAULT_LEGEND\n        end\n    end\n    return raw\nend\n\nlocal function resolve_titles(raw, problems)\n    local titles = {}\n    if raw == nil then return titles end\n    if type(raw) ~= 'table' then\n        warn(problems, 'layout.section_titles must be a table')\n        return titles\n    end\n    for name, title in pairs(raw) do\n        local bucket = SECTION_NAMES[tostring(name):lower()]\n        if not bucket or type(title) ~= 'string' then\n            warn(problems, ('layout.section_titles.%s ignored'):format(tostring(name)))\n        else\n            titles[bucket] = title\n        end\n    end\n    return titles\nend\n\nlocal function resolve_colors(raw, problems)\n    local colors = {}\n    for name, value in pairs(DEFAULT_COLORS) do colors[name] = value end\n    if raw == nil then return colors end\n    if type(raw) ~= 'table' then\n        warn(problems, 'colors must be a table')\n        return colors\n    end\n    for name, value in pairs(raw) do\n        if not COLOR_NAMES[name] then\n            warn(problems, ('colors.%s: unknown color'):format(tostring(name)))\n        elseif value ~= nil and not valid_rgb(value) then\n            warn(problems, ('colors.%s must be {r, g, b} with 0-255 values'):format(tostring(name)))\n        else\n            colors[name] = value\n        end\n    end\n    return colors\nend\n\n--- chat.colors: palette colors (gray, green...) and MessageColors constants\n--- (success, error...) -> FFXI chat code 1-255.\nlocal function resolve_chat_colors(raw, problems)\n    local colors = {}\n    if raw == nil then return colors end\n    if type(raw) ~= 'table' then\n        warn(problems, 'chat.colors must be a table')\n        return colors\n    end\n    local ChatPalette = require('shared/utils/messages/chat_palette')\n    local MessageColors = require('shared/utils/messages/message_colors')\n    for name, code in pairs(raw) do\n        local key = tostring(name):lower()\n        if not ChatPalette.NAMES[key] and not MessageColors.SETTABLE[key] then\n            warn(problems, ('chat.colors.%s: unknown color'):format(tostring(name)))\n        elseif type(code) ~= 'number' or code < 1 or code > 255 then\n            warn(problems, ('chat.colors.%s must be an FFXI chat color 1-255'):format(tostring(name)))\n        else\n            colors[key] = math.floor(code)\n        end\n    end\n    return colors\nend\n\n--- A number within [low, high] from the chat table, or nil (+ warning).\nlocal function chat_number(raw, name, low, high, problems)\n    local n = raw[name]\n    if n == nil then return nil end\n    if type(n) == 'number' and n >= low and n <= high then return math.floor(n) end\n    warn(problems, ('chat.%s must be a number from %d to %d'):format(name, low, high))\n    return nil\nend\n\n--- The separator character: plain characters only.\nlocal function chat_separator_char(raw, problems)\n    local char = raw.separator_char\n    if char == nil then return '=' end\n    -- ASCII only: FFXI's chat does not render UTF-8 (a \"─\" prints as garbage)\n    if type(char) == 'string' and char ~= '' and not char:find('[\\128-\\255]') then return char end\n    warn(problems, 'chat.separator_char must be plain characters such as = - * ~ #')\n    return '='\nend\n\nlocal ROLL_STYLES = {full = true, compact = true, line = true}\n\n--- Roll details in their standard order, and the names the player may type.\nlocal ROLL_PARTS = {'party', 'lucky', 'eleven', 'bust'}\nlocal ROLL_PART_NAMES = {party = 'party', pt = 'party', lucky = 'lucky', luck = 'lucky',\n    eleven = 'eleven', ['11'] = 'eleven', bust = 'bust'}\n\n--- rolls.order: the details the player named first, in that order, then\n--- the others in the standard order.\nlocal function resolve_roll_order(raw, problems)\n    local order, seen = {}, {}\n    if raw ~= nil and type(raw) ~= 'table' then\n        warn(problems, 'rolls.order must be a list')\n        raw = nil\n    end\n    for _, name in ipairs(raw or {}) do\n        local part = ROLL_PART_NAMES[tostring(name):lower()]\n        if not part then\n            warn(problems, ('rolls.order: unknown detail \"%s\" (party, lucky, eleven, bust)'):format(tostring(name)))\n        elseif not seen[part] then\n            order[#order + 1] = part\n            seen[part] = true\n        end\n    end\n    for _, part in ipairs(ROLL_PARTS) do\n        if not seen[part] then order[#order + 1] = part end\n    end\n    return order\nend\n\n--- rolls: how a COR roll result is shown (roll_messages.lua). style =\n--- full / compact / line; remote_style = the same choices plus 'same' and\n--- 'off', for a roll another box sends here (roll_share.lua); lucky, party,\n--- bust, eleven = each detail on or off; order = the details' order.\nlocal function resolve_rolls(raw, problems)\n    if raw ~= nil and type(raw) ~= 'table' then\n        warn(problems, 'rolls must be a table')\n        raw = nil\n    end\n    raw = raw or {}\n    local style = raw.style or 'full'\n    if not ROLL_STYLES[style] then\n        warn(problems, ('rolls.style \"%s\": use full, compact or line'):format(tostring(style)))\n        style = 'full'\n    end\n    local remote = raw.remote_style or 'same'\n    if remote ~= 'same' and remote ~= 'off' and not ROLL_STYLES[remote] then\n        warn(problems, ('rolls.remote_style \"%s\": use same, full, compact, line or off'):format(tostring(remote)))\n        remote = 'same'\n    end\n    return {style = style, remote_style = remote, lucky = raw.lucky ~= false, party = raw.party ~= false,\n            bust = raw.bust ~= false, eleven = raw.eleven ~= false,\n            order = resolve_roll_order(raw.order, problems)}\nend\n\nlocal function resolve_chat(raw, problems)\n    if raw ~= nil and type(raw) ~= 'table' then\n        warn(problems, 'chat must be a table')\n        raw = nil\n    end\n    raw = raw or {}\n    return {\n        separators = raw.separators ~= false,\n        separator_char = chat_separator_char(raw, problems),\n        separator_color = chat_number(raw, 'separator_color', 1, 255, problems),\n        width = chat_number(raw, 'width', 20, 150, problems),\n        job_tag = raw.job_tag ~= false,\n        colors = resolve_chat_colors(raw.colors, problems),\n    }\nend\n\n--- A whole-number option within [low, high], or `fallback` when unset or wrong.\nlocal function resolve_number(raw, name, low, high, fallback, problems)\n    local n = raw[name]\n    if n == nil then return fallback end\n    if type(n) ~= 'number' or n < low or n > high then\n        warn(problems, ('layout.%s must be a number from %d to %d'):format(name, low, high))\n        return fallback\n    end\n    return math.floor(n)\nend\n\n--- Spacing of the chosen layout, with the player's values on top:\n--- column_gap = key -> label, value_gap = label -> value (defaults to\n--- column_gap when only that one is set), margin_top/margin_bottom = blank\n--- lines above/below the rows, margin_side = spaces left and right of the rows,\n--- padding = pixels of background around the text.\nlocal function resolve_spacing(raw, problems)\n    local base = raw.compact and SPACING.compact or SPACING.normal\n    local gap = resolve_number(raw, 'column_gap', 1, 10, base.gap, problems)\n    local value_fallback = raw.column_gap ~= nil and gap or base.gap_value\n    local side_left = resolve_number(raw, 'margin_side', 0, 3, base.left, problems)\n    local side_right = raw.margin_side ~= nil and side_left or base.right\n    return {\n        left = side_left, right = side_right, title_gap = base.title_gap,\n        gap = gap,\n        gap_value = resolve_number(raw, 'value_gap', 1, 10, value_fallback, problems),\n        margin_top = resolve_number(raw, 'margin_top', 0, 3, base.margin_top, problems),\n        margin_bottom = resolve_number(raw, 'margin_bottom', 0, 3, base.margin_bottom, problems),\n        -- Exact geometry: no final newline, and widths counted in displayed\n        -- characters (\"●\" is 3 bytes, one column). The standard layout keeps\n        -- its historical slack; compact or a player-set margin gets exact.\n        exact = raw.compact == true or raw.margin_bottom ~= nil or raw.margin_side ~= nil,\n        padding = resolve_number(raw, 'padding', 0, 20, base.padding, problems),\n    }\nend\n\nlocal function resolve_layout(raw, problems)\n    if raw ~= nil and type(raw) ~= 'table' then\n        warn(problems, 'layout must be a table')\n        raw = nil\n    end\n    raw = raw or {}\n    local key_style = raw.key_style or 'symbols'\n    if key_style ~= 'symbols' and key_style ~= 'words' then\n        warn(problems, ('layout.key_style \"%s\": use \"symbols\" or \"words\"'):format(tostring(key_style)))\n        key_style = 'symbols'\n    end\n    local bullet = raw.bullet or '●'\n    if type(bullet) ~= 'string' then\n        warn(problems, 'layout.bullet must be a text')\n        bullet = '●'\n    end\n    bullet = BULLETS[bullet:lower()] or bullet\n    return {\n        section_order = resolve_order(raw.section_order, problems),\n        spacing = resolve_spacing(raw, problems),\n        move_to_section = resolve_moves(raw.move_to_section, problems),\n        hide_rows = resolve_set(raw.hide_rows, 'layout.hide_rows', problems),\n        row_order = resolve_row_order(raw.row_order, problems),\n        section_titles = resolve_titles(raw.section_titles, problems),\n        legend = resolve_legend(raw.legend, problems),\n        key_style = key_style,\n        bullet = bullet,\n    }\nend\n\nlocal function report(problems)\n    if #problems == 0 then return end\n    local ok, MessageFormatter = pcall(require, 'shared/utils/messages/message_formatter')\n    if not ok or not MessageFormatter or not MessageFormatter.show_warning then return end\n    for _, problem in ipairs(problems) do\n        MessageFormatter.show_warning('UI_CONFIG.lua: ' .. problem .. ' (default used)')\n    end\nend\n\n---============================================================================\n--- PUBLIC API\n---============================================================================\n\n--- The resolved style. Re-resolved only when UI_CONFIG.lua was reloaded\n--- (a new _G.UIConfig table), so problems are reported once per load.\n--- @return table {layout = {...}, colors = {...}, chat = {...}}\nfunction UIStyle.get()\n    local source = rawget(_G, 'UIConfig') or {}\n    if cache and cache_source == source then return cache end\n    local style, problems = UIStyle.resolve(source)\n    cache, cache_source = style, source\n    report(problems)\n    return cache\nend\n\n--- Resolve a config table without touching the cache or the chat: used to\n--- check a value typed in game before it is applied.\n--- @param source table A UI_CONFIG-shaped table\n--- @return table style\n--- @return table problems List of problem texts (empty when all is valid)\nfunction UIStyle.resolve(source)\n    local problems = {}\n    local style = {\n        layout = resolve_layout(source.layout, problems),\n        colors = resolve_colors(source.colors, problems),\n        chat = resolve_chat(source.chat, problems),\n        rolls = resolve_rolls(source.rolls, problems),\n    }\n    return style, problems\nend\n\n--- Forget the resolved style: the next get() reads _G.UIConfig again. For a\n--- change made in place (in-game ui commands keep the same table).\nfunction UIStyle.invalidate()\n    cache, cache_source = nil, nil\nend\n\n--- \"\\\\cs(r,g,b)\" for a style color, or `fallback` when the color is unset.\n--- @param name string Color name (key, description, section_title...)\n--- @param fallback string|nil Returned when the color is nil\n--- @return string\nfunction UIStyle.color(name, fallback)\n    local rgb = UIStyle.get().colors[name]\n    if not rgb then return fallback or '' end\n    return ('\\\\cs(%d,%d,%d)'):format(rgb[1], rgb[2], rgb[3])\nend\n\n--- The key as the HUD shows it: \"^f1\", or \"CTRL+F1\" with key_style words.\n--- @param key string Windower key\n--- @return string\nfunction UIStyle.display_key(key)\n    if not key or key == '' or UIStyle.get().layout.key_style ~= 'words' then\n        return key\n    end\n    local ok, MessageCore = pcall(require, 'shared/utils/messages/message_core')\n    if not ok or not MessageCore.convert_key_display then return key end\n    return MessageCore.convert_key_display(key)\nend\n\n--- Rows the player did not hide (layout.hide_rows names a state or a key).\n--- @param keybinds table List of bind entries\n--- @return table The same list when nothing is hidden, else a filtered copy\nfunction UIStyle.visible_rows(keybinds)\n    local hidden = UIStyle.get().layout.hide_rows\n    if next(hidden) == nil then return keybinds end\n    local shown = {}\n    for _, bind in ipairs(keybinds) do\n        if not by_row(hidden, bind) then\n            shown[#shown + 1] = bind\n        end\n    end\n    return shown\nend\n\n--- The section order of `job` (default: the job played now): its own list\n--- in <Character>/<job>/display/<JOB>_HUD.lua when not empty, else layout.section_order.\n--- @param job string|nil\n--- @return table Section buckets in order\nfunction UIStyle.section_order(job)\n    job = job or (player and player.main_job)\n    local ok, HudJobConfig = pcall(require, 'shared/utils/ui/hud_job_config')\n    local own = ok and HudJobConfig and job and HudJobConfig.section_order(job)\n    if own then return resolve_order(own, {}) end\n    return UIStyle.get().layout.section_order\nend\n\n--- Rows in the player's order (layout.row_order): the rows it names come\n--- first, in its order; the others keep the file order after them. Each\n--- section keeps only its own rows, so this orders every section at once.\n--- @param keybinds table List of bind entries\n--- @return table The same list when no order is set, else a sorted copy\nfunction UIStyle.ordered_rows(keybinds)\n    local order = UIStyle.get().layout.row_order\n    local job = player and player.main_job\n    -- The job's own list (<Character>/<job>/display/<JOB>_HUD.lua) replaces the default\n    local ok, HudJobConfig = pcall(require, 'shared/utils/ui/hud_job_config')\n    local own = ok and HudJobConfig and job and HudJobConfig.row_order(job)\n    local rank = own and rank_of(own) or (job and order.jobs[job]) or order.all\n    if next(rank) == nil then return keybinds end\n    local indexed = {}\n    for i, bind in ipairs(keybinds) do\n        local r = by_row(rank, bind) or math.huge\n        indexed[i] = {bind = bind, rank = r, pos = i}\n    end\n    table.sort(indexed, function(a, b)\n        if a.rank ~= b.rank then return a.rank < b.rank end\n        return a.pos < b.pos\n    end)\n    local sorted = {}\n    for i, item in ipairs(indexed) do sorted[i] = item.bind end\n    return sorted\nend\n\n--- Bucket the player forced for this bind, or nil.\n--- @param bind table Bind entry\n--- @return string|nil spell/ja/weapon/mode\nfunction UIStyle.forced_section(bind)\n    local moves = UIStyle.get().layout.move_to_section\n    return by_row(moves, bind)\nend\n\n--- Display width of a text (UTF-8 multi-byte symbols count as one).\n--- @param text string\n--- @return number\nfunction UIStyle.display_len(text)\n    local _, count = tostring(text):gsub('[^\\128-\\191]', '')\n    return count\nend\n\nreturn UIStyle\n", "scripts/atelier/hud_harness.lua": "---============================================================================\n--- HUD harness - GearSwap's own HUD code, run outside the game\n---============================================================================\n--- Renders the keybind HUD the way shared/utils/ui/ui_display.lua does in game\n--- (UI_DISPLAY_BUILDER + UI_SECTIONS, the player's UI_CONFIG.lua, its saved\n--- ui_settings.lua, UI_COLOR_CONFIG.lua and <JOB>_HUD.lua), from the rows and\n--- values of an Atelier export instead of the live game. Used by the Atelier\n--- page (atelier/app/js/hud_preview.js, Lua in WebAssembly) and by\n--- scripts/atelier/gen_hud_sources.py (which records the files it needs).\n---\n--- Globals it reads, set by the caller before dofile:\n---   HUD_ROOT  the folder holding data/ (with its last slash)\n---   HUD_IN    {char, job, sub, keys = {{key, desc, state, ...}}, modes = {[name] = {current, values}}}\n--- It sets HUD_OUT = {text = the HUD's text, meta = {font, size, bold, stroke..., bg...},\n--- sections = {{bucket, title}} in their order, rows = {{desc, state}} in their order}.\n---\n--- @file    scripts/atelier/hud_harness.lua\n--- @author  ejouanchicot\n--- @date    Created: 2026-10-30\n---============================================================================\n\nlocal IN = HUD_IN\n-- nothing is ever written: ui_settings.lua saves its file when it lines it up with UI_CONFIG.lua, and a preview run\n-- on the real folder must not touch the player's saved/ui_settings.lua\nlocal io_open = io.open\nio.open = function(path, mode)\n    if mode and mode:find('[wa+]') then\n        return {write = function(self) return self end, close = function() return true end, flush = function() end, lines = function() return function() end end}\n    end\n    return io_open(path, mode)\nend\npackage.path = HUD_ROOT .. 'data/?.lua;' .. package.path\nplayer = {main_job = IN.job, sub_job = IN.sub, name = IN.char}\nwindower = {addon_path = HUD_ROOT, ffxi = {get_player = function() return player end, get_info = function() return {} end},\n    get_dir = function() return {} end, add_to_chat = function() end, send_command = function() end,\n    register_event = function() return 0 end, unregister_event = function() end}\nadd_to_chat = function() end\nsend_command = function() end\n\n-- the player's UI_CONFIG.lua, as config_loader.lua reads it (shared/utils/config/config_loader.lua)\nlocal ok, UIConfig = pcall(dofile, HUD_ROOT .. 'data/' .. IN.char .. '/_common/display/UI_CONFIG.lua')\nif not ok or type(UIConfig) ~= 'table' then UIConfig = {} end\n_G.UIConfig = UIConfig\nlocal Settings = require('shared/config/ui_settings')\n_G.ui_display_config = {\n    enabled             = Settings.get_enabled(),\n    show_header         = Settings.get_show_header(),\n    show_legend         = Settings.get_show_legend(),\n    show_column_headers = Settings.get_show_column_headers(),\n    show_footer         = Settings.get_show_footer(),\n}\n\nlocal Builder = require('shared/utils/ui/UI_DISPLAY_BUILDER')\nlocal Sections = require('shared/utils/ui/UI_SECTIONS')\nlocal keybinds = IN.keys\nlocal value = function(state) local m = state and IN.modes[state] return m and tostring(m.current) or '' end\nlocal values = function(state) local m = state and IN.modes[state] return m and m.values or {} end\nlocal text = Sections.render_complete_ui(Builder.build_display_structure(IN.job, keybinds), keybinds, IN.job, value, values)\n\n-- what the page needs to know what a click or a drag in the preview touches: the sections in their order with their\n-- titles, the rows in their order with their labels (ui_style.lua section_order / ordered_rows)\nlocal UIStyle, Formatter = require('shared/utils/ui/ui_style'), require('shared/utils/ui/UI_FORMATTER')\nlocal order, rows = {}, {}\nfor i, bucket in ipairs(UIStyle.section_order(IN.job)) do order[i] = {bucket = bucket, title = Formatter.get_section_title(IN.job, bucket)} end\nfor i, bind in ipairs(UIStyle.ordered_rows(UIStyle.visible_rows(keybinds))) do rows[i] = {desc = tostring(bind.desc or ''), state = bind.state or bind.key or ''} end\nlocal s, txt = _G.UI_SETTINGS or {}, UIConfig.text or {}\nlocal stroke, flags = txt.stroke or {}, UIConfig.flags or {}\nHUD_OUT = {text = text, meta = {\n    font = s.font_name or txt.font or 'Consolas', size = s.font_size or txt.size or 10, bold = flags.bold == true,\n    stroke_width = stroke.width or 0, stroke_alpha = stroke.alpha or 255,\n    stroke = {stroke.red or 0, stroke.green or 0, stroke.blue or 0},\n    bg = {s.bg_r or 15, s.bg_g or 15, s.bg_b or 35, s.bg_a or 180}, bg_visible = s.bg_visible ~= false,\n    enabled = _G.ui_display_config.enabled ~= false,\n}, sections = order, rows = rows}\n-- the caller writes the answer: files can be written again once the HUD is drawn\nio.open = io_open\n"};
